B.aUI=s(["\u0628\u0639\u062f \u0623\u0646 \u0646\u0642\u0636 \u064a\u0647\u0648\u062f \u0628\u0646\u064a \u0627\u0644\u0646\u0636\u064a\u0631 \u0639\u0647\u062f\u064e\u0647\u0645 \u0645\u0639 \u0627\u0644\u0646\u0628\u064a \ufdfa\u060c \u0648\u0623\u0631\u0634\u062f\u0648\u0627 \u0627\u0644\u0623\u0639\u062f\u0627\u0621 \u0639\u0644\u0649 \u0645\u0648\u0627\u0637\u0646\u0650 \u0627\u0644\u0636\u0639\u0641 \u0641\u064a \u0623\u0637\u0631\u0627\u0641 \u0627\u0644\u0645\u062f\u064a\u0646\u0629\u060c \u0648\u062a\u062d\u0627\u0644\u0641\u0648\u0627 \u0645\u0639 \u0631\u0623\u0633 \u0627\u0644\u0645\u0646\u0627\u0641\u0642\u064a\u0646 \u0627\u0628\u0646 \u0633\u0644\u0648\u0644\u060c \u0623\u0645\u0631\u064e \u0627\u0644\u0646\u0628\u064a \ufdfa \u0628\u0625\u062c\u0644\u0627\u0626\u0647\u0645 \u0639\u0646 \u0627\u0644\u0645\u062f\u064a\u0646\u0629. \u0641\u0643\u0627\u0646\u062a \u062a\u0644\u0643 \u0627\u0644\u063a\u0632\u0648\u0629 \u0627\u0646\u0641\u0631\u0627\u062c\u064b\u0627 \u0643\u0628\u064a\u0631\u064b\u0627\u060c \u0625\u0630 \u0627\u0646\u062a\u0642\u0644\u064e \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u0648\u0646 \u0645\u0646 \u0645\u0633\u0627\u0643\u0646\u0650 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0625\u0644\u0649 \u062f\u0648\u0631\u0650 \u0628\u0646\u064a \u0627\u0644\u0646\u0636\u064a\u0631.","\u0648\u064a\u0648\u0645 \u062a\u0648\u0632\u064a\u0639 \u0627\u0644\u063a\u0646\u0627\u0626\u0645 \u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0644\u0644\u0623\u0646\u0635\u0627\u0631: \u0644\u064a\u0633 \u0644\u0650\u0625\u062e\u0648\u064e\u0627\u0646\u0643\u064f\u0645 \u0645\u0646 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u0650\u064a\u0646 \u0623\u0645\u0648\u064e\u0627\u0644\u060c \u0641\u0625\u0650\u0646 \u0634\u0650\u0626\u062a\u064f\u0645 \u0642\u0633\u064e\u0645\u062a\u064f\u0645 \u0647\u064e\u0630\u0650\u0647\u0650 \u0648\u0623\u0645\u0648\u064e\u0627\u0644\u064e\u0643\u064f\u0645 \u0628\u064a\u0646\u0643\u064f\u0645 \u0648\u0628\u064a\u0646\u064e\u0647\u064f\u0645 \u062c\u0645\u064a\u0639\u064b\u0627\u060c \u0648\u064e\u0625\u0650\u0646 \u0634\u0650\u0626\u062a\u064f\u0645 \u0623\u0645\u0633\u064e\u0643\u062a\u064f\u0645 \u0623\u0645\u0648\u064e\u0627\u0644\u064e\u0643\u064f\u0645 \u0648\u064e\u0642\u0633\u064e\u0645\u062a\u064f \u0647\u064e\u0630\u0650\u0647\u0650 \u0641\u0650\u064a\u0647\u0650\u0645 \u062e\u0627\u0635\u0629\u064b.","\u0641\u0642\u0627\u0644 \u0627\u0644\u0623\u0646\u0635\u0627\u0631: \u0628\u0644 \u0627\u0642\u0633\u0650\u0645 \u0647\u064e\u0630\u0650\u0647\u0650 \u0641\u0650\u064a\u0647\u0650\u0645 \u0648\u064e\u0627\u0642\u0633\u0650\u0645 \u0644\u064e\u0647\u064f\u0645 \u0645\u0650\u0646 \u0623\u0645\u0648\u064e\u0627\u0644\u0650\u0646\u0627 \u0645\u064e\u0627 \u0634\u0650\u0626\u062a.","\u0641\u0646\u0632\u0644\u062a \u0627\u0644\u0622\u064a\u0629: \ufd3f\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u064a\u0646\u064e \u062a\u064e\u0628\u064e\u0648\u0651\u064e\u0621\u064f\u0648\u0627 \u0627\u0644\u062f\u0651\u0627\u0631\u064e \u0648\u064e\u0627\u0644\u0625\u064a\u0645\u0627\u0646\u064e \u0645\u0650\u0646 \u0642\u064e\u0628\u0644\u0650\u0647\u0650\u0645 \u064a\u064f\u062d\u0650\u0628\u0651\u0648\u0646\u064e \u0645\u064e\u0646 \u0647\u0627\u062c\u064e\u0631\u064e \u0625\u0650\u0644\u064e\u064a\u0647\u0650\u0645 \u0648\u064e\u0644\u0627 \u064a\u064e\u062c\u0650\u062f\u0648\u0646\u064e \u0641\u064a \u0635\u064f\u062f\u0648\u0631\u0650\u0647\u0650\u0645 \u062d\u0627\u062c\u064e\u0629\u064b \u0645\u0650\u0645\u0651\u0627 \u0623\u0648\u062a\u0648\u0627 \u0648\u064e\u064a\u064f\u0624\u062b\u0650\u0631\u0648\u0646\u064e \u0639\u064e\u0644\u0649 \u0623\u064e\u0646\u0641\u064f\u0633\u0650\u0647\u0650\u0645 \u0648\u064e\u0644\u064e\u0648 \u0643\u0627\u0646\u064e \u0628\u0650\u0647\u0650\u0645 \u062e\u064e\u0635\u0627\u0635\u064e\u0629\u064c \u0648\u064e\u0645\u064e\u0646 \u064a\u0648\u0642\u064e \u0634\u064f\u062d\u0651\u064e \u0646\u064e\u0641\u0633\u0650\u0647\u0650 \u0641\u064e\u0623\u064f\u0648\u0644\u0626\u0650\u0643\u064e \u0647\u064f\u0645\u064f \u0627\u0644\u0645\u064f\u0641\u0644\u0650\u062d\u0648\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u062d\u0634\u0631"],t.s)
