B.aya=s(["\u0627\u0633\u062a\u0628\u0634\u0631\u064e \u0623\u0628\u0648 \u0628\u0643\u0631\u064d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0628\u0645\u0627 \u0631\u0623\u0649 \u0645\u0646 \u0633\u064f\u0645\u0648\u0651\u0650 \u062e\u064f\u0644\u0642\u0650 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0648\u0625\u064a\u062b\u0627\u0631\u0650\u0647\u0645 \u0644\u0625\u062e\u0648\u0627\u0646\u0650\u0647\u0645 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646\u060c \u0641\u0627\u0645\u062a\u0644\u0623 \u0642\u0644\u0628\u064f\u0647 \u062d\u0645\u062f\u064b\u0627 \u0644\u0644\u0647 \u0639\u0644\u0649 \u0645\u0627 \u0623\u0643\u0631\u0645 \u0627\u0644\u0644\u0647 \u0628\u0647 \u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0629\u064e \u0645\u0646 \u0631\u062c\u0627\u0644\u064d \u0622\u062b\u064e\u0631\u0648\u0627 \u0627\u0644\u062f\u0651\u0650\u064a\u0646\u064e \u0639\u0644\u0649 \u0627\u0644\u062f\u0646\u064a\u0627\u060c \u0648\u0623\u0631\u0633\u064e\u0648\u0627 \u0623\u062e\u0648\u0629\u064b \u0635\u0627\u062f\u0642\u0629\u064b \u0644\u0627 \u062a\u0639\u0631\u0641 \u0623\u0646\u0627\u0646\u064a\u0629\u064b \u0648\u0644\u0627 \u0634\u064f\u062d\u0651\u064b\u0627.","\u0647\u0646\u0627\u0644\u0643\u064e \u0627\u0646\u0637\u0644\u0642 \u0644\u0633\u0627\u0646\u064f\u0647 \u0628\u0627\u0644\u062b\u0646\u0627\u0621 \u0639\u0644\u064a\u0647\u0645\u060c \u0645\u0639\u062a\u0631\u0650\u0641\u064b\u0627 \u0628\u0641\u0636\u0644\u0650\u0647\u0645\u060c \u0648\u0645\u0634\u0628\u0651\u0650\u0647\u064b\u0627 \u062d\u0627\u0644\u064e\u0647\u0645 \u0628\u062d\u0627\u0644\u0650 \u0627\u0644\u0643\u0631\u0627\u0645\u0650 \u0645\u0646 \u0627\u0644\u0639\u0631\u0628\u0650 \u0627\u0644\u0630\u064a\u0646 \u0639\u0638\u064f\u0645 \u0646\u064f\u0628\u0644\u064f\u0647\u0645 \u0648\u0627\u0634\u062a\u0647\u0631\u062a \u0645\u0622\u062b\u0631\u064f\u0647\u0645\u060c \u0641\u0642\u0627\u0644:","\u062c\u064e\u0632\u0627\u0643\u0645\u064f \u0627\u0644\u0644\u0647 \u064a\u0627 \u0645\u064e\u0639\u0634\u0631 \u0627\u0644\u0623\u0646\u0635\u064e\u0627\u0631 \u062e\u064a\u0631\u064b\u0627\u060c \u0641\u0648\u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u064e\u0627 \u0645\u0650\u062b\u0644\u064f\u0646\u0627 \u0648\u0645\u0650\u062b\u0644\u0643\u064f\u0645 \u0625\u0644\u0627 \u0643\u0645\u062b\u0644 \u0627\u0644\u0637\u0641\u064a\u0644 \u0627\u0644\u063a\u0646\u0648\u0650\u064a\u0651\u064f \u0625\u0630 \u064a\u0642\u0648\u0644:","\u062c\u064e\u0632\u064e\u0649 \u0627\u0644\u0644\u0651\u064e\u0647\u064f \u0639\u064e\u0646\u0651\u064e\u0627 \u062c\u0639\u0641\u0631\u064b\u0627 \u062d\u064a\u0646 \u0623\u0632\u0644\u064e\u0641\u062a .. \u0628\u0650\u0646\u0627 \u0646\u064e\u0639\u0644\u064f\u0646\u064e\u0627 \u0641\u0650\u064a \u0627\u0644\u0648\u0627\u0637\u0626\u0650\u064a\u0646\u064e \u0641\u0632\u064e\u0644\u062a\u0650","\u0623\u064e\u0628\u064e\u0648\u0627 \u0623\u064e\u0646 \u064a\u064e\u0645\u064e\u0644\u0651\u064f\u0648\u0646\u064e\u0627 \u0648\u064e\u0644\u0648 \u0623\u0646\u0651\u064e \u0623\u0645\u0651\u064e\u0646\u0627 .. \u062a\u064f\u0644\u0627\u0642\u0650\u064a \u0627\u0644\u0630\u0650\u064a \u064a\u064e\u0644\u0642\u0648\u0646 \u0645\u0650\u0646\u0651\u064e\u0627 \u0644\u0645\u0644\u0651\u064e\u062a\u0650","\u0641\u064e\u0630\u0648 \u0627\u0644\u0645\u0627\u0644\u0650 \u0645\u064e\u0648\u0641\u0648\u0631\u064c \u0648\u064e\u0643\u064f\u0644\u0651\u064f \u0645\u064f\u0639\u064e\u0635\u0651\u064e\u0628\u064d .. \u0625\u0650\u0644\u0649 \u062d\u064f\u062c\u0631\u0627\u062a\u064d \u0623\u064e\u062f\u0641\u064e\u0623\u064e\u062a \u0648\u0623\u0638\u0644\u0651\u064e\u062a\u0650","\u0633\u0646\u062c\u0632\u064a \u0628\u0625\u062d\u0633\u0627\u0646\u0650 \u0627\u0644\u0623\u064a\u0627\u062f\u064a \u0627\u0644\u062a\u064a .. \u0645\u064e\u0636\u064e\u062a \u0644\u0647\u0627 \u0639\u0650\u0646\u062f\u0646\u0627 \u0643\u0628\u064e\u0651\u0631\u064e\u062a \u0648\u0623\u0647\u064e\u0644\u0651\u062a\u0650","\u0648\u0645\u0627 \u0623\u0639\u0638\u0645 \u0637\u064a\u0628\u0629\u064e \u0646\u0641\u0648\u0633\u0650 \u0627\u0644\u0623\u0646\u0635\u0627\u0631\u060c \u0625\u0630 \u0622\u0648\u064e\u0648\u0627 \u0625\u062e\u0648\u0627\u0646\u0647\u0645 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0628\u0642\u0644\u0648\u0628\u064d \u0631\u0627\u0636\u064a\u0629\u060c \u0648\u0628\u064a\u0648\u062a\u064d \u0645\u0641\u062a\u0648\u062d\u0629\u060c \u0648\u0623\u0645\u0648\u0627\u0644\u064d \u0645\u0642\u0633\u0648\u0645\u0629\u060c \u0648\u062c\u0648\u0627\u0631\u064d \u0622\u0645\u0646\u061b \u0641\u0645\u0627 \u0636\u062c\u0631\u0648\u0627 \u0648\u0644\u0627 \u0645\u0644\u0651\u0648\u0627\u060c \u0648\u0644\u0648 \u0623\u0646 \u0623\u0645\u0651\u064b\u0627 -\u0648\u0647\u064a \u0645\u0646\u0628\u0639 \u0627\u0644\u0631\u062d\u0645\u0629- \u0644\u064e\u0642\u0650\u064a\u062a \u0645\u0627 \u0644\u064e\u0642\u064f\u0648\u0627 \u0644\u064e\u0636\u0627\u0642\u062a \u0648\u0645\u064e\u0644\u0651\u064e\u062a\u060c \u0641\u0630\u0644\u0643 \u0627\u0644\u0648\u0641\u0627\u0621 \u0627\u0644\u0630\u064a \u064a\u062a\u062c\u0627\u0648\u0632 \u062d\u062f\u0648\u062f \u0627\u0644\u0639\u064f\u0631\u0641 \u0648\u0627\u0644\u0639\u0627\u062f\u0629\u060c \u0648\u0627\u0644\u0625\u064a\u062b\u0627\u0631 \u0627\u0644\u0630\u064a \u064a\u062a\u0631\u0641\u0651\u0639 \u0639\u0646 \u062d\u0638\u0648\u0638 \u0627\u0644\u0646\u0641\u0633 \u0648\u0645\u062a\u0627\u0639 \u0627\u0644\u062f\u0646\u064a\u0627."],t.s)
B.VI=new A.a("B2_C4_T4","\u0627\u0644\u0635\u062f\u064a\u0642 \u0648\u0623\u064e\u0628\u0644\u064e\u063a \u0645\u0627 \u0642\u0650\u064a\u0644 \u0641\u064a \u0627\u0644\u0648\u064e\u0641\u0627\u0621",B.aya)
B.aRZ=s(["\u0623\u0645\u0627 \u0641\u064a \u0627\u0644\u062d\u064f\u062f\u064a\u0628\u064a\u0629\u060c \u062d\u064a\u0646 \u0628\u062f\u062a \u0628\u0646\u0648\u062f \u0627\u0644\u0635\u0644\u062d \u062b\u0642\u064a\u0644\u0629\u064b \u0639\u0644\u0649 \u0627\u0644\u0646\u0641\u0648\u0633\u060c \u0648\u0643\u0627\u0646 \u0638\u0627\u0647\u0631\u0647\u0627 \u0643\u064e\u0633\u0631\u0629 \u0648\u0636\u0639\u0641\u060c \u0644\u0643\u0646\u0651\u064e \u0623\u0628\u0627 \u0628\u0643\u0631\u064d \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0631\u0623\u0649 \u0645\u0627 \u0644\u0645 \u062a\u0631\u0647 \u0627\u0644\u0623\u0628\u0635\u0627\u0631\u060c \u0648\u0641\u0647\u0650\u0645 \u0639\u0645\u0642 \u0627\u0644\u062d\u0643\u0645\u0629 \u0641\u064a \u0642\u0631\u0627\u0631\u0627\u062a \u0627\u0644\u0646\u0628\u064a \ufdfa.","\u062b\u0645 \u0648\u0642\u0641 \u064a\u064f\u062c\u064a\u0628 \u0639\u0645\u0631 \u0628\u0646 \u0627\u0644\u062e\u0637\u0627\u0628 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u0648\u0647\u0648 \u064a\u0642\u0648\u0644: \u064a\u0627 \u0623\u0628\u0627 \u0628\u0643\u0631\u060c \u0623\u0644\u064a\u0633 \u0647\u0630\u0627 \u0646\u0628\u064a\u0651\u064e \u0627\u0644\u0644\u0647 \u062d\u0642\u0651\u064b\u0627\u061f \u0642\u0627\u0644: \u0628\u0644\u0649. \u0642\u0627\u0644: \u0623\u0644\u0633\u0646\u0627 \u0639\u0644\u0649 \u0627\u0644\u062d\u0642\u060c \u0648\u0639\u062f\u0648\u0651\u0646\u0627 \u0639\u0644\u0649 \u0627\u0644\u0628\u0627\u0637\u0644\u061f \u0642\u0627\u0644: \u0628\u0644\u0649. \u0642\u0627\u0644: \u0641\u0644\u0645\u064e \u0646\u0639\u0637\u064a \u0627\u0644\u062f\u0646\u064a\u0651\u0629 \u0641\u064a \u062f\u064a\u0646\u0646\u0627 \u0625\u0630\u0646\u061f \u0642\u0627\u0644: \u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u062c\u0644\u060c \u0625\u0646\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0648\u0644\u064a\u0633 \u064a\u0639\u0635\u064a \u0631\u0628\u0647\u060c \u0648\u0647\u0648 \u0646\u0627\u0635\u0631\u0647\u060c \u0641\u0627\u0633\u062a\u0645\u0633\u0643 \u0628\u063a\u0631\u0632\u0647\u060c \u0641\u0648\u0627\u0644\u0644\u0647\u060c \u0625\u0646\u0647 \u0639\u0644\u0649 \u0627\u0644\u062d\u0642.","\u0642\u0627\u0644 \u0639\u0645\u0631: \u0623\u0644\u064a\u0633 \u0643\u0627\u0646 \u064a\u062d\u062f\u062b\u0646\u0627 \u0623\u0646\u0627 \u0633\u0646\u0623\u062a\u064a \u0627\u0644\u0628\u064a\u062a \u0648\u0646\u0637\u0648\u0641 \u0628\u0647\u061f \u0642\u0627\u0644: \u0628\u0644\u0649\u060c \u0623\u0641\u0623\u062e\u0628\u0631\u0643 \u0623\u0646\u0643 \u062a\u0623\u062a\u064a\u0647 \u0627\u0644\u0639\u0627\u0645\u061f \u0642\u0627\u0644: \u0644\u0627. \u0642\u0627\u0644: \u0641\u0625\u0646\u0643 \u0622\u062a\u064a\u0647 \u0648\u0645\u0637\u0648\u0641 \u0628\u0647.","\u064a\u0642\u0648\u0644 \u0639\u0645\u0631: \u0641\u0639\u0645\u0644\u062a\u064f \u0644\u0630\u0644\u0643 \u0623\u0639\u0645\u0627\u0644\u064b\u0627 \u0645\u0646 \u0627\u0644\u0635\u062f\u0642\u0629 \u0648\u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0627\u0644\u0635\u064a\u0627\u0645\u060c \u0645\u062e\u0627\u0641\u0629\u064b \u0645\u0646 \u0643\u0644\u0627\u0645\u064a \u064a\u0648\u0645\u0626\u0630.","\u0625\u0646 \u0627\u0644\u0635\u062f\u064a\u0642 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0643\u0627\u0646 \u064a\u0632\u0646\u064f \u0627\u0644\u0623\u0645\u0648\u0631\u064e \u0628\u0645\u064a\u0632\u0627\u0646 \u0627\u0644\u0646\u0628\u0648\u0629\u060c \u064a\u0641\u0647\u0645 \u0633\u064f\u0646\u064e\u0646 \u0627\u0644\u062a\u062f\u0631\u0651\u062c \u0648\u0627\u0644\u062a\u0645\u0643\u064a\u0646 \u0628\u0645\u0646\u0637\u0642 \u0627\u0644\u0648\u062d\u064a \u0644\u0627 \u0628\u0631\u062f\u0651\u0627\u062a \u0627\u0644\u0641\u0639\u0644\u060c \u0641\u062b\u0628\u062a \u062d\u064a\u0646 \u062a\u0631\u062f\u062f \u063a\u064a\u0631\u0647\u060c \u0648\u0644\u0645 \u064a\u062a\u0644\u0639\u062b\u0645 \u0641\u064a \u0627\u0644\u0631\u062f \u0639\u0644\u0649 \u0639\u0645\u0631\u060c \u0648\u0647\u0648 \u064a\u0642\u0648\u0644 \u0644\u0647: \u0623\u064a\u0647\u0627 \u0627\u0644\u0631\u062c\u0644\u060c \u0627\u0633\u062a\u0645\u0633\u0643 \u0628\u063a\u0631\u0632\u0647."],t.s)
