B.aNZ=s(["\u0645\u0627 \u0625\u0646 \u0628\u0644\u063a \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u062e\u0628\u0631 \u0627\u062c\u062a\u0645\u0627\u0639 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0641\u064a \u0633\u0642\u064a\u0641\u0629 \u0628\u0646\u064a \u0633\u0627\u0639\u062f\u0629\u060c \u062d\u062a\u0649 \u0623\u062f\u0631\u0643\u0648\u0627 \u062e\u0637\u0648\u0631\u0629 \u0627\u0646\u0641\u0635\u0627\u0644 \u0627\u0644\u0642\u0631\u0627\u0631\u060c \u0641\u0633\u0627\u0631\u0639 \u0623\u0628\u0648 \u0628\u0643\u0631 \u0648\u0639\u0645\u0631 \u0648\u0623\u0628\u0648 \u0639\u0628\u064a\u062f\u0629 \u0625\u0644\u0649 \u0627\u0644\u0633\u0642\u064a\u0641\u0629 \u0644\u062a\u062f\u0627\u0631\u0643 \u0627\u0644\u0645\u0648\u0642\u0641.","\u0643\u0627\u0646 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u062b\u0644\u0627\u062b\u0629 \u0631\u0636\u0648\u0627\u0646 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0645\u060c \u0645\u0646 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0631\u0623\u064a \u0648\u0627\u0644\u0645\u0634\u0648\u0631\u0629 \u0628\u064a\u0646 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646\u060c \u0648\u0647\u0648 \u0645\u0627 \u064a\u064f\u0635\u062f\u0651\u0642\u0647 \u0642\u0648\u0644 \u0623\u0645 \u0627\u0644\u0645\u0624\u0645\u0646\u064a\u0646 \u0639\u0627\u0626\u0634\u0629 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0627: \u0644\u0648 \u0627\u0633\u062a\u062e\u0644\u0641 \u0627\u0644\u0646\u0628\u064a \u0623\u062d\u062f\u064b\u0627 \u0644\u0627\u0633\u062a\u062e\u0644\u0641 \u0623\u0628\u0627 \u0628\u0643\u0631\u064d\u060c \u0641\u0642\u064a\u0644 \u0644\u0647\u0627: \u062b\u0645 \u0645\u0646 \u0628\u0639\u062f\u0647\u061f \u0642\u0627\u0644\u062a: \u0639\u0645\u0631\u060c \u062b\u0645 \u0642\u064a\u0644: \u0645\u0646 \u0628\u0639\u062f \u0639\u0645\u0631\u061f \u0642\u0627\u0644\u062a: \u0623\u0628\u0648 \u0639\u0628\u064a\u062f\u0629 - \u0631\u0648\u0627\u0647 \u0645\u0633\u0644\u0645.","\u0648\u062d\u064a\u0646 \u062f\u062e\u0644\u0648\u0627 \u0627\u0644\u0633\u0642\u064a\u0641\u0629\u060c \u0642\u0627\u0645 \u0623\u062d\u062f \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0644\u0645 \u062a\u064f\u0633\u0645\u0651\u0647 \u0627\u0644\u0631\u0648\u0627\u064a\u0627\u062a\u060c \u0648\u064a\u064f\u0631\u062c\u062d \u0623\u0646\u0647 \u062b\u0627\u0628\u062a \u0628\u0646 \u0642\u064a\u0633\u060c \u0627\u0641\u062a\u062a\u062d \u0643\u0644\u0627\u0645\u0647 \u0628\u0627\u0644\u062b\u0646\u0627\u0621 \u0639\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u062b\u0645 \u0642\u0627\u0644: \u0646\u062d\u0646 \u0623\u0646\u0635\u0627\u0631 \u0627\u0644\u0644\u0647 \u0648\u0643\u062a\u064a\u0628\u0629 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u0623\u0646\u062a\u0645 \u0631\u0647\u0637 \u0645\u0646\u0651\u0627\u060c \u0623\u064a: \u0625\u0634\u0627\u0631\u0629 \u0625\u0644\u0649 \u0642\u0644\u0651\u0629 \u0639\u062f\u062f \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646\u060c \u0648\u0642\u062f \u062c\u0627\u0621\u062a \u062c\u0645\u0627\u0639\u0629 \u0645\u0646 \u0642\u0648\u0645\u0643\u0645\u060c \u064a\u0631\u064a\u062f\u0648\u0646 \u0623\u0646 \u064a\u0633\u062a\u062b\u0646\u0648\u0646\u0627 \u0645\u0646 \u0627\u0644\u0623\u0645\u0631 \u0641\u064a \u062f\u064a\u0627\u0631\u0646\u0627."],t.s)
