B.aBC=s(["\u0645\u0627 \u0625\u0646 \u062a\u0645\u0651\u064e\u062a\u0650 \u0627\u0644\u0628\u064a\u0639\u0629 \u0644\u0623\u0628\u064a \u0628\u0643\u0631\u064d \u0627\u0644\u0635\u062f\u064a\u0642 \u0631\u0636\u064a\u064e \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u060c \u062d\u062a\u0649 \u0635\u0639\u062f \u0627\u0644\u0645\u0646\u0628\u0631\u060c \u0648\u062e\u0637\u0628 \u062e\u0637\u0628\u0629\u064b \u062c\u0627\u0645\u0639\u0629\u060c \u0631\u0633\u0645\u062a \u0645\u0639\u0627\u0644\u0645 \u0627\u0644\u062d\u0643\u0645 \u0627\u0644\u0631\u0634\u064a\u062f\u060c \u0648\u0627\u0628\u062a\u062f\u0623\u0647\u0627 \u0628\u062d\u0645\u062f \u0627\u0644\u0644\u0647 \u0648\u0627\u0644\u062b\u0646\u0627\u0621 \u0639\u0644\u064a\u0647\u060c \u062b\u0645 \u0642\u0627\u0644:","\u0623\u0645\u0627 \u0628\u0639\u062f\u060c \u0623\u064a\u0647\u0627 \u0627\u0644\u0646\u0627\u0633\u064f\u060c \u0641\u0625\u0646\u064a \u0642\u062f \u0648\u064f\u0644\u0651\u0650\u064a\u062a\u064f \u0639\u0644\u064a\u0643\u0645 \u0648\u0644\u0633\u062a\u064f \u0628\u062e\u064a\u0631\u0650\u0643\u0645\u060c \u0641\u0625\u0646 \u0623\u062d\u0633\u0646\u062a\u064f \u0641\u0623\u0639\u0650\u064a\u0646\u0648\u0646\u064a\u060c \u0648\u0625\u0646 \u0623\u0633\u0623\u062a\u064f \u0641\u0642\u0648\u0651\u0650\u0645\u0648\u0646\u064a\u060c \u0627\u0644\u0635\u062f\u0642\u064f \u0623\u0645\u0627\u0646\u0629 \u0648\u0627\u0644\u0643\u0630\u0628\u064f \u062e\u064a\u0627\u0646\u0629\u060c \u0648\u0627\u0644\u0636\u0639\u064a\u0641 \u0645\u0646\u0643\u0645 \u0642\u0648\u064a\u0651 \u0639\u0646\u062f\u064a \u062d\u062a\u0649 \u0623\u064f\u0632\u064a\u062d\u064e \u0639\u0650\u0644\u0651\u064e\u062a\u064e\u0647 \u0625\u0646 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647\u060c \u0648\u0627\u0644\u0642\u0648\u064a\u0651 \u0641\u064a\u0643\u0645 \u0636\u0639\u064a\u0641 \u062d\u062a\u0649 \u0622\u062e\u064f\u0630\u064e \u0645\u0646\u0647 \u0627\u0644\u062d\u0642 \u0625\u0646 \u0634\u0627\u0621 \u0627\u0644\u0644\u0647\u060c \u0644\u0627 \u064a\u062f\u0639\u064f \u0642\u0648\u0645\u064c \u0627\u0644\u062c\u0647\u0627\u062f\u064e \u0641\u064a \u0633\u0628\u064a\u0644 \u0627\u0644\u0644\u0647\u0650 \u0625\u0644\u0627 \u0636\u0631\u0628\u064e\u0647\u0645 \u0627\u0644\u0644\u0647\u064f \u0628\u0627\u0644\u0630\u0644\u060c \u0648\u0644\u0627 \u064a\u0634\u064a\u0639\u064f \u0642\u0648\u0645\u064c \u0642\u0637\u0651\u064f \u0627\u0644\u0641\u0627\u062d\u0634\u0629\u064e \u0625\u0644\u0627 \u0639\u0645\u0651\u064e\u0647\u0645 \u0627\u0644\u0644\u0647 \u0628\u0627\u0644\u0628\u0644\u0627\u0621\u060c \u0623\u064e\u0637\u064a\u0639\u0648\u0646\u064a \u0645\u0627 \u0623\u064e\u0637\u0639\u062a\u064f \u0627\u0644\u0644\u0647\u064e \u0648\u0631\u0633\u0648\u0644\u064e\u0647\u060c \u0641\u0625\u0630\u0627 \u0639\u0635\u064a\u062a\u064f \u0627\u0644\u0644\u0647\u064e \u0648\u0631\u0633\u0648\u0644\u064e\u0647 \u0641\u0644\u0627 \u0637\u0627\u0639\u0629\u064e \u0644\u064a \u0639\u0644\u064a\u0643\u0645 .. \u0642\u0648\u0645\u0648\u0627 \u0625\u0644\u0649 \u0635\u0644\u0627\u062a\u0650\u0643\u0645 \u064a\u0631\u062d\u0645\u0652\u0643\u0645 \u0627\u0644\u0644\u0647."],t.s)
