B.ay7=s(["\u0625\u0646 \u0647\u0630\u0647 \u0627\u0644\u0645\u0648\u0627\u0642\u0641 \u062a\u064f\u062e\u0644\u0651\u064e\u062f \u0641\u064a \u0633\u062c\u0644\u0651 \u0627\u0644\u062a\u0627\u0631\u064a\u062e\u060c \u0644\u0627 \u0644\u0643\u0648\u0646\u0647\u0627 \u0648\u0642\u0627\u0626\u0639 \u0632\u0645\u0646\u064d \u0645\u0636\u0649\u060c \u0628\u0644 \u0644\u0645\u0627 \u062a\u062d\u0645\u0644\u0647 \u0641\u064a \u0637\u064a\u0651\u0627\u062a\u0647\u0627 \u0645\u0646 \u062f\u0631\u0648\u0633\u064d \u0639\u0642\u0627\u0626\u062f\u064a\u0629 \u0648\u062a\u0631\u0628\u0648\u064a\u0629\u060c \u062a\u062c\u0644\u0651\u062a \u0641\u064a\u0647\u0627 \u0628\u0635\u064a\u0631\u0629 \u0627\u0644\u0635\u062d\u0627\u0628\u0629\u060c \u0625\u0630 \u0623\u062f\u0631\u0643\u0648\u0627 \u062b\u0650\u0642\u0644 \u0627\u0644\u0623\u0645\u0627\u0646\u0629 \u0627\u0644\u062a\u064a \u062a\u0631\u0643\u0647\u0627 \u0644\u0647\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa.","\u0641\u0643\u0627\u0646\u0648\u0627 \u0644\u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0627\u0646\u0629\u0650 \u0631\u062c\u0627\u0644\u064b\u0627\u060c \u0644\u0627 \u064a\u0642\u0628\u0644\u0648\u0646 \u0627\u0644\u0636\u0651\u064e\u064a\u0645\u060c \u0648\u0644\u0627 \u064a\u0646\u0642\u0636\u0648\u0646 \u0639\u0647\u062f\u064b\u0627 \u0639\u0627\u0647\u062f\u0648\u0627 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u060c \u0648\u0644\u0627 \u064a\u064f\u0641\u0631\u0651\u0642\u0648\u0646 \u0635\u0641\u0651\u064b\u0627 \u062c\u0645\u064e\u0639\u0647\u064f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0639\u0644\u0649 \u0627\u0644\u062d\u0642\u060c \u0641\u0627\u0633\u062a\u062d\u064e\u0642\u0648\u0627 \u0628\u0630\u0644\u0650\u0643 \u0627\u0644\u062b\u0646\u0627\u0621\u064e \u0645\u0646 \u0627\u0644\u0644\u0647.","\u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0623\u064f\u0648\u0644\u0626\u0650\u0643\u064e \u0627\u0644\u0651\u064e\u0630\u064a\u0646\u064e \u0622\u062a\u064e\u064a\u0646\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0643\u0650\u062a\u0627\u0628\u064e \u0648\u064e\u0627\u0644\u062d\u064f\u0643\u0645\u064e \u0648\u064e\u0627\u0644\u0646\u0651\u064f\u0628\u064f\u0648\u0651\u064e\u0629\u064e \u0641\u064e\u0625\u0650\u0646 \u064a\u064e\u0643\u0641\u064f\u0631 \u0628\u0650\u0647\u0627 \u0647\u0624\u064f\u0644\u0627\u0621\u0650 \u0641\u064e\u0642\u064e\u062f \u0648\u064e\u0643\u0651\u064e\u0644\u0646\u0627 \u0628\u0650\u0647\u0627 \u0642\u064e\u0648\u0645\u064b\u0627 \u0644\u064e\u064a\u0633\u0648\u0627 \u0628\u0650\u0647\u0627 \u0628\u0650\u0643\u0627\u0641\u0650\u0631\u064a\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0623\u0646\u0639\u0627\u0645","\u0642\u0627\u0644 \u0627\u0628\u0646 \u0639\u0628\u0627\u0633: \ufd3f\u0641\u064e\u0642\u064e\u062f \u0648\u064e\u0643\u0651\u064e\u0644\u0646\u0627 \u0628\u0650\u0647\u0627 \u0642\u064e\u0648\u0645\u064b\u0627\ufd3e \u0647\u0645 \u0627\u0644\u0645\u064f\u0647\u0627\u062c\u0631\u0650\u064a\u0646 \u0648\u0627\u0644\u0623\u0646\u0635\u064e\u0627\u0631 \u0648\u0623\u062a\u0628\u064e\u0627\u0639\u0647\u064f\u0645 \u0625\u0644\u0649 \u064a\u0648\u0645 \u0627\u0644\u0642\u064a\u0627\u0645\u064e\u0629.","\u0647\u0643\u0630\u0627 \u062a\u0645\u0651\u062a \u0627\u0644\u0628\u064a\u0639\u0629 \u0644\u0623\u0628\u064a \u0628\u0643\u0631\u064d\u060c \u0641\u064a \u0645\u0648\u0642\u0641\u064d \u0645\u0646 \u0623\u0639\u0638\u0645 \u0645\u0648\u0627\u0642\u0641 \u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0627\u062c\u062a\u0645\u0639 \u0641\u064a\u0647 \u0627\u0644\u0646\u0635 \u0645\u0639 \u0627\u0644\u0627\u062c\u062a\u0647\u0627\u062f\u060c \u0641\u0643\u0627\u0646 \u0645\u064a\u062b\u0627\u0642 \u0628\u0623\u0646 \u0647\u0630\u0647 \u0627\u0644\u0623\u0645\u0629 \u0644\u0646 \u062a\u064f\u062a\u0631\u0643 \u062f\u0648\u0646 \u0623\u0645\u064a\u0646 \u0639\u0644\u064a\u0647\u0627\u060c \u0648\u0623\u0646 \u0627\u0644\u062e\u0644\u0627\u0641\u0629 \u0645\u0627\u0636\u064a\u0629 \u0639\u0644\u0649 \u0645\u0646\u0647\u0627\u062c \u0627\u0644\u0646\u0628\u0648\u0629\u060c \u0645\u0627 \u062f\u0627\u0645 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0645\u0646 \u064a\u062d\u0645\u0644 \u0627\u0644\u0623\u0645\u0627\u0646\u0629 \u0628\u062d\u0642\u0647\u0627 \u0648\u064a\u0642\u064a\u0645 \u0641\u064a\u0647\u0627 \u0634\u0631\u0639 \u0627\u0644\u0644\u0647."],t.s)
