B.aHi=s(["\u0643\u0627\u0646\u062a \u0627\u0644\u0625\u0646\u0633\u0627\u0646\u064a\u0629\u064f \u0642\u0628\u0644 \u0628\u0632\u0648\u063a \u0641\u062c\u0631 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u062a\u0639\u064a\u0634 \u0645\u0631\u062d\u0644\u0629\u064b \u0645\u0646 \u0623\u062d\u0637\u0650\u0651 \u0645\u0631\u0627\u062d\u0644 \u0627\u0644\u062a\u0627\u0631\u064a\u062e \u0627\u0644\u0628\u0634\u0631\u064a \u0641\u064a \u0634\u0624\u0648\u0646\u0647\u0627 \u0627\u0644\u062f\u064a\u0646\u064a\u0629 \u0648\u0627\u0644\u0627\u0642\u062a\u0635\u0627\u062f\u064a\u0629 \u0648\u0627\u0644\u0633\u064a\u0627\u0633\u064a\u0629 \u0648\u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629\u060c \u0648\u062a\u064f\u0639\u0627\u0646\u064a \u0645\u0646 \u0641\u0648\u0636\u0649 \u0639\u0627\u0645\u0629 \u0637\u0627\u0644\u062a \u0643\u0644\u064e\u0651 \u062c\u0627\u0646\u0628 \u0645\u0646 \u062c\u0648\u0627\u0646\u0628 \u0627\u0644\u062d\u064a\u0627\u0629\u060c \u0648\u0647\u064e\u064a\u0645\u064e\u0646 \u0627\u0644\u0645\u0646\u0647\u062c\u064f \u0627\u0644\u062c\u0627\u0647\u0644\u064a \u0639\u0644\u0649 \u0627\u0644\u0639\u0642\u0627\u0626\u062f \u0648\u0627\u0644\u0623\u0641\u0643\u0627\u0631\u060c \u0648\u0623\u0635\u0628\u062d \u0627\u0644\u062c\u0647\u0644\u064f \u0648\u0627\u0644\u0647\u0648\u0649 \u0648\u0627\u0644\u0627\u0646\u062d\u0644\u0627\u0644\u064f \u0648\u0627\u0644\u0641\u062c\u0648\u0631\u064f \u0648\u0627\u0644\u062a\u062c\u0628\u0631\u064f \u0648\u0627\u0644\u062a\u0639\u0633\u0641\u064f \u0645\u0646 \u0623\u0628\u0631\u0632 \u0645\u0644\u0627\u0645\u062d \u0627\u0644\u0645\u0646\u0647\u062c \u0627\u0644\u062c\u0627\u0647\u0644\u064a \u0627\u0644\u0645\u064f\u0647\u064a\u0645\u0650\u0646 \u0639\u0644\u0649 \u062f\u0646\u064a\u0627 \u0627\u0644\u0646\u0627\u0633.","\u0648\u0636\u0627\u0639 \u062a\u0623\u062b\u064a\u0631\u064f \u0627\u0644\u062f\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0633\u0645\u0627\u0648\u064a\u0629 \u0623\u0648 \u0643\u0627\u062f\u060c \u0628\u0633\u0628\u0628 \u0645\u0627 \u0623\u0635\u0627\u0628\u0647\u0627 \u0645\u0646 \u062a\u0628\u062f\u064a\u0644\u064d \u0648\u062a\u062d\u0631\u064a\u0641\u064d \u062c\u0639\u0644\u0647\u0627 \u062a\u0641\u0642\u062f \u0623\u0647\u0645\u064a\u062a\u064e\u0647\u0627 \u0628\u0627\u0639\u062a\u0628\u0627\u0631\u0647\u0627 \u0631\u0633\u0627\u0644\u0629\u064e \u0627\u0644\u0644\u0647 \u0625\u0644\u0649 \u062e\u0644\u0642\u0647\u060c \u0648\u0627\u0646\u0634\u063a\u0644 \u0623\u0647\u0644\u064f\u0647\u0627 \u0628\u0635\u0631\u0627\u0639\u0627\u062a \u0639\u0642\u062f\u064a\u0629 \u0646\u0638\u0631\u064a\u0629 \u0643\u0627\u0646 \u0633\u0628\u0628\u064f\u0647\u0627 \u062f\u062e\u0648\u0644\u064f \u0627\u0644\u0623\u0641\u0643\u0627\u0631 \u0627\u0644\u0628\u0634\u0631\u064a\u0629 \u0648\u0627\u0644\u062a\u0635\u0648\u0631\u0627\u062a \u0627\u0644\u0641\u0627\u0633\u062f\u0629 \u0639\u0644\u064a\u0647\u0627\u060c \u062d\u062a\u0649 \u0623\u0641\u0636\u062a \u0625\u0644\u0649 \u062d\u0631\u0648\u0628 \u0637\u0627\u062d\u0646\u0629 \u0628\u064a\u0646\u0647\u0645\u060c \u0648\u0645\u0646 \u0628\u0642\u064a \u0645\u0646\u0647\u0645 \u0644\u0645 \u064a\u064f\u062d\u0631\u0650\u0651\u0641 \u0648\u0644\u0645 \u064a\u064f\u0628\u062f\u0650\u0651\u0644 \u0643\u0627\u0646 \u0642\u0644\u064a\u0644\u0627\u064b \u0646\u0627\u062f\u0631\u0627\u064b\u060c \u0648\u0642\u062f \u0622\u062b\u0631 \u0627\u0644\u0627\u0628\u062a\u0639\u0627\u062f\u064e \u0639\u0646 \u062f\u0646\u064a\u0627 \u0627\u0644\u0646\u0627\u0633 \u0648\u062f\u062e\u0644 \u0641\u064a \u062d\u064a\u0627\u0629 \u0627\u0644\u062e\u0644\u0648\u0629 \u0648\u0627\u0644\u0639\u0632\u0644\u0629\u060c \u064a\u0623\u0633\u0627\u064b \u0645\u0646 \u0627\u0644\u0625\u0635\u0644\u0627\u062d \u0648\u0637\u0645\u0639\u0627\u064b \u0641\u064a \u0627\u0644\u0646\u062c\u0627\u0629 \u0628\u0646\u0641\u0633\u0647\u060c \u0648\u0648\u0635\u0644 \u0627\u0644\u0641\u0633\u0627\u062f\u064f \u0625\u0644\u0649 \u062c\u0645\u064a\u0639 \u0627\u0644\u0623\u0635\u0646\u0627\u0641 \u0648\u0627\u0644\u0623\u062c\u0646\u0627\u0633 \u0627\u0644\u0628\u0634\u0631\u064a\u0629\u060c \u0648\u062f\u062e\u0644 \u0641\u064a \u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u062c\u0627\u0644\u0627\u062a \u0628\u0644\u0627 \u0627\u0633\u062a\u062b\u0646\u0627\u0621.","\u0641\u0641\u064a \u0627\u0644\u062c\u0627\u0646\u0628 \u0627\u0644\u062f\u064a\u0646\u064a \u062a\u062c\u062f \u0627\u0644\u0646\u0627\u0633\u064e \u0625\u0645\u0627 \u0627\u0631\u062a\u062f\u0648\u0627 \u0639\u0646 \u0627\u0644\u062f\u064a\u0646 \u0623\u0648 \u062e\u0631\u062c\u0648\u0627 \u0645\u0646\u0647 \u0623\u0648 \u0644\u0645 \u064a\u062f\u062e\u0644\u0648\u0627 \u0641\u064a\u0647 \u0623\u0635\u0644\u0627\u064b\u060c \u0623\u0648 \u0648\u0642\u0639\u0648\u0627 \u0641\u064a \u062a\u062d\u0631\u064a\u0641 \u0627\u0644\u062f\u064a\u0627\u0646\u0627\u062a \u0627\u0644\u0633\u0645\u0627\u0648\u064a\u0629 \u0648\u062a\u0628\u062f\u064a\u0644\u0647\u0627\u060c \u0648\u0641\u064a \u0627\u0644\u062a\u0634\u0631\u064a\u0639 \u0646\u064e\u0628\u064e\u0630 \u0627\u0644\u0646\u0627\u0633\u064f \u0634\u0631\u064a\u0639\u0629\u064e \u0627\u0644\u0644\u0647 \u0648\u0631\u0627\u0621\u0647\u0645 \u0638\u0647\u0631\u064a\u0627\u064b\u060c \u0648\u0627\u062e\u062a\u0631\u0639\u0648\u0627 \u0645\u0646 \u0639\u0646\u062f \u0623\u0646\u0641\u0633\u0647\u0645 \u0642\u0648\u0627\u0646\u064a\u0646\u064e \u0648\u0634\u0631\u0627\u0626\u0639\u064e \u0644\u0645 \u064a\u0623\u0630\u0646 \u0628\u0647\u0627 \u0627\u0644\u0644\u0647\u060c \u062a\u0635\u0637\u062f\u0645 \u0645\u0639 \u0627\u0644\u0639\u0642\u0644 \u0648\u062a\u062e\u062a\u0644\u0641 \u0645\u0639 \u0627\u0644\u0641\u0637\u0631\u0629\u060c \u0648\u062a\u0632\u0639\u064e\u0651\u0645 \u0647\u0630\u0627 \u0627\u0644\u0641\u0633\u0627\u062f\u064e \u0632\u0639\u0645\u0627\u0621\u064f \u0627\u0644\u0634\u0639\u0648\u0628 \u0648\u0627\u0644\u0623\u0645\u0645 \u0645\u0646 \u0627\u0644\u0642\u0627\u062f\u0629 \u0648\u0627\u0644\u0631\u0647\u0628\u0627\u0646 \u0648\u0627\u0644\u0642\u0633\u0627\u0648\u0633\u0629 \u0648\u0627\u0644\u062f\u0647\u0627\u0642\u064a\u0646 \u0648\u0627\u0644\u0645\u0644\u0648\u0643\u060c \u0648\u0623\u0635\u0628\u062d \u0627\u0644\u0639\u0627\u0644\u064e\u0645\u064f \u0641\u064a \u0638\u0644\u0627\u0645 \u062f\u0627\u0645\u0633 \u0648\u0627\u0646\u062d\u0631\u0627\u0641 \u0639\u0638\u064a\u0645 \u0639\u0646 \u0645\u0646\u0647\u062c \u0627\u0644\u0644\u0647 \u0633\u0628\u062d\u0627\u0646\u0647 \u0648\u062a\u0639\u0627\u0644\u0649."],t.s)
