B.aAR=s(["\u0643\u0627\u0646\u062a \u0627\u0644\u062d\u0631\u0648\u0628\u064f \u062a\u0646\u0634\u0628\u064f \u0628\u064a\u0646\u0647\u0645 \u0644\u0623\u062a\u0641\u0647\u0650 \u0627\u0644\u0623\u0633\u0628\u0627\u0628\u060c \u0641\u0647\u0645 \u0644\u0627 \u064a\u064f\u0628\u0627\u0644\u0648\u0646 \u0628\u0625\u0632\u0647\u0627\u0642\u0650 \u0627\u0644\u0623\u0631\u0648\u0627\u062d \u062f\u0641\u0627\u0639\u064b\u0627 \u0639\u0646 \u0645\u064f\u062b\u064f\u0644\u064d \u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629 \u0644\u0627 \u0642\u064a\u0645\u0629 \u0644\u0647\u0627\u060c \u0648\u0642\u062f \u0631\u064e\u0648\u0649 \u0644\u0646\u0627 \u0627\u0644\u062a\u0627\u0631\u064a\u062e\u064f \u0633\u0644\u0633\u0644\u0629\u064b \u0645\u0646 \u0623\u064a\u0627\u0645 \u0627\u0644\u0639\u0631\u0628 \u0641\u064a \u0627\u0644\u062c\u0627\u0647\u0644\u064a\u0629 \u0645\u0645\u0627 \u064a\u062f\u0644 \u0639\u0644\u0649 \u062a\u064e\u0645\u064e\u0643\u064f\u0651\u0646 \u0627\u0644\u0631\u0648\u062d \u0627\u0644\u062d\u0631\u0628\u064a\u0629 \u0645\u0646 \u0646\u0641\u0648\u0633\u0647\u0645 \u0648\u063a\u064e\u0644\u064e\u0628\u064e\u062a\u0650\u0647\u0627 \u0639\u0644\u0649 \u0627\u0644\u062a\u0639\u0642\u0644 \u0648\u0627\u0644\u062a\u0641\u0643\u064a\u0631\u060c \u0648\u0645\u0646 \u062a\u0644\u0643 \u0627\u0644\u0623\u064a\u0627\u0645 \u064a\u0648\u0645 \u0627\u0644\u0628\u0633\u0648\u0633.","\u0648\u0642\u0639\u062a \u062d\u0631\u0628 \u0627\u0644\u0628\u0633\u0648\u0633 \u0628\u064a\u0646 \u0642\u0628\u064a\u0644\u062a\u064a \u0628\u064e\u0643\u0631 \u0648\u062a\u064e\u063a\u0644\u0650\u0628 \u0648\u0627\u0645\u062a\u062f\u062a \u0646\u062d\u0648 \u0623\u0631\u0628\u0639\u064a\u0646 \u0633\u0646\u0629\u060c \u0648\u0643\u0627\u0646 \u0643\u064f\u0644\u064e\u064a\u0628 \u0628\u0646 \u0631\u0628\u064a\u0639\u0629 \u0633\u064a\u062f\u064e \u062a\u063a\u0644\u0628 \u0648\u0642\u062f \u0627\u062c\u062a\u0645\u0639\u062a \u062a\u062d\u062a \u0631\u0627\u064a\u062a\u0647 \u0642\u0628\u0627\u0626\u0644 \u0645\u064e\u0639\u064e\u062f\u0651 \u0641\u0623\u0645\u064e\u0651\u0631\u062a\u0647 \u0639\u0644\u064a\u0647\u0627\u060c \u0648\u0628\u0644\u063a \u0645\u0646 \u0627\u0644\u0645\u0643\u0627\u0646\u0629 \u0645\u0628\u0644\u063a\u064b\u0627 \u062d\u062a\u0649 \u0636\u064f\u0631\u0628 \u0628\u0647 \u0627\u0644\u0645\u062b\u0644\u060c \u063a\u064a\u0631 \u0623\u0646 \u0627\u0644\u063a\u0631\u0648\u0631 \u0623\u062e\u0630\u0647 \u0641\u0637\u063a\u0649 \u0648\u0628\u063a\u0649\u060c \u0641\u0627\u062a\u062e\u0630 \u0644\u0646\u0641\u0633\u0647 \u0645\u0631\u0639\u0649\u064b \u0644\u0627 \u062a\u0637\u0623\u0647 \u0642\u062f\u0645\u064c \u0648\u0644\u0627 \u062a\u062f\u062e\u0644\u0647 \u062f\u0627\u0628\u0629 \u0625\u0644\u0627 \u0628\u0625\u0630\u0646\u0647.","\u0648\u0643\u0627\u0646\u062a \u0627\u0644\u0628\u064e\u0633\u0648\u0633 \u0628\u0646\u062a \u0645\u0646\u0642\u0630 \u0627\u0644\u062a\u0645\u064a\u0645\u064a\u0629 \u0646\u0627\u0632\u0644\u0629\u064b \u0639\u0646\u062f \u0627\u0628\u0646 \u0623\u062e\u062a\u0647\u0627 \u062c\u064e\u0633\u064e\u0651\u0627\u0633 \u0628\u0646 \u0645\u064f\u0631\u064e\u0651\u0629 \u0645\u0646 \u0628\u0646\u064a \u0628\u0643\u0631\u060c \u0648\u0643\u0627\u0646 \u0644\u062c\u0627\u0631\u0647\u0627 \u0633\u064e\u0639\u062f \u0627\u0644\u062c\u064e\u0631\u0645\u064a \u0646\u0627\u0642\u0629\u064c \u0627\u0633\u0645\u0647\u0627 \u0633\u064e\u0631\u0627\u0628\u060c \u0641\u062f\u062e\u0644\u062a \u062a\u0644\u0643 \u0627\u0644\u0646\u0627\u0642\u0629 \u0623\u0631\u0636\u064e \u0643\u0644\u064a\u0628 \u0627\u0644\u0645\u062d\u0645\u064a\u0651\u0629 \u0641\u0631\u0645\u0627\u0647\u0627 \u0628\u0633\u0647\u0645 \u0641\u064a \u0636\u0631\u0639\u0647\u0627 \u0641\u0646\u0641\u0631\u062a \u0648\u0647\u064a \u062a\u0635\u064a\u062d \u0645\u0646 \u0627\u0644\u0623\u0644\u0645\u060c \u0641\u0644\u0645\u0627 \u0631\u0623\u062a \u0627\u0644\u0628\u0633\u0648\u0633 \u0645\u0627 \u062d\u0644\u064e\u0651 \u0628\u0646\u0627\u0642\u0629 \u062c\u0627\u0631\u0647\u0627 \u0635\u0627\u062d\u062a \u0645\u0633\u062a\u0646\u062c\u062f\u0629\u064b \u0628\u0627\u0628\u0646 \u0623\u062e\u062a\u0647\u0627 \u062c\u064e\u0633\u064e\u0651\u0627\u0633.","\u0641\u0644\u0645 \u064a\u064f\u0637\u0642 \u062c\u0633\u0627\u0633\u064c \u0635\u0628\u0631\u064b\u0627 \u0639\u0644\u0649 \u063a\u062f\u0631 \u0635\u0650\u0647\u0631\u0647 \u0628\u062c\u0627\u0631\u0647\u060c \u0641\u062a\u0631\u0628\u064e\u0651\u0635 \u0628\u0643\u0644\u064a\u0628 \u0641\u0642\u062a\u0644\u0647\u060c \u0641\u0623\u0634\u0639\u0644 \u0645\u0642\u062a\u0644\u064f \u0643\u0644\u064a\u0628 \u0646\u0627\u0631\u064e \u0627\u0644\u062d\u0631\u0628 \u0648\u062a\u0648\u0644\u0651\u0649 \u0642\u064a\u0627\u062f\u0629\u064e \u062a\u063a\u0644\u0628 \u0623\u062e\u0648\u0647 \u0627\u0644\u0645\u064f\u0647\u0644\u0647\u0644 \u0628\u0646 \u0631\u0628\u064a\u0639\u0629 \u064a\u0637\u0644\u0628 \u062b\u0623\u0631 \u0623\u062e\u064a\u0647\u060c \u0648\u062a\u0648\u0627\u0644\u062a \u0627\u0644\u0623\u064a\u0627\u0645 \u0648\u0627\u0644\u0648\u0642\u0627\u0626\u0639 \u0628\u064a\u0646 \u0627\u0644\u0642\u0628\u064a\u0644\u062a\u064a\u0646 \u0623\u0631\u0628\u0639\u064a\u0646 \u0633\u0646\u0629 \u062a\u064f\u0631\u0648\u0649 \u0623\u062d\u062f\u0627\u062b\u0647\u0627 \u0648\u062a\u064f\u0628\u0643\u0649 \u0642\u062a\u0644\u0627\u0647\u0627\u060c \u0648\u0642\u062f \u0636\u064f\u0631\u0628 \u0628\u0647\u0627 \u0627\u0644\u0645\u062b\u0644 \u0641\u064a \u0643\u0644 \u062d\u0631\u0628 \u0627\u0634\u062a\u0639\u0644\u062a \u0645\u0646 \u0634\u0631\u0627\u0631\u0629."],t.s)
