B.aHm=s(["\u0648\u064f\u0644\u0650\u062f\u064e \u0627\u0644\u062d\u0628\u064a\u0628\u064f \u0627\u0644\u0645\u0635\u0637\u0641\u0649 \ufdfa \u064a\u0648\u0645\u064e \u0627\u0644\u0627\u062b\u0646\u064a\u0646 \u0628\u0644\u0627 \u062e\u0644\u0627\u0641\u060c \u0648\u0627\u0644\u0623\u0643\u062b\u0631\u0648\u0646 \u0639\u0644\u0649 \u0623\u0646\u0647 \u0644\u0627\u062b\u0646\u062a\u064e\u064a \u0639\u0634\u0631\u0629\u064e \u0644\u064a\u0644\u0629\u064b \u062e\u0644\u064e\u062a \u0645\u0646 \u0634\u0647\u0631 \u0631\u0628\u064a\u0639 \u0627\u0644\u0623\u0648\u0644\u060c \u0648\u0627\u0644\u0645\u064f\u062c\u0645\u064e\u0639\u064f \u0639\u0644\u064a\u0647 \u0623\u0646\u0647 \ufdfa \u0648\u064f\u0644\u0650\u062f\u064e \u0639\u0627\u0645\u064e \u0627\u0644\u0641\u064a\u0644\u060c \u0648\u0643\u0627\u0646\u062a \u0648\u0644\u0627\u062f\u062a\u064f\u0647 \u0641\u064a \u062f\u0627\u0631 \u0623\u0628\u064a \u0637\u0627\u0644\u0628 \u0628\u0634\u0639\u0628 \u0628\u0646\u064a \u0647\u0627\u0634\u0645.","\u0642\u0627\u0644 \u0623\u062d\u0645\u062f \u0634\u0648\u0642\u064a \u0631\u062d\u0645\u0647 \u0627\u0644\u0644\u0647 \u0641\u064a \u0645\u0648\u0644\u062f \u0627\u0644\u062d\u0628\u064a\u0628 \u0627\u0644\u0645\u0635\u0637\u0641\u0649 \ufdfa:","\u0648\u064f\u0644\u0650\u062f\u064e \u0627\u0644\u0647\u062f\u0649 \u0641\u0627\u0644\u0643\u0627\u0626\u0646\u0627\u062a\u064f \u0636\u064a\u0627\u0621 .. \u0648\u0641\u0645\u064f \u0627\u0644\u0632\u0645\u0627\u0646\u0650 \u062a\u0628\u0633\u064e\u0651\u0645\u064e \u0648\u062b\u0646\u0627\u0621","\u0627\u0644\u0631\u0648\u062d \u0648\u0627\u0644\u0645\u0644\u0623 \u0627\u0644\u0645\u0644\u0627\u0626\u0643\u064f \u062d\u0648\u0644\u0647 .. \u0644\u0644\u062f\u064a\u0646 \u0648\u0627\u0644\u062f\u0646\u064a\u0627 \u0628\u0647 \u0628\u064f\u0634\u064e\u0631\u0627\u0621","\u0648\u0627\u0644\u0639\u0631\u0634\u064f \u064a\u0632\u0647\u0648 \u0648\u0627\u0644\u062d\u0638\u064a\u0631\u0629\u064f \u062a\u0632\u062f\u0647\u064a .. \u0648\u0627\u0644\u0645\u0646\u062a\u0647\u0649 \u0648\u0627\u0644\u0633\u062f\u0631\u0629\u064f \u0627\u0644\u0639\u0635\u0645\u0627\u0621","\u0628\u0643\u064e \u0628\u0634\u064e\u0651\u0631\u064e \u0627\u0644\u0644\u0647\u064f \u0627\u0644\u0633\u0645\u0627\u0621\u064e \u0641\u0632\u064f\u064a\u0650\u0651\u0646\u064e\u062a .. \u0648\u062a\u0636\u0648\u064e\u0651\u0639\u064e\u062a \u0645\u0633\u0643\u064b\u0627 \u0628\u0643\u064e \u0627\u0644\u063a\u0628\u0631\u0627\u0621","\u064a\u0648\u0645\u064c \u064a\u062a\u064a\u0647\u064f \u0639\u0644\u0649 \u0627\u0644\u0632\u0645\u0627\u0646\u0650 \u0635\u0628\u0627\u062d\u064f\u0647 .. \u0648\u0645\u0633\u0627\u0624\u064f\u0647 \u0628\u0645\u062d\u0645\u062f\u064d \u0648\u0636\u064e\u0651\u0627\u0621","\u0630\u064f\u0639\u0650\u0631\u064e\u062a \u0639\u0631\u0648\u0634\u064f \u0627\u0644\u0638\u0627\u0644\u0645\u064a\u0646 \u0641\u0632\u064f\u0644\u0632\u0650\u0644\u064e\u062a .. \u0648\u0639\u0644\u064e\u062a \u0639\u0644\u0649 \u062a\u064a\u062c\u0627\u0646\u0650\u0647\u0645 \u0623\u0635\u062f\u0627\u0621","\u0648\u0627\u0644\u0646\u0627\u0631\u064f \u062e\u0627\u0648\u064a\u0629\u064f \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u062d\u0648\u0644\u064e\u0647\u0645 .. \u062c\u064f\u0645\u0650\u0639\u064e\u062a \u0630\u0648\u0627\u0626\u0628\u064f\u0647\u0627 \u0648\u063a\u0627\u0636\u064e \u0627\u0644\u0645\u0627\u0621","\u0648\u0627\u0644\u0622\u064a\u064f \u062a\u062a\u0631\u0649 \u0648\u0627\u0644\u062e\u0648\u0627\u0631\u0642\u064f \u062c\u0645\u064e\u0651\u0629 .. \u062c\u0628\u0631\u064a\u0644\u064f \u0631\u064e\u0648\u064e\u0651\u0627\u062d\u064c \u0628\u0647\u0627 \u063a\u062f\u064e\u0651\u0627\u0621"],t.s)
