B.azw=s(["\u0648\u0642\u062f \u0648\u0642\u0639 \u0627\u0644\u062a\u062d\u0631\u064a\u0641\u064f \u0641\u064a \u0646\u064f\u0633\u064e\u062e \u0627\u0644\u062a\u0648\u0631\u0627\u0629 \u0648\u0627\u0644\u0625\u0646\u062c\u064a\u0644\u060c \u0641\u062d\u064f\u0630\u0641 \u0645\u0646\u0647\u0645\u0627 \u0627\u0644\u062a\u0635\u0631\u064a\u062d\u064f \u0628\u0627\u0633\u0645 \u0645\u062d\u0645\u062f \ufdfa\u060c \u0625\u0644\u0627 \u062a\u0648\u0631\u0627\u0629\u064e \u0627\u0644\u0633\u0627\u0645\u0631\u0629\u060c \u0648\u0625\u0646\u062c\u064a\u0644\u064e \u0628\u0631\u0646\u0627\u0628\u0627 \u0627\u0644\u0630\u064a \u0643\u0627\u0646 \u0645\u0648\u062c\u0648\u062f\u0627\u064b \u0642\u0628\u0644 \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u060c \u0648\u062d\u0631\u064e\u0651\u0645\u062a \u0627\u0644\u0643\u0646\u064a\u0633\u0629\u064f \u062a\u062f\u0627\u0648\u0644\u0647 \u0641\u064a \u0622\u062e\u0631 \u0627\u0644\u0642\u0631\u0646 \u0627\u0644\u062e\u0627\u0645\u0633 \u0627\u0644\u0645\u064a\u0644\u0627\u062f\u064a\u060c \u0648\u0642\u062f \u0623\u064a\u064e\u0651\u062f\u062a\u0647 \u0627\u0644\u0645\u062e\u0637\u0648\u0637\u0627\u062a\u064f \u0627\u0644\u062a\u064a \u0639\u064f\u062b\u0631 \u0639\u0644\u064a\u0647\u0627 \u0641\u064a \u0645\u0646\u0637\u0642\u0629 \u0627\u0644\u0628\u062d\u0631 \u0627\u0644\u0645\u064a\u062a \u062d\u062f\u064a\u062b\u0627\u064b\u060c \u0648\u0642\u062f \u062c\u0627\u0621 \u0641\u064a \u0625\u0646\u062c\u064a\u0644 \u0628\u0631\u0646\u0627\u0628\u0627 \u0627\u0644\u062a\u0635\u0631\u064a\u062d\u064f \u0628\u0627\u0633\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa\u060c \u0641\u0641\u064a \u0627\u0644\u0625\u0635\u062d\u0627\u062d \u0627\u0644\u062d\u0627\u062f\u064a \u0648\u0627\u0644\u0623\u0631\u0628\u0639\u064a\u0646 \u0645\u0646\u0647: \u0627\u062d\u062a\u062c\u0628 \u0627\u0644\u0644\u0647 \u0648\u0637\u0631\u062f\u0647\u0645\u0627 \u0627\u0644\u0645\u0644\u0627\u0643 \u0645\u064a\u062e\u0627\u0626\u064a\u0644 \u0645\u0646 \u0627\u0644\u0641\u0631\u062f\u0648\u0633\u060c \u0641\u0644\u0645\u0627 \u0627\u0644\u062a\u0641\u062a \u0622\u062f\u0645 \u0631\u0623\u0649 \u0645\u0643\u062a\u0648\u0628\u0627\u064b \u0641\u0648\u0642 \u0627\u0644\u0628\u0627\u0628: \u0644\u0627 \u0625\u0644\u0647 \u0625\u0644\u0627 \u0627\u0644\u0644\u0647 \u0645\u062d\u0645\u062f \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647.","\u0648\u0642\u0627\u0644 \u0627\u0628\u0646 \u062a\u064a\u0645\u064a\u0629: \xab\u0648\u0627\u0644\u0623\u062e\u0628\u0627\u0631 \u0628\u0645\u0639\u0631\u0641\u0629 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0628\u0635\u0641\u0629 \u0645\u062d\u0645\u062f \ufdfa \u0639\u0646\u062f\u0647\u0645 \u0641\u064a \u0627\u0644\u0643\u062a\u0628 \u0627\u0644\u0645\u062a\u0642\u062f\u0645\u0629 \u0645\u062a\u0648\u0627\u062a\u0631\u0629 \u0639\u0646\u0647\u0645\xbb\u060c \u062b\u0645 \u0642\u0627\u0644: \xab\u062b\u0645 \u0627\u0644\u0639\u0644\u0645 \u0628\u0623\u0646 \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621 \u0642\u0628\u0644\u0647 \u0628\u0634\u0631\u0648\u0627 \u0628\u0647 \u064a\u064f\u0639\u0644\u0645 \u0645\u0646 \u0648\u062c\u0648\u0647: \u0623\u062d\u062f\u0647\u0645\u0627 \u0645\u0627 \u0641\u064a \u0627\u0644\u0643\u062a\u0628 \u0627\u0644\u0645\u0648\u062c\u0648\u062f\u0629 \u0627\u0644\u064a\u0648\u0645 \u0628\u0623\u064a\u062f\u064a \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628\u060c \u0648\u0627\u0644\u062b\u0627\u0646\u064a \u0625\u062e\u0628\u0627\u0631\u064f \u0645\u0646 \u0648\u0642\u0641 \u0639\u0644\u0649 \u062a\u0644\u0643 \u0627\u0644\u0643\u062a\u0628 \u0645\u0645\u0646 \u0623\u0633\u0644\u0645 \u0648\u0645\u0645\u0646 \u0644\u0645 \u064a\u0633\u0644\u0645 \u0628\u0645\u0627 \u0648\u062c\u062f\u0648\u0647 \u0645\u0646 \u0630\u0643\u0631\u0647 \u0641\u064a\u0647\u0627\u060c \u0648\u0647\u0630\u0627 \u0645\u062b\u0644 \u0645\u0627 \u062a\u0648\u0627\u062a\u0631 \u0639\u0646 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0623\u0646 \u062c\u064a\u0631\u0627\u0646\u0647\u0645 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0643\u062a\u0627\u0628 \u0643\u0627\u0646\u0648\u0627 \u064a\u064f\u062e\u0628\u0631\u0648\u0646 \u0628\u0645\u0628\u0639\u062b\u0647\u060c \u0648\u0623\u0646\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0648\u0623\u0646\u0647 \u0645\u0648\u062c\u0648\u062f \u0639\u0646\u062f\u0647\u0645\u060c \u0648\u0643\u0627\u0646\u0648\u0627 \u064a\u0646\u062a\u0638\u0631\u0648\u0646\u0647\u060c \u0648\u0643\u0627\u0646 \u0647\u0630\u0627 \u0645\u0646 \u0623\u0639\u0638\u0645 \u0645\u0627 \u062f\u0639\u0627 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0625\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0628\u0647 \u0644\u0645\u0627 \u062f\u0639\u0627\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u062d\u062a\u0649 \u0622\u0645\u0646 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0628\u0647 \u0648\u0628\u0627\u064a\u0639\u0648\u0647\xbb."],t.s)
