B.aJX=s(["\u062d\u0631\u0635 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0639\u0644\u0649 \u062a\u0631\u0628\u064a\u0629 \u0623\u0635\u062d\u0627\u0628\u0647 \u062c\u0633\u062f\u064a\u0627\u064b \u0631\u0635\u064a\u0646\u0629\u060c \u0645\u0633\u062a\u0645\u062f\u0629\u064b \u0623\u0635\u0648\u0644\u0647\u0627 \u0645\u0646 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645\u061b \u0644\u062a\u0624\u062f\u064a \u0627\u0644\u0623\u0628\u062f\u0627\u0646 \u0648\u0638\u064a\u0641\u062a\u0647\u0627 \u0627\u0644\u062a\u064a \u062e\u064f\u0644\u0642\u062a \u0644\u0647\u0627 \u0628\u062a\u0648\u0627\u0632\u0646\u064d \u062a\u0627\u0645\u060c \u062f\u0648\u0646 \u0625\u0633\u0631\u0627\u0641\u064d \u064a\u064f\u0646\u0647\u0643\u0647\u0627 \u0623\u0648 \u062a\u0642\u062a\u064a\u0631\u064d \u064a\u064f\u0636\u0639\u0641\u0647\u0627\u060c \u0648\u0628\u0645\u0639\u0627\u062f\u0644\u0629\u064d \u062a\u0636\u0645\u0646 \u0623\u0644\u0627 \u062a\u0637\u063a\u0649 \u0637\u0627\u0642\u0629\u064c \u0645\u0646 \u0637\u0627\u0642\u0627\u062a \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0639\u0644\u0649 \u0623\u062e\u0631\u0649.","\u0648\u0641\u064a \u0633\u0628\u064a\u0644 \u0630\u0644\u0643 \u0648\u0636\u0639 \u0627\u0644\u0647\u062f\u064a \u0627\u0644\u0642\u0631\u0622\u0646\u064a \u0636\u0648\u0627\u0628\u0637 \u062d\u0643\u064a\u0645\u0629 \u062a\u064f\u0644\u0628\u064a \u062d\u0627\u062c\u0627\u062a \u0627\u0644\u062c\u0633\u062f \u0627\u0644\u0623\u0633\u0627\u0633\u064a\u0629\u061b \u0628\u062f\u0621\u0627\u064b \u0645\u0646 \u062a\u0646\u0638\u064a\u0645 \u0637\u0639\u0627\u0645\u0647 \u0648\u0634\u0631\u0627\u0628\u0647\u060c \u0645\u0631\u0648\u0631\u0627\u064b \u0628\u062a\u0623\u0645\u064a\u0646 \u0645\u0644\u0628\u0633\u0647 \u0648\u0645\u0623\u0648\u0627\u0647 \u0628\u0645\u0627 \u064a\u0633\u062a\u0631 \u0639\u0648\u0631\u062a\u0647 \u0648\u064a\u062d\u0645\u064a\u0647 \u0645\u0646 \u0627\u0644\u062d\u0631 \u0648\u0627\u0644\u0628\u0631\u062f \u0645\u0639 \u0646\u062f\u0628\u0647 \u0644\u0644\u0632\u064a\u0646\u0629 \u0639\u0646\u062f \u0627\u0644\u0645\u0633\u0627\u062c\u062f\u060c \u0648\u0635\u0648\u0644\u0627\u064b \u0625\u0644\u0649 \u0625\u0628\u0627\u062d\u0629 \u0627\u0644\u0646\u0643\u0627\u062d \u0648\u062a\u0634\u0631\u064a\u0639\u0647 \u0644\u0628\u0646\u0627\u0621 \u0627\u0644\u0623\u0633\u0631\u0629 \u0648\u0625\u0639\u0641\u0627\u0641 \u0627\u0644\u0628\u062f\u0646\u060c \u0645\u0639 \u0633\u062f \u0623\u0628\u0648\u0627\u0628 \u0627\u0644\u0627\u0646\u062d\u0631\u0627\u0641 \u0628\u0627\u0644\u062a\u062d\u0631\u064a\u0645 \u0627\u0644\u062d\u0627\u0632\u0645 \u0644\u0644\u0632\u0646\u0627 \u0648\u0627\u0644\u0645\u062e\u0627\u062f\u0646\u0629 \u0648\u0627\u0644\u0641\u0648\u0627\u062d\u0634.","\u0648\u0644\u0645 \u062a\u0642\u062a\u0635\u0631 \u0647\u0630\u0647 \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0639\u0644\u0649 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0627\u0644\u0628\u064a\u0648\u0644\u0648\u062c\u064a\u0629 \u0627\u0644\u0645\u062d\u0636\u0629\u060c \u0628\u0644 \u0627\u0645\u062a\u062f\u062a \u0644\u062a\u0636\u0628\u0637 \u062d\u0631\u0643\u0629 \u0647\u0630\u0627 \u0627\u0644\u062c\u0633\u062f \u0648\u0633\u0639\u064a\u0647 \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u061b \u0641\u0623\u0628\u0627\u062d\u062a \u0644\u0647 \u062a\u0645\u0644\u0651\u0643 \u0627\u0644\u0645\u0627\u0644 \u0648\u0627\u0644\u0639\u0642\u0627\u0631 \u0648\u0641\u0642 \u0636\u0648\u0627\u0628\u0637 \u0634\u0631\u0639\u064a\u0629 \u0639\u0627\u062f\u0644\u0629\u060c \u0648\u0648\u062c\u064e\u0651\u0647\u062a \u063a\u0631\u064a\u0632\u0629 \u0627\u0644\u0633\u064a\u0627\u062f\u0629 \u0644\u062f\u064a\u0647 \u0628\u062a\u062d\u0631\u064a\u0645 \u0627\u0644\u0628\u063a\u064a \u0648\u0627\u0644\u0638\u0644\u0645 \u0648\u0627\u0644\u0639\u062f\u0648\u0627\u0646\u060c \u0643\u0645\u0627 \u062f\u0641\u0639 \u0627\u0644\u0645\u0646\u0647\u062c \u0627\u0644\u0625\u0633\u0644\u0627\u0645\u064a \u0627\u0644\u0637\u0627\u0642\u0627\u062a\u0650 \u0627\u0644\u062c\u0633\u062f\u064a\u0629 \u0646\u062d\u0648 \u0627\u0644\u0639\u0645\u0644 \u0627\u0644\u0645\u062b\u0645\u0631 \u0648\u0627\u0644\u0646\u062c\u0627\u062d \u0627\u0644\u0645\u0634\u0631\u0648\u0639 \u0627\u0644\u0630\u064a \u0644\u0627 \u064a\u0636\u0631 \u0623\u062d\u062f\u0627\u064b\u060c \u062d\u0627\u062b\u0627\u064b \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0639\u0644\u0649 \u0627\u0644\u0633\u0639\u064a \u0627\u0644\u0630\u064a \u064a\u0643\u0641\u0644 \u0644\u0647\u0645 \u0627\u0644\u0642\u064a\u0627\u0645 \u0628\u0623\u0639\u0628\u0627\u0621 \u0627\u0644\u062f\u064a\u0646 \u0648\u0627\u0644\u062f\u0639\u0648\u0629\u060c \u0645\u0639 \u0627\u0644\u062a\u062d\u0630\u064a\u0631 \u0627\u0644\u0628\u0644\u064a\u063a \u0645\u0646 \u0627\u0644\u0631\u0643\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u062f\u0639\u0629 \u0648\u0627\u0644\u0628\u0637\u0631 \u0623\u0648 \u0627\u0644\u0627\u063a\u062a\u0631\u0627\u0631 \u0628\u0627\u0644\u0646\u0639\u0645\u0629\u060c \u0648\u0628\u0647\u0630\u0647 \u0627\u0644\u0623\u0633\u0633 \u0627\u0644\u0645\u062a\u0643\u0627\u0645\u0644\u0629 \u0635\u0650\u064a\u063a\u062a \u0627\u0644\u0623\u062c\u0633\u0627\u0645 \u0641\u064a \u0627\u0644\u0645\u062f\u0631\u0633\u0629 \u0627\u0644\u0646\u0628\u0648\u064a\u0629 \u0644\u062a\u063a\u062f\u0648 \u0642\u0627\u062f\u0631\u0629 \u0639\u0644\u0649 \u062a\u062d\u0645\u0644 \u0623\u062b\u0642\u0627\u0644 \u0627\u0644\u062c\u0647\u0627\u062f \u0648\u0645\u0643\u0627\u0628\u062f\u0629 \u0647\u0645\u0648\u0645 \u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u0645\u0648\u0627\u062c\u0647\u0629 \u0645\u0634\u0627\u0642 \u0627\u0644\u062d\u064a\u0627\u0629."],t.s)
