B.aGr=s(["\u062a\u062d\u0645\u0644 \u0642\u0635\u0629 \u0625\u0633\u0644\u0627\u0645 \u0636\u0650\u0645\u0627\u062f \u0627\u0644\u0623\u0632\u062f\u064a \u062f\u0631\u0648\u0633\u0627\u064b \u0628\u064a\u0650\u0651\u0646\u0629\u060c \u0623\u0648\u064e\u0651\u0644\u0647\u0627 \u0623\u0646 \u0627\u0644\u062d\u0631\u0628 \u0627\u0644\u0625\u0639\u0644\u0627\u0645\u064a\u0629 \u0627\u0644\u062a\u064a \u0634\u0646\u064e\u0651\u062a\u0647\u0627 \u0642\u0631\u064a\u0634 \u0644\u062a\u0634\u0648\u064a\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0642\u062f \u0627\u0646\u0642\u0644\u0628\u062a \u0648\u064e\u0628\u0627\u0644\u0627\u064b \u0639\u0644\u064a\u0647\u0627\u060c \u0625\u0630 \u0643\u0627\u0646\u062a \u062f\u0639\u0627\u064a\u062a\u0647\u0645 \u0628\u0627\u062a\u0647\u0627\u0645\u0647 \u0628\u0627\u0644\u062c\u0646\u0648\u0646 \u0647\u064a \u0627\u0644\u0633\u0628\u0628 \u0627\u0644\u0645\u0628\u0627\u0634\u0631 \u0627\u0644\u0630\u064a \u062d\u0645\u0644 \u0636\u0650\u0645\u0627\u062f\u0627\u064b \u0639\u0644\u0649 \u0627\u0644\u0633\u064a\u0631 \u0625\u0644\u064a\u0647\u060c \u0641\u0635\u0627\u0631\u062a \u062a\u0644\u0643 \u0627\u0644\u062f\u0639\u0627\u064a\u0629 \u0630\u0627\u062a\u0647\u0627 \u0637\u0631\u064a\u0642\u0627\u064b \u0625\u0644\u0649 \u0625\u0633\u0644\u0627\u0645\u0647 \u0648\u0625\u0633\u0644\u0627\u0645 \u0642\u0648\u0645\u0647 \u0645\u0646 \u0628\u0639\u062f\u0647.","\u0648\u062a\u062c\u0644\u064e\u0651\u062a \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0645\u0648\u0642\u0641 \u0635\u0641\u062a\u064e\u0627 \u0627\u0644\u0635\u0628\u0631 \u0648\u0627\u0644\u062d\u0650\u0644\u0645 \u0641\u064a \u0634\u062e\u0635 \u0627\u0644\u0646\u0628\u064a \ufdfa\u060c \u0641\u0631\u063a\u0645 \u0623\u0646 \u0639\u064e\u0631\u0636 \u0636\u0650\u0645\u0627\u062f \u0639\u0644\u064a\u0647 \u0627\u0644\u0631\u064f\u0651\u0642\u064a\u0629 \u0645\u0646 \u0627\u0644\u062c\u0646\u0648\u0646 \u064a\u064f\u0639\u064e\u062f \u0645\u0648\u0642\u0641\u064c \u064a\u062b\u064a\u0631 \u0627\u0644\u063a\u0636\u0628 \u0641\u064a \u0627\u0644\u0646\u0641\u0648\u0633\u060c \u0627\u0633\u062a\u0642\u0628\u0644\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0647\u062f\u0648\u0621 \u062a\u0627\u0645 \u0648\u062d\u0650\u0644\u0645 \u0638\u0627\u0647\u0631\u060c \u0641\u0623\u062b\u0627\u0631\u062a \u0647\u0630\u0647 \u0627\u0644\u0627\u0633\u062a\u062c\u0627\u0628\u0629 \u0625\u0639\u062c\u0627\u0628 \u0636\u0650\u0645\u0627\u062f \u0648\u0627\u062d\u062a\u0631\u0627\u0645\u0647 \u0627\u0644\u0634\u062f\u064a\u062f\u060c \u0648\u0642\u062f \u062a\u062c\u0644\u064e\u0651\u062a \u0643\u0630\u0644\u0643 \u0623\u0647\u0645\u064a\u0629 \u062a\u0644\u0643 \u0627\u0644\u0645\u0642\u062f\u0645\u0629 \u0627\u0644\u0628\u0644\u064a\u063a\u0629 \u0627\u0644\u062a\u064a \u0627\u0633\u062a\u0641\u062a\u062d \u0628\u0647\u0627 \ufdfa \u062d\u062f\u064a\u062b\u0647\u060c \u0648\u0627\u0644\u062a\u064a \u0643\u0627\u0646 \u0643\u062b\u064a\u0631\u0627\u064b \u0645\u0627 \u064a\u062c\u0639\u0644\u0647\u0627 \u0628\u064a\u0646 \u064a\u062f\u064a \u062e\u0637\u0628\u0647 \u0648\u0645\u0648\u0627\u0639\u0638\u0647\u060c \u0644\u0650\u0645\u0627 \u0627\u0634\u062a\u0645\u0644\u062a \u0639\u0644\u064a\u0647 \u0645\u0646 \u062a\u0639\u0638\u064a\u0645 \u0627\u0644\u0644\u0647 \u0648\u062a\u0645\u062c\u064a\u062f\u0647 \u0648\u0635\u064e\u0631\u0641 \u0627\u0644\u0639\u0628\u0627\u062f\u0629 \u0644\u0647 \u0648\u062d\u062f\u0647\u060c \u0641\u062a\u0623\u062b\u064e\u0651\u0631 \u0636\u0650\u0645\u0627\u062f \u062a\u0623\u062b\u064f\u0651\u0631\u0627\u064b \u0639\u0645\u064a\u0642\u0627\u064b \u0628\u0641\u0635\u0627\u062d\u0629 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0648\u0642\u0648\u0629 \u0628\u064a\u0627\u0646\u0647\u060c \u0644\u0623\u0646 \u0630\u0644\u0643 \u0627\u0644\u062d\u062f\u064a\u062b \u0627\u0646\u0628\u0639\u062b \u0645\u0646 \u0642\u0644\u0628 \u0645\u0644\u064a\u0621 \u0628\u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u0648\u0627\u0644\u064a\u0642\u064a\u0646 \u0648\u0627\u0644\u062d\u0643\u0645\u0629\u060c \u0641\u0628\u0644\u063a \u0627\u0644\u0642\u0644\u0648\u0628\u064e \u0645\u0628\u0627\u0634\u0631\u0629 \u0648\u062c\u0630\u0628\u0647\u0627 \u0625\u0644\u0649 \u0627\u0644\u0625\u064a\u0645\u0627\u0646.","\u0648\u062a\u0623\u062a\u064a \u0633\u0631\u0639\u0629 \u0625\u0633\u0644\u0627\u0645 \u0636\u0650\u0645\u0627\u062f \u062f\u0644\u064a\u0644\u0627\u064b \u0639\u0644\u0649 \u0623\u0646 \u0627\u0644\u0625\u0633\u0644\u0627\u0645 \u062f\u064a\u0646 \u0627\u0644\u0641\u0637\u0631\u0629\u060c \u0648\u0623\u0646 \u0627\u0644\u0646\u0641\u0648\u0633 \u0625\u0630\u0627 \u062a\u062c\u0631\u062f\u062a \u0645\u0646 \u0627\u0644\u0623\u0647\u0648\u0627\u0621 \u0648\u0627\u0644\u0639\u0646\u0627\u062f \u0641\u0625\u0646\u0647\u0627 \u062a\u0633\u062a\u062c\u064a\u0628 \u0648\u062a\u0646\u0642\u0627\u062f\u060c \u0625\u0645\u0627 \u0628\u0633\u0645\u0627\u0639 \u0642\u0648\u0644 \u0645\u0624\u062b\u0631\u060c \u0623\u0648 \u0628\u0627\u0644\u0625\u0639\u062c\u0627\u0628 \u0628\u0633\u0644\u0648\u0643 \u0642\u0648\u064a\u0645\u060c \u0648\u0645\u0646 \u062c\u0627\u0646\u0628\u0647 \u0638\u0647\u0631 \u062d\u0631\u0635 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0644\u0634\u062f\u064a\u062f \u0639\u0644\u0649 \u0627\u0646\u062a\u0634\u0627\u0631 \u062f\u0639\u0648\u062a\u0647\u061b \u0625\u0630 \u0631\u0623\u0649 \u0641\u064a \u0636\u0650\u0645\u0627\u062f \u0635\u062f\u0642\u064e \u0625\u064a\u0645\u0627\u0646\u0647 \u0648\u0642\u0648\u0629 \u0627\u0642\u062a\u0646\u0627\u0639\u0647\u060c \u0641\u0623\u062e\u0630 \u0645\u0646\u0647 \u0627\u0644\u0628\u064a\u0639\u0629 \u0639\u0644\u0649 \u0642\u0648\u0645\u0647\u060c \u0648\u0641\u064a \u0647\u0630\u0627 \u0628\u064a\u0627\u0646\u064c \u0648\u0627\u0636\u062d \u0644\u0623\u0647\u0645\u064a\u0629 \u0627\u0644\u062f\u0639\u0648\u0629 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647\u060c \u062d\u064a\u062b \u062c\u0639\u0644\u0647\u0627 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0642\u0631\u064a\u0646\u0629 \u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0627\u0644\u0634\u062e\u0635\u064a\u060c \u0641\u0644\u0645 \u064a\u0643\u062a\u0641\u0650 \u0628\u0645\u0628\u0627\u064a\u0639\u0629 \u0636\u0650\u0645\u0627\u062f \u0639\u0644\u0649 \u062f\u064a\u0646\u0647 \u0641\u062d\u0633\u0628\u060c \u0628\u0644 \u0623\u062e\u0630 \u0645\u0646\u0647 \u0627\u0644\u0628\u064a\u0639\u0629 \u0639\u0644\u0649 \u062f\u0639\u0648\u0629 \u0642\u0648\u0645\u0647 \u0625\u0644\u0649 \u0627\u0644\u0625\u0633\u0644\u0627\u0645.","\u0648\u064a\u0638\u0647\u0631 \u0645\u0646 \u0627\u0644\u0623\u062d\u062f\u0627\u062b \u0623\u064a\u0636\u0627\u064b \u062e\u064f\u0644\u064f\u0642 \u062d\u0641\u0638 \u0627\u0644\u0645\u0639\u0631\u0648\u0641 \u0648\u0631\u062f\u0650\u0651 \u0627\u0644\u062c\u0645\u064a\u0644 \u0644\u0623\u0647\u0644 \u0627\u0644\u0633\u0627\u0628\u0642\u0629 \u0648\u0627\u0644\u0641\u0636\u0644\u060c \u0648\u064a\u062a\u062c\u0644\u0649 \u0630\u0644\u0643 \u0641\u064a \u0642\u0648\u0644\u0647 \ufdfa \u0644\u062c\u0646\u062f\u0647: \u0631\u064f\u062f\u064f\u0651\u0648\u0647\u0627\u060c \u0641\u0625\u0646 \u0647\u0624\u0644\u0627\u0621 \u0642\u0648\u0645 \u0636\u0650\u0645\u0627\u062f\u060c \u0648\u062a\u0628\u0631\u0632 \u0641\u064a \u0627\u0644\u0642\u0635\u0629 \u062c\u0645\u0644\u0629 \u0645\u0646 \u0627\u0644\u0648\u0633\u0627\u0626\u0644 \u0627\u0644\u062a\u0631\u0628\u0648\u064a\u0629 \u0627\u0644\u062a\u064a \u0627\u0633\u062a\u0639\u0645\u0644\u0647\u0627 \u0627\u0644\u0646\u0628\u064a \ufdfa\u060c \u0643\u0627\u0644\u062a\u0623\u0646\u064a \u0641\u064a \u0627\u0644\u062d\u062f\u064a\u062b\u060c \u0648\u0623\u0633\u0644\u0648\u0628 \u0627\u0644\u062d\u0648\u0627\u0631\u060c \u0648\u0627\u0644\u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u060c \u0641\u0636\u0644\u0627\u064b \u0639\u0646 \u0635\u0641\u0627\u062a\u0647 \u0627\u0644\u0642\u064a\u0627\u062f\u064a\u0629 \u0643\u0645\u064f\u0631\u0628\u064d\u0651 \u064a\u062a\u0633\u0645 \u0628\u0627\u0644\u062d\u0650\u0644\u0645 \u0648\u0627\u0644\u0635\u0628\u0631 \u0648\u0627\u0644\u062a\u0634\u062c\u064a\u0639 \u0627\u0644\u0645\u0633\u062a\u0645\u0631 \u0639\u0644\u0649 \u0627\u0644\u0625\u0643\u062b\u0627\u0631 \u0645\u0646 \u0627\u0644\u062e\u064a\u0631\u0627\u062a."],t.s)
