B.awx=s(["\u062c\u0627\u0621\u064e\u062a \u0642\u0631\u064a\u0634\u064c \u0625\u0644\u0649 \u0627\u0644\u062d\u064f\u0635\u064e\u064a\u0646 -\u0648\u0643\u0627\u0646\u062a \u062a\u064f\u0639\u0638\u0650\u0651\u0645\u0647- \u0641\u0642\u0627\u0644\u0648\u0627: \u0643\u064e\u0644\u0650\u0651\u0645 \u0644\u0646\u0627 \u0647\u0630\u0627 \u0627\u0644\u0631\u062c\u0644\u060c \u0641\u0625\u0646\u0647 \u064a\u0630\u0643\u0631 \u0622\u0644\u0647\u062a\u0646\u0627 \u0648\u064a\u0633\u0628\u064f\u0651\u0647\u0645\u060c \u0641\u062c\u0627\u0624\u0648\u0627 \u0645\u0639\u0647 \u062d\u062a\u0649 \u062c\u0644\u0633\u0648\u0627 \u0642\u0631\u064a\u0628\u0627\u064b \u0645\u0646 \u0628\u0627\u0628 \u0627\u0644\u0646\u0628\u064a \ufdfa\u060c \u0641\u0642\u0627\u0644: \xab\u0623\u064e\u0648\u0633\u0650\u0639\u0648\u0627 \u0644\u0644\u0634\u064a\u062e\xbb\u060c \u0648\u0639\u0645\u0631\u0627\u0646 \u0648\u0623\u0635\u062d\u0627\u0628\u0647 \u0645\u062a\u0648\u0627\u0641\u0631\u0648\u0646.","\u0641\u0642\u0627\u0644 \u062d\u064f\u0635\u064e\u064a\u0646: \u0645\u0627 \u0647\u0630\u0627 \u0627\u0644\u0630\u064a \u0628\u0644\u063a\u0646\u0627 \u0639\u0646\u0643 \u0623\u0646\u0643 \u062a\u0634\u062a\u0645 \u0622\u0644\u0647\u062a\u0646\u0627 \u0648\u062a\u0630\u0643\u0631\u0647\u0645\u060c \u0648\u0642\u062f \u0643\u0627\u0646 \u0623\u0628\u0648\u0643 \u062d\u0650\u0635\u0646\u064b\u0627 \u0648\u062e\u064a\u0631\u0627\u064b\u061f -\u0645\u064f\u062a\u064e\u062d\u064e\u0635\u0650\u0651\u0646\u0627\u064b \u0628\u062f\u064a\u0646 \u0622\u0628\u0627\u0626\u0647 \u0648\u0623\u062c\u062f\u0627\u062f\u0647- \u0641\u0642\u0627\u0644: \xab\u064a\u0627 \u062d\u064f\u0635\u064e\u064a\u0646\u060c \u0625\u0646 \u0623\u0628\u064a \u0648\u0623\u0628\u0627\u0643 \u0641\u064a \u0627\u0644\u0646\u0627\u0631\u060c \u064a\u0627 \u062d\u064f\u0635\u064e\u064a\u0646\u060c \u0643\u0645 \u062a\u0639\u0628\u062f \u0645\u0646 \u0625\u0644\u0647\u061f\xbb \u0642\u0627\u0644: \u0633\u0628\u0639\u0629\u064b \u0641\u064a \u0627\u0644\u0623\u0631\u0636\u060c \u0648\u0648\u0627\u062d\u062f\u0627\u064b \u0641\u064a \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0641\u0642\u0627\u0644: \xab\u0641\u0625\u0630\u0627 \u0623\u0635\u0627\u0628\u0643\u064e \u0627\u0644\u0636\u0631\u064f\u0651 \u0645\u0646 \u062a\u064e\u062f\u0639\u0648\u061f\xbb \u0642\u0627\u0644: \u0627\u0644\u0630\u064a \u0641\u064a \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0642\u0627\u0644: \xab\u0641\u0625\u0630\u0627 \u0647\u064e\u0644\u064e\u0643 \u0627\u0644\u0645\u0627\u0644\u064f \u0645\u0646 \u062a\u064e\u062f\u0639\u0648\u061f\xbb \u0642\u0627\u0644: \u0627\u0644\u0630\u064a \u0641\u064a \u0627\u0644\u0633\u0645\u0627\u0621\u060c \u0642\u0627\u0644: \xab\u0641\u064a\u0633\u062a\u062c\u064a\u0628 \u0644\u0643 \u0648\u062d\u062f\u0647 \u0648\u062a\u064f\u0634\u0631\u0650\u0643\u064f\u0647\u0645 \u0645\u0639\u0647\u060c \u0623\u064e\u0631\u0636\u0650\u064a\u062a\u064e\u0647 \u0641\u064a \u0627\u0644\u0634\u0643\u0631 \u0623\u0645 \u062a\u062e\u0627\u0641 \u0623\u0646 \u064a\u064e\u063a\u0644\u064f\u0628 \u0639\u0644\u064a\u0643\u061f\xbb \u0642\u0627\u0644: \u0648\u0644\u0627 \u0648\u0627\u062d\u062f\u0629 \u0645\u0646 \u0647\u0627\u062a\u064a\u0646\u060c \u0642\u0627\u0644: \u0648\u0639\u064e\u0644\u0650\u0645\u062a\u064f \u0623\u0646\u064a \u0644\u0645 \u0623\u064f\u0643\u064e\u0644\u0650\u0651\u0645 \u0645\u0650\u062b\u0644\u064e\u0647.","\u0642\u0627\u0644: \xab\u064a\u0627 \u062d\u064f\u0635\u064e\u064a\u0646\u060c \u0623\u064e\u0633\u0644\u0650\u0645 \u062a\u064e\u0633\u0644\u064e\u0645\xbb\u060c \u0642\u0627\u0644: \u0625\u0646 \u0644\u064a \u0642\u0648\u0645\u0627\u064b \u0648\u0639\u0634\u064a\u0631\u0629\u060c \u0641\u0645\u0627\u0630\u0627 \u0623\u0642\u0648\u0644\u061f \u0642\u0627\u0644: \xab\u0642\u0644: \u0627\u0644\u0644\u0647\u0645 \u0623\u064e\u0633\u062a\u064e\u0647\u062f\u064a\u0643 \u0644\u0623\u064e\u0631\u0634\u064e\u062f\u0650 \u0623\u0645\u0631\u064a \u0648\u0632\u0650\u062f\u0646\u064a \u0639\u0644\u0645\u0627\u064b \u064a\u0646\u0641\u0639\u0646\u064a\xbb\u060c \u0641\u0642\u0627\u0644\u0647\u0627 \u062d\u064f\u0635\u064e\u064a\u0646 \u0641\u0644\u0645 \u064a\u064e\u0642\u064f\u0645 \u062d\u062a\u0649 \u0623\u064e\u0633\u0644\u064e\u0645\u060c \u0641\u0642\u0627\u0645 \u0625\u0644\u064a\u0647 \u0639\u0645\u0631\u0627\u0646 \u0641\u0642\u0628\u064e\u0651\u0644 \u0631\u0623\u0633\u0647 \u0648\u064a\u062f\u064a\u0647 \u0648\u0631\u062c\u0644\u064a\u0647\u060c \u0641\u0644\u0645\u0627 \u0631\u0623\u0649 \u0630\u0644\u0643 \u0627\u0644\u0646\u0628\u064a\u064f\u0651 \ufdfa \u0628\u0643\u0649 \u0648\u0642\u0627\u0644: \xab\u0628\u0643\u064a\u062a\u064f \u0645\u0646 \u0635\u0646\u064a\u0639 \u0639\u0645\u0631\u0627\u0646\u060c \u062f\u064e\u062e\u064e\u0644 \u062d\u064f\u0635\u064e\u064a\u0646 \u0648\u0647\u0648 \u0643\u0627\u0641\u0631 \u0641\u0644\u0645 \u064a\u064e\u0642\u064f\u0645 \u0625\u0644\u064a\u0647 \u0639\u0645\u0631\u0627\u0646 \u0648\u0644\u0645 \u064a\u064e\u0644\u062a\u064e\u0641\u0650\u062a \u0646\u0627\u062d\u064a\u064e\u062a\u064e\u0647\u060c \u0641\u0644\u0645\u0627 \u0623\u0633\u0644\u064e\u0645 \u0642\u0636\u0649 \u062d\u0642\u064e\u0651\u0647 \u0641\u062f\u064e\u062e\u064e\u0644\u064e\u0646\u064a \u0645\u0646 \u0630\u0644\u0643 \u0627\u0644\u0631\u0650\u0651\u0642\u064e\u0651\u0629\xbb\u060c \u0641\u0644\u0645\u0627 \u0623\u0631\u0627\u062f \u062d\u064f\u0635\u064e\u064a\u0646 \u0623\u0646 \u064a\u062e\u0631\u062c \u0642\u0627\u0644 \u0644\u0623\u0635\u062d\u0627\u0628\u0647: \xab\u0642\u0648\u0645\u0648\u0627 \u0641\u0634\u064e\u064a\u0650\u0651\u0639\u0648\u0647 \u0625\u0644\u0649 \u0645\u0646\u0632\u0644\u0647\xbb\u060c \u0641\u0644\u0645\u0627 \u062e\u0631\u062c \u0645\u0646 \u0633\u064f\u062f\u064e\u0651\u0629 \u0627\u0644\u0628\u0627\u0628 \u0631\u0623\u064e\u062a\u0647\u064f \u0642\u0631\u064a\u0634 \u0641\u0642\u0627\u0644\u0648\u0627: \u0635\u064e\u0628\u064e\u0623\u060c \u0648\u062a\u0641\u0631\u064e\u0651\u0642\u0648\u0627 \u0639\u0646\u0647.","\u0648\u0644\u0639\u0644\u064e\u0651 \u0627\u0644\u0630\u064a \u062d\u064e\u062f\u064e\u0627 \u0628\u0627\u0644\u062d\u064f\u0635\u064e\u064a\u0646 \u0648\u0627\u0644\u062f \u0639\u0645\u0631\u0627\u0646 \u0623\u0646 \u064a\u064f\u0633\u0644\u0650\u0645 \u0628\u0647\u0630\u0647 \u0627\u0644\u0633\u0631\u0639\u0629 \u0633\u0644\u0627\u0645\u0629\u064f \u0641\u0637\u0631\u062a\u0647 \u0648\u062d\u064f\u0633\u0646\u064f \u0627\u0633\u062a\u0639\u062f\u0627\u062f\u0647 \u0645\u0646 \u0646\u0627\u062d\u064a\u0629\u060c \u0648\u0642\u0648\u0629\u064f \u062d\u062c\u0629 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa \u0648\u0633\u0644\u0627\u0645\u0629\u064f \u0645\u0646\u0637\u0642\u0647 \u0645\u0646 \u0646\u0627\u062d\u064a\u0629 \u0623\u062e\u0631\u0649\u060c \u0648\u0646\u064e\u0644\u062d\u064e\u0638\u064f \u0623\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0627\u0633\u062a\u062e\u062f\u0645 \u0623\u0633\u0644\u0648\u0628 \u0627\u0644\u062d\u0648\u0627\u0631 \u0645\u0639 \u0627\u0644\u062d\u064f\u0635\u064e\u064a\u0646 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0644\u063a\u064e\u0631\u0633\u0650 \u0645\u0639\u0627\u0646\u064a \u0627\u0644\u062a\u0648\u062d\u064a\u062f \u0641\u064a \u0646\u0641\u0633\u0647 \u0648\u0646\u064e\u0633\u0641\u0650 \u0627\u0644\u0639\u0642\u0627\u0626\u062f \u0627\u0644\u0628\u0627\u0637\u0644\u0629 \u0627\u0644\u062a\u064a \u0643\u0627\u0646 \u064a\u0639\u062a\u0642\u062f\u0647\u0627."],t.s)
