B.aNl=s(["\u0644\u0642\u062f \u0623\u0635\u0628\u062d \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0641\u064a \u0648\u0636\u0639\u064d \u063a\u064a\u0631 \u0627\u0644\u0630\u064a \u0643\u0627\u0646\u0648\u0627 \u0641\u064a\u0647 \u0642\u0628\u0644 \u0627\u0644\u0647\u062c\u0631\u0629\u060c \u0641\u0642\u062f \u0627\u0645\u062a\u0646\u0639\u0648\u0627 \u0628\u062d\u0645\u0632\u0629 \u0648\u0639\u0645\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645\u0627\u060c \u0648\u0627\u0633\u062a\u0637\u0627\u0639\u0648\u0627 \u0623\u0646 \u064a\u064f\u0635\u0644\u064f\u0651\u0648\u0627 \u0639\u0646\u062f \u0627\u0644\u0643\u0639\u0628\u0629 \u0628\u0639\u062f \u0623\u0646 \u0643\u0627\u0646\u0648\u0627 \u0644\u0627 \u064a\u064e\u0642\u062f\u0650\u0631\u0648\u0646 \u0639\u0644\u0649 \u0630\u0644\u0643\u060c \u0648\u062e\u0631\u062c\u0648\u0627 \u0645\u0646 \u0628\u064a\u062a \u0627\u0644\u0623\u0631\u0642\u0645 \u0628\u0646 \u0623\u0628\u064a \u0627\u0644\u0623\u0631\u0642\u0645 \u0645\u062c\u0627\u0647\u0650\u0631\u064a\u0646 \u062d\u062a\u0649 \u062f\u062e\u0644\u0648\u0627 \u0627\u0644\u0645\u0633\u062c\u062f\u060c \u0648\u0643\u0641\u064e\u0651\u062a \u0642\u0631\u064a\u0634 \u0639\u0646 \u0625\u064a\u0630\u0627\u0626\u0647\u0645 \u0628\u0627\u0644\u0635\u0648\u0631\u0629 \u0627\u0644\u0648\u062d\u0634\u064a\u0629 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u062a \u062a\u064f\u0639\u0630\u0650\u0651\u0628\u064f\u0647\u0645 \u0628\u0647\u0627 \u0645\u0646 \u0642\u0628\u0644\u060c \u0648\u0627\u0644\u0638\u0631\u0648\u0641 \u0627\u0644\u062a\u064a \u0643\u0627\u0646\u0648\u0627 \u064a\u0639\u064a\u0634\u0648\u0646 \u0641\u064a\u0647\u0627 \u0642\u0628\u0644 \u0627\u0644\u0647\u062c\u0631\u0629 \u0642\u062f \u062a\u062d\u0648\u064e\u0651\u0644\u062a \u0625\u0644\u0649 \u0623\u062d\u0633\u0646\u060c \u0648\u0644\u0627 \u0634\u0643 \u0623\u0646 \u0643\u0644 \u0630\u0644\u0643 \u0642\u062f \u0648\u0635\u0644 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0641\u064a \u0627\u0644\u062d\u0628\u0634\u0629 \u0648\u0644\u0648 \u0639\u0646 \u0637\u0631\u064a\u0642 \u0627\u0644\u0628\u062d\u0627\u0631\u0629 \u0627\u0644\u0630\u064a\u0646 \u0643\u0627\u0646\u0648\u0627 \u064a\u0645\u0631\u064f\u0651\u0648\u0646 \u0628\u062c\u062f\u0629\u060c \u0641\u064e\u0641\u064e\u0631\u0650\u062d\u064e \u0628\u0647 \u0647\u0624\u0644\u0627\u0621 \u0627\u0644\u063a\u0631\u0628\u0627\u0621 \u0641\u0631\u062d\u064b\u0627 \u0643\u0628\u064a\u0631\u064b\u0627\u060c \u0648\u0639\u0627\u0648\u062f\u064e\u0647\u0645 \u0627\u0644\u062d\u0646\u064a\u0646\u064f \u0625\u0644\u0649 \u0627\u0644\u0648\u0637\u0646 -\u0648\u0647\u0648 \u0641\u0637\u0631\u0629\u064c \u0641\u0637\u0631 \u0627\u0644\u0644\u0647 \u0639\u0644\u064a\u0647\u0627 \u062c\u0645\u064a\u0639 \u0627\u0644\u0645\u062e\u0644\u0648\u0642\u0627\u062a- \u0641\u0631\u063a\u0628\u062a \u0646\u0641\u0648\u0633\u0647\u0645 \u0641\u064a \u0627\u0644\u0639\u0648\u062f\u0629 \u0625\u0644\u0649 \u0645\u0643\u0629 \u0623\u0645 \u0627\u0644\u0642\u0631\u0649 \u0648\u0625\u0644\u0649 \u0627\u0644\u0623\u0647\u0644 \u0648\u0627\u0644\u0639\u0634\u064a\u0631\u0629\u060c \u0641\u0639\u0627\u062f\u0648\u0627 \u0625\u0644\u064a\u0647\u0627 \u0641\u064a \u0638\u0644 \u0627\u0644\u0638\u0631\u0648\u0641 \u0627\u0644\u062c\u062f\u064a\u062f\u0629 \u0627\u0644\u0645\u0634\u062c\u0650\u0651\u0639\u0629 \u0648\u062a\u062d\u062a \u0625\u0644\u062d\u0627\u062d \u0627\u0644\u0646\u0641\u0633 \u0648\u062d\u0646\u064a\u0646\u0647\u0627 \u0625\u0644\u0649 \u062d\u0631\u0645 \u0627\u0644\u0644\u0647 \u0648\u0628\u064a\u062a\u0647 \u0627\u0644\u0639\u062a\u064a\u0642.","\u0644\u0642\u062f \u0631\u062c\u0639 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u0648\u0646 \u0625\u0644\u0649 \u0645\u0643\u0629 \u0628\u0633\u0628\u0628 \u0645\u0627 \u0639\u0644\u0645\u0648\u0647 \u0645\u0646 \u0625\u0633\u0644\u0627\u0645 \u062d\u0645\u0632\u0629 \u0648\u0639\u0645\u0631\u060c \u0648\u0627\u0639\u062a\u0642\u0627\u062f\u0647\u0645 \u0623\u0646 \u0625\u0633\u0644\u0627\u0645\u064e \u0647\u0630\u064a\u0646 \u0627\u0644\u0635\u062d\u0627\u0628\u064a\u064e\u0651\u064a\u0646 \u0627\u0644\u062c\u0644\u064a\u0644\u064a\u0646 \u0633\u064a\u064f\u0639\u0650\u0632\u064f\u0651 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0648\u062a\u064e\u0642\u0648\u0649 \u0628\u0647 \u0634\u0648\u0643\u062a\u064f\u0647\u0645\u060c \u0625\u0644\u0627 \u0623\u0646 \u0642\u0631\u064a\u0634\u064b\u0627 \u0648\u0627\u062c\u0647\u062a \u0625\u0633\u0644\u0627\u0645\u064e\u0647\u0645\u0627 \u0628\u062a\u062f\u0628\u064a\u0631\u0627\u062a\u064d \u062c\u062f\u064a\u062f\u0629 \u064a\u062a\u062c\u0644\u064e\u0651\u0649 \u0641\u064a\u0647\u0627 \u0627\u0644\u0645\u0643\u0631\u064f \u0648\u0627\u0644\u062f\u0647\u0627\u0621 \u0645\u0646 \u0646\u0627\u062d\u064a\u0629\u060c \u0648\u0627\u0644\u0642\u0633\u0648\u0629\u064f \u0648\u0627\u0644\u0639\u0646\u0641 \u0645\u0646 \u0646\u0627\u062d\u064a\u0629 \u0623\u062e\u0631\u0649\u060c \u0641\u0632\u0627\u062f\u062a \u0641\u064a \u0623\u0633\u0644\u062d\u0629 \u0627\u0644\u0625\u0631\u0647\u0627\u0628 \u0627\u0644\u062a\u064a \u062a\u0633\u062a\u0639\u0645\u0644\u0647\u0627 \u0636\u062f \u0627\u0644\u0646\u0628\u064a \ufdfa \u0648\u0623\u0635\u062d\u0627\u0628\u0647 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645 \u0633\u0644\u0627\u062d\u064b\u0627 \u0642\u0627\u0637\u0639\u064b\u0627 \u0647\u0648 \u0633\u0644\u0627\u062d\u064f \u0627\u0644\u0645\u0642\u0627\u0637\u0639\u0629 \u0627\u0644\u0627\u0642\u062a\u0635\u0627\u062f\u064a\u0629\u060c \u0641\u0643\u0627\u0646 \u0645\u0646 \u062c\u0631\u0627\u0621 \u0630\u0644\u0643 \u0627\u0644\u0645\u0648\u0642\u0641 \u0627\u0644\u0639\u0646\u064a\u0641 \u0623\u0646 \u0631\u062c\u0639 \u0627\u0644\u0645\u0633\u0644\u0645\u0648\u0646 \u0625\u0644\u0649 \u0627\u0644\u062d\u0628\u0634\u0629 \u0645\u0631\u0629\u064b \u062b\u0627\u0646\u064a\u0629\u060c \u0648\u0627\u0646\u0636\u0645\u064e\u0651 \u0625\u0644\u064a\u0647\u0645 \u0639\u062f\u062f\u064c \u0643\u0628\u064a\u0631 \u0645\u0645\u0646 \u0644\u0645 \u064a\u064f\u0647\u0627\u062c\u0631\u0648\u0627 \u0642\u0628\u0644 \u0630\u0644\u0643."],t.s)
