B.aHc=s(["\u062a\u062a\u062c\u0644\u0649 \u0628\u0631\u0643\u0627\u062a \u0647\u062c\u0631\u0629 \u0627\u0644\u062d\u0628\u0634\u0629 \u0641\u064a \u0635\u0648\u0631 \u0634\u062a\u0649\u060c \u0643\u0627\u0646 \u0645\u0646 \u0623\u0628\u0631\u0632\u0647\u0627 \u0625\u0633\u0644\u0627\u0645\u064f \u0639\u0645\u0631\u0648 \u0628\u0646 \u0627\u0644\u0639\u0627\u0635 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647 \u0628\u0623\u0631\u0636 \u0627\u0644\u062d\u0628\u0634\u0629\u060c \u0648\u0647\u0648 \u0628\u0644\u0627 \u0634\u0643 \u0623\u062b\u0631 \u0639\u0638\u064a\u0645 \u0645\u0646 \u0622\u062b\u0627\u0631 \u0627\u0644\u0647\u062c\u0631\u0629\u060c \u0648\u0628\u0631\u0647\u0627\u0646 \u0633\u0627\u0637\u0639 \u0639\u0644\u0649 \u0645\u0627 \u062d\u0642\u0642\u0647 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u0648\u0646 \u0645\u0646 \u0645\u0643\u0627\u0633\u0628 \u062d\u0642\u064a\u0642\u064a\u0629 \u0644\u0644\u062f\u0639\u0648\u0629 \u0645\u0646 \u062e\u0644\u0627\u0644 \u0645\u0643\u0648\u062b\u0647\u0645 \u0641\u064a \u062a\u0644\u0643 \u0627\u0644\u0623\u0631\u0636.","\u0648\u0625\u0646 \u0643\u0627\u0646\u062a \u0643\u062b\u064a\u0631\u0627\u064b \u0645\u0646 \u0627\u0644\u0645\u0631\u0648\u064a\u0627\u062a \u062a\u062a\u062c\u0647 \u0625\u0644\u0649 \u0623\u0646 \u0628\u062f\u0627\u064a\u0629 \u0625\u0633\u0644\u0627\u0645 \u0639\u0645\u0631\u0648 \u0628\u0646 \u0627\u0644\u0639\u0627\u0635 \u0643\u0627\u0646\u062a \u0639\u0644\u0649 \u064a\u062f \u0627\u0644\u0646\u062c\u0627\u0634\u064a -\u0648\u0647\u0648 \u0627\u0644\u0645\u0634\u0647\u0648\u0631 \u0643\u0645\u0627 \u064a\u0642\u0648\u0644 \u0627\u0628\u0646 \u062d\u062c\u0631- \u0648\u0647\u064a \u0644\u0637\u064a\u0641\u0629 \u0644\u0627 \u0645\u062b\u064a\u0644 \u0644\u0647\u0627 \u0641\u064a \u0627\u0644\u062a\u0627\u0631\u064a\u062e \u0625\u0630 \u0623\u0633\u0644\u0645 \u0635\u062d\u0627\u0628\u064a\u064c\u0651 \u0639\u0644\u0649 \u064a\u062f \u062a\u0627\u0628\u0639\u064a \u0643\u0645\u0627 \u064a\u0642\u0648\u0644 \u0627\u0644\u0632\u0631\u0642\u0627\u0646\u064a\u060c \u0641\u0625\u0646 \u0647\u0646\u0627\u0643 \u0645\u0631\u0648\u064a\u0627\u062a \u0623\u062e\u0631\u0649 \u062a\u064f\u0641\u064a\u062f \u0628\u0623\u0646 \u0625\u0633\u0644\u0627\u0645 \u0639\u0645\u0631\u0648 \u0643\u0627\u0646 \u0639\u0644\u0649 \u064a\u062f \u062c\u0639\u0641\u0631 \u0631\u0636\u064a \u0627\u0644\u0644\u0647 \u0639\u0646\u0647\u0645 \u062c\u0645\u064a\u0639\u0627\u064b.","\u0648\u0644\u0645 \u062a\u0642\u062a\u0635\u0631 \u0622\u062b\u0627\u0631 \u0627\u0644\u0647\u062c\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u062d\u0628\u0634\u0629 \u0639\u0644\u0649 \u0627\u0644\u062c\u0648\u0627\u0646\u0628 \u0627\u0644\u062f\u0639\u0648\u064a\u0629 \u0648\u0627\u0644\u0627\u062c\u062a\u0645\u0627\u0639\u064a\u0629 \u0641\u062d\u0633\u0628\u060c \u0628\u0644 \u0643\u0627\u0646 \u0644\u0647\u0627 \u0623\u062b\u0631 \u0633\u064a\u0627\u0633\u064a \u0628\u0627\u0644\u063a \u0641\u064a \u0627\u0644\u062d\u0637\u0650\u0651 \u0645\u0646 \u0645\u0643\u0627\u0646\u0629 \u0627\u0644\u0642\u0631\u0634\u064a\u064a\u0646 \u0639\u0646\u062f \u0633\u0627\u0626\u0631 \u0627\u0644\u0639\u0631\u0628\u060c \u0648\u0625\u062f\u0627\u0646\u0629 \u0645\u0648\u0642\u0641\u0647\u0645 \u0627\u0644\u0645\u062a\u0639\u0646\u062a \u0645\u0646 \u0627\u0644\u062f\u0639\u0648\u0629 \u0648\u062d\u0645\u0644\u062a\u0647\u0627\u060c \u0625\u0630 \u0643\u0627\u0646\u062a \u0627\u0644\u0628\u064a\u0626\u0629 \u0627\u0644\u0639\u0631\u0628\u064a\u0629 \u062a\u0641\u062a\u062e\u0631 \u0628\u0637\u0628\u064a\u0639\u062a\u0647\u0627 \u0628\u0625\u064a\u0648\u0627\u0621 \u0627\u0644\u063a\u0631\u064a\u0628 \u0648\u0625\u0643\u0631\u0627\u0645 \u0627\u0644\u062c\u0627\u0631\u060c \u0648\u062a\u062a\u0646\u0627\u0641\u0633 \u0641\u064a \u0630\u0644\u0643 \u0648\u062a\u062a\u062d\u0627\u0634\u0649 \u0627\u0644\u0633\u064f\u0651\u0628\u064e\u0651\u0629 \u0648\u0627\u0644\u0639\u0627\u0631 \u0641\u064a \u062e\u0644\u0627\u0641\u0647\u060c \u0641\u0625\u0630\u0627 \u0628\u0627\u0644\u0623\u062d\u0628\u0627\u0634 \u064a\u0633\u0628\u0642\u0648\u0646 \u0642\u0631\u064a\u0634\u0627\u064b \u0648\u064a\u0636\u0631\u0628\u0648\u0646 \u0645\u062b\u0644\u0627\u064b \u0641\u064a \u0627\u0644\u0645\u0631\u0648\u0621\u0629 \u0648\u0627\u0644\u0634\u0647\u0627\u0645\u0629\u060c \u0648\u064a\u064e\u0623\u0648\u0648\u0646 \u0645\u064e\u0646\u0652 \u0637\u0631\u062f\u062a\u0647\u0645 \u0642\u0631\u064a\u0634 \u0648\u0623\u0633\u0627\u0621\u062a \u0625\u0644\u064a\u0647\u0645 \u0645\u0646 \u0623\u0634\u0631\u0627\u0641 \u0627\u0644\u0646\u0627\u0633 \u0648\u0645\u0646 \u0636\u0639\u0641\u0627\u0626\u0647\u0645 \u0648\u0645\u0646 \u063a\u0631\u0628\u0627\u0626\u0647\u0645 \u0639\u0644\u0649 \u062d\u062f\u064d\u0651 \u0633\u0648\u0627\u0621."],t.s)
