B.aDQ=s(["\u0644\u0645\u064e\u0651\u0627 \u062a\u0639\u0631\u064e\u0651\u0636 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0644\u0644\u0623\u0630\u0649 \u0645\u0646 \u0623\u0647\u0644 \u0627\u0644\u0637\u0627\u0626\u0641\u060c \u0648\u062e\u0631\u062c \u0645\u0646 \u0639\u0646\u062f\u0647\u0645\u060c \u0622\u0648\u0649 \u0625\u0644\u0649 \u062d\u0627\u0626\u0637 \u0644\u0639\u062a\u0628\u0629 \u0628\u0646 \u0631\u0628\u064a\u0639\u0629 \u0648\u0634\u064a\u0628\u0629 \u0628\u0646 \u0631\u0628\u064a\u0639\u0629 \u0648\u0647\u0645\u0627 \u0641\u064a\u0647\u060c \u0641\u0644\u0645\u064e\u0651\u0627 \u0631\u0622\u0647 \u0639\u062a\u0628\u0629\u064f \u0648\u0634\u064a\u0628\u0629\u064f \u0631\u0642\u064e\u0651\u0627 \u0644\u0647\u060c \u0648\u062f\u0639\u064e\u0648\u0627 \u063a\u0644\u0627\u0645\u064b\u0627 \u0644\u0647\u0645\u0627 \u0646\u0635\u0631\u0627\u0646\u064a\u064b\u0651\u0627 \u064a\u064f\u0642\u0627\u0644 \u0644\u0647 \u0639\u062f\u064e\u0651\u0627\u0633\u060c \u0641\u0642\u0627\u0644\u0627 \u0644\u0647: \u062e\u0630 \u0642\u0650\u0637\u0641\u064b\u0627 \u0645\u0646 \u0647\u0630\u0627 \u0627\u0644\u0639\u0646\u0628\u060c \u0641\u0636\u064e\u0639\u0647 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u0637\u0628\u0642\u060c \u062b\u0645 \u0627\u0630\u0647\u0628 \u0628\u0647 \u0625\u0644\u0649 \u0630\u0644\u0643 \u0627\u0644\u0631\u062c\u0644\u060c \u0641\u0642\u064f\u0644 \u0644\u0647 \u064a\u0623\u0643\u0644 \u0645\u0646\u0647\u060c \u0641\u0641\u0639\u0644 \u0639\u062f\u064e\u0651\u0627\u0633.","\u062b\u0645 \u0623\u0642\u0628\u0644 \u0639\u062f\u064e\u0651\u0627\u0633 \u0628\u0627\u0644\u0637\u0628\u0642 \u062d\u062a\u0649 \u0648\u0636\u0639\u0647 \u0628\u064a\u0646 \u064a\u062f\u064e\u064a \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0642\u0627\u0644 \u0644\u0647: \u0643\u064f\u0644\u060c \u0641\u0644\u0645\u064e\u0651\u0627 \u0648\u0636\u0639 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u062f\u0647 \u0641\u064a\u0647 \u0642\u0627\u0644: \xab\u0628\u0633\u0645 \u0627\u0644\u0644\u0647\xbb\u060c \u062b\u0645 \u0623\u0643\u0644\u060c \u0641\u0646\u0638\u0631 \u0639\u062f\u064e\u0651\u0627\u0633\u064c \u0641\u064a \u0648\u062c\u0647\u0647 \u0648\u0642\u0627\u0644: \u0648\u0627\u0644\u0644\u0647 \u0625\u0646 \u0647\u0630\u0627 \u0627\u0644\u0643\u0644\u0627\u0645 \u0645\u0627 \u064a\u0642\u0648\u0644\u0647 \u0623\u0647\u0644 \u0647\u0630\u0647 \u0627\u0644\u0628\u0644\u0627\u062f\u060c \u0641\u0642\u0627\u0644 \u0644\u0647 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \xab\u0648\u0645\u0646 \u0623\u0647\u0644\u0650 \u0623\u064a\u0650\u0651 \u0627\u0644\u0628\u0644\u0627\u062f \u0623\u0646\u062a \u064a\u0627 \u0639\u062f\u064e\u0651\u0627\u0633\u061f \u0648\u0645\u0627 \u062f\u064a\u0646\u064f\u0643\u061f\xbb \u0642\u0627\u0644: \u0646\u0635\u0631\u0627\u0646\u064a\u060c \u0648\u0623\u0646\u0627 \u0631\u062c\u0644 \u0645\u0646 \u0623\u0647\u0644 \u0646\u064a\u0646\u0648\u0649\u060c \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \xab\u0645\u0646 \u0642\u0631\u064a\u0629 \u0627\u0644\u0631\u062c\u0644 \u0627\u0644\u0635\u0627\u0644\u062d \u064a\u0648\u0646\u0633 \u0628\u0646 \u0645\u062a\u064e\u0651\u0649\xbb\u060c \u0641\u0642\u0627\u0644 \u0644\u0647 \u0639\u062f\u064e\u0651\u0627\u0633: \u0648\u0645\u0627 \u064a\u064f\u062f\u0631\u064a\u0643 \u0645\u0627 \u064a\u0648\u0646\u0633 \u0628\u0646 \u0645\u062a\u064e\u0651\u0649\u061f \u0641\u0642\u0627\u0644 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa: \xab\u0630\u0627\u0643 \u0623\u062e\u064a\u060c \u0643\u0627\u0646 \u0646\u0628\u064a\u064b\u0651\u0627 \u0648\u0623\u0646\u0627 \u0646\u0628\u064a\xbb\u060c \u0641\u0623\u0643\u0628\u064e\u0651 \u0639\u062f\u064e\u0651\u0627\u0633\u064c \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u064a\u064f\u0642\u0628\u0650\u0651\u0644 \u0631\u0623\u0633\u0647 \u0648\u064a\u062f\u064a\u0647 \u0648\u0642\u062f\u0645\u064a\u0647\u060c \u0641\u0642\u0627\u0644 \u0623\u062d\u062f \u0627\u0628\u0646\u064e\u064a \u0631\u0628\u064a\u0639\u0629 \u0644\u0635\u0627\u062d\u0628\u0647: \u0623\u0645\u0627 \u063a\u0644\u0627\u0645\u0643 \u0641\u0642\u062f \u0623\u0641\u0633\u062f\u0647 \u0639\u0644\u064a\u0643\u060c \u0641\u0644\u0645\u064e\u0651\u0627 \u062c\u0627\u0621\u0647\u0645\u0627 \u0639\u062f\u064e\u0651\u0627\u0633 \u0642\u0627\u0644\u0627 \u0644\u0647: \u0648\u064a\u0644\u0643 \u064a\u0627 \u0639\u062f\u064e\u0651\u0627\u0633\u060c \u0645\u0627 \u0644\u0643 \u062a\u064f\u0642\u0628\u0650\u0651\u0644 \u0631\u0623\u0633 \u0647\u0630\u0627 \u0627\u0644\u0631\u062c\u0644 \u0648\u064a\u062f\u064a\u0647 \u0648\u0642\u062f\u0645\u064a\u0647\u061f \u0642\u0627\u0644: \u064a\u0627 \u0633\u064a\u062f\u064a\u060c \u0645\u0627 \u0641\u064a \u0627\u0644\u0623\u0631\u0636 \u0634\u064a\u0621 \u062e\u064a\u0631\u064c \u0645\u0646 \u0647\u0630\u0627\u060c \u0644\u0642\u062f \u0623\u062e\u0628\u0631\u0646\u064a \u0628\u0623\u0645\u0631 \u0645\u0627 \u064a\u0639\u0644\u0645\u0647 \u0625\u0644\u0627 \u0646\u0628\u064a\u060c \u0642\u0627\u0644\u0627 \u0644\u0647: \u0648\u064a\u062d\u0643 \u064a\u0627 \u0639\u062f\u064e\u0651\u0627\u0633\u060c \u0644\u0627 \u064a\u064e\u0635\u0631\u0641\u064e\u0646\u064e\u0651\u0643 \u0639\u0646 \u062f\u064a\u0646\u0643\u060c \u0641\u0625\u0646 \u062f\u064a\u0646\u0643 \u062e\u064a\u0631\u064c \u0645\u0646 \u062f\u064a\u0646\u0647."],t.s)
