B.aEe=s(["\u062b\u064f\u0645\u064e\u0651 \u0630\u0643\u064e\u0631 \u0627\u0644\u0646\u064e\u0651\u0628\u064a\u064f\u0651 \ufdfa \u0623\u0646\u064e\u0651\u0647 \u0628\u0639\u062f \u0630\u0644\u0643 \u0623\u064f\u062a\u064a\u064e \u0644\u0647 \u0628\u0627\u0644\u062f\u064e\u0651\u0627\u0628\u064e\u0651\u0629\u0650 \u0627\u0644\u064e\u0651\u062a\u064a \u0633\u064a\u064e\u0631\u0643\u064e\u0628\u064f\u0647\u0627 \u0641\u064a \u0631\u0650\u062d\u0644\u0629\u0650 \u0627\u0644\u0625\u0633\u0631\u0627\u0621\u0650 \u0625\u0644\u0649 \u0627\u0644\u0645\u064e\u0633\u062c\u0650\u062f\u0650 \u0627\u0644\u0623\u0642\u0635\u0649\u060c \u0648\u0647\u064a \u0627\u0644\u0628\u064f\u0631\u0627\u0642\u064f\u060c \u0648\u0642\u062f \u0633\u064f\u0645\u0650\u0651\u064a\u064e \u0628\u0630\u0644\u0643 \u0644\u0627\u0634\u062a\u0642\u0627\u0642\u0650 \u0627\u0633\u0645\u0650\u0647 \u0645\u0650\u0646 \u0627\u0644\u0628\u064e\u0631\u0642\u0650\u060c \u062f\u0644\u0627\u0644\u0629\u064b \u0639\u0644\u0649 \u0633\u064f\u0631\u0639\u062a\u0650\u0647 \u0627\u0644\u062e\u0627\u0631\u0642\u0629\u0650 \u0648\u0625\u0636\u0627\u0621\u062a\u0650\u0647\u060c \u0648\u0647\u0648 \u062f\u0627\u0628\u064e\u0651\u0629\u064c \u0628\u064a\u0636\u0627\u0621\u064f \u0623\u0642\u0644\u064f\u0651 \u0641\u064a \u062d\u064e\u062c\u0645\u0650\u0647\u0627 \u0645\u0650\u0646 \u0627\u0644\u0628\u064e\u063a\u0644\u0650\u060c \u0648\u0623\u0643\u0628\u0631\u064f \u0645\u0650\u0646 \u0627\u0644\u062d\u0650\u0645\u0627\u0631\u0650\u060c \xab\u064a\u0636\u064e\u0639\u064f \u062e\u064e\u0637\u0648\u064e\u0647 \u0639\u0646\u062f\u064e \u0623\u0642\u0635\u0649 \u0637\u064e\u0631\u0641\u0650\u0647\xbb\u060c \u0623\u064a: \u0625\u0646\u064e\u0651 \u062e\u064f\u0637\u0648\u062a\u064e\u0647 \u0627\u0644\u0648\u0627\u062d\u0650\u062f\u0629\u064e \u0628\u0645\u0650\u0642\u062f\u0627\u0631\u0650 \u0645\u0627 \u064a\u064e\u0646\u062a\u064e\u0647\u064a \u0625\u0644\u064a\u0647 \u0628\u064e\u0635\u064e\u0631\u064f\u0647\u060c \u0648\u0641\u064a \u0630\u0644\u0643 \u0625\u0634\u0627\u0631\u0629\u064c \u0625\u0644\u0649 \u0634\u062f\u064e\u0651\u0629\u0650 \u0633\u064f\u0631\u0639\u062a\u0650\u0647.","\u0641\u0644\u0645\u064e\u0651\u0627 \u0648\u0635\u064e\u0644 \u0627\u0644\u0646\u064e\u0651\u0628\u064a\u064f\u0651 \ufdfa \u0625\u0644\u0649 \u0627\u0644\u0645\u064e\u0633\u062c\u0650\u062f\u0650 \u0627\u0644\u0623\u0642\u0635\u0649\u060c \u0631\u0628\u064e\u0637\u064e \u0627\u0644\u0628\u064f\u0631\u0627\u0642\u064e \u0628\u0627\u0644\u062d\u064e\u0644\u0642\u0629\u0650 \u0627\u0644\u064e\u0651\u062a\u064a \u0643\u0627\u0646\u064e \u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621\u064f \u064a\u064e\u0631\u0628\u0650\u0637\u0648\u0646\u064e \u0628\u0647\u0627 \u062f\u0648\u0627\u0628\u064e\u0651\u0647\u0645 \u0639\u0646\u062f\u064e \u0628\u0627\u0628\u0650 \u0627\u0644\u0645\u064e\u0633\u062c\u0650\u062f\u0650\u060c \u062b\u064f\u0645\u064e\u0651 \u062f\u062e\u064e\u0644 \ufdfa \u0627\u0644\u0645\u064e\u0633\u062c\u0650\u062f\u064e \u0641\u0635\u0644\u064e\u0651\u0649 \u0628\u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621\u0650 \u0625\u0645\u0627\u0645\u064b\u0627\u060c \u062a\u0644\u0643\u064e \u0627\u0644\u0635\u064e\u0651\u0644\u0627\u0629\u064f \u0627\u0644\u064e\u0651\u062a\u064a \u062c\u0645\u064e\u0639\u064e\u062a \u062e\u0627\u062a\u064e\u0645\u064e \u0627\u0644\u0646\u064e\u0651\u0628\u064a\u0650\u0651\u064a\u0646\u064e \u0628\u0627\u0644\u0623\u0646\u0628\u064a\u0627\u0621\u0650 \u0641\u064a \u0623\u0634\u0631\u064e\u0641\u0650 \u0628\u0650\u0642\u0627\u0639\u0650 \u0627\u0644\u0623\u0631\u0636\u0650\u060c \u0641\u0644\u0645\u064e\u0651\u0627 \u0642\u064e\u0636\u0649 \u0627\u0644\u0646\u064e\u0651\u0628\u064a\u064f\u0651 \ufdfa \u0635\u0644\u0627\u062a\u064e\u0647\u060c \u0643\u0627\u0646\u064e \u0627\u0644\u0645\u064e\u0639\u0631\u0627\u062c\u064f \u0625\u0644\u0649 \u0627\u0644\u0633\u064e\u0651\u0645\u0627\u0648\u0627\u062a\u0650 \u0627\u0644\u0639\u064f\u0644\u0627."],t.s)
