B.aI3=s(["\u0627\u062e\u062a\u0627\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0623\u0646 \u064a\u064f\u062c\u0631\u064a \u0645\u0641\u0627\u0648\u0636\u0627\u062a\u0647 \u0645\u0639 \u0628\u0646\u064a \u0639\u0627\u0645\u0631 \u0639\u0644\u0649 \u0623\u0633\u0627\u0633 \u0645\u0646 \u0627\u0644\u062f\u0631\u0627\u0633\u0629 \u0648\u0627\u0644\u062a\u062e\u0637\u064a\u0637\u060c \u0625\u0630 \u0643\u0627\u0646 \u0647\u0648 \u0648\u0635\u0627\u062d\u0628\u0647 \u0623\u0628\u0648 \u0628\u0643\u0631 \u064a\u0639\u0644\u0645\u0627\u0646 \u0623\u0646 \u0628\u0646\u064a \u0639\u0627\u0645\u0631 \u0642\u0628\u064a\u0644\u0629 \u0645\u0642\u0627\u062a\u0644\u0629 \u0643\u0628\u064a\u0631\u0629 \u0627\u0644\u0639\u062f\u062f \u0639\u0632\u064a\u0632\u0629 \u0627\u0644\u062c\u0627\u0646\u0628\u060c \u0628\u0644 \u0647\u064a \u0645\u0646 \u0627\u0644\u0642\u0628\u0627\u0626\u0644 \u0627\u0644\u062e\u0645\u0633 \u0627\u0644\u062a\u064a \u0644\u0645 \u064a\u064e\u0645\u0633\u064e\u0651\u0647\u0627 \u0633\u0628\u0627\u0621\u060c \u0648\u0644\u0645 \u062a\u062a\u0628\u0639 \u0644\u0645\u0644\u0643\u060c \u0648\u0644\u0645 \u062a\u064f\u0624\u062f\u0650\u0651 \u0625\u062a\u0627\u0648\u0629\u064b\u060c \u0645\u062b\u0644\u0647\u0627 \u0641\u064a \u0630\u0644\u0643 \u0645\u062b\u0644 \u0642\u0631\u064a\u0634 \u0648\u062e\u0632\u0627\u0639\u0629\u060c \u0648\u0643\u0627\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u064a\u0639\u0644\u0645 \u0641\u0648\u0642 \u0630\u0644\u0643 \u0623\u0646 \u062b\u0645\u0629 \u062a\u0636\u0627\u062f\u064b\u0627 \u0642\u062f\u064a\u0645\u064b\u0627 \u0628\u064a\u0646 \u0628\u0646\u064a \u0639\u0627\u0645\u0631 \u0648\u062b\u0642\u064a\u0641\u060c \u0641\u0625\u0630\u0627 \u0643\u0627\u0646\u062a \u062b\u0642\u064a\u0641 \u0642\u062f \u0627\u0645\u062a\u0646\u0639\u062a \u0639\u0644\u064a\u0647 \u0645\u0646 \u0627\u0644\u062f\u0627\u062e\u0644\u060c \u0641\u0644\u0645\u0627\u0630\u0627 \u0644\u0627 \u064a\u064f\u062d\u0627\u0648\u0644 \u062a\u0637\u0648\u064a\u0642\u0647\u0627 \u0645\u0646 \u0627\u0644\u062e\u0627\u0631\u062c \u0628\u0627\u0644\u0627\u0633\u062a\u0641\u0627\u062f\u0629 \u0645\u0646 \u0628\u0646\u064a \u0639\u0627\u0645\u0631 \u0628\u0646 \u0635\u0639\u0635\u0639\u0629\u061f \u0648\u0625\u0630\u0627 \u0623\u0628\u0631\u0645 \u0627\u0644\u0646\u0628\u064a \ufdfa \u062d\u0644\u0641\u064b\u0627 \u0645\u0639 \u0628\u0646\u064a \u0639\u0627\u0645\u0631\u060c \u0635\u0627\u0631 \u0645\u0648\u0642\u0641 \u062b\u0642\u064a\u0641 \u0639\u0644\u0649 \u062d\u0627\u0641\u0629 \u0627\u0644\u062e\u0637\u0631.","\u0648\u064a\u0630\u0643\u0631 \u0623\u0635\u062d\u0627\u0628 \u0627\u0644\u0633\u064a\u0631\u0629 \u0623\u0646 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0644\u0645\u0627 \u0623\u062a\u0649 \u0628\u0646\u064a \u0639\u0627\u0645\u0631 \u0628\u0646 \u0635\u0639\u0635\u0639\u0629\u060c \u062f\u0639\u0627\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0644\u0647 \u0648\u0639\u0631\u0636 \u0639\u0644\u064a\u0647\u0645 \u0646\u0641\u0633\u0647\u060c \u0641\u0642\u0627\u0644 \u0644\u0647 \u0631\u062c\u0644 \u0645\u0646\u0647\u0645 \u064a\u064f\u0642\u0627\u0644 \u0644\u0647 \u0628\u064e\u064a\u062d\u064e\u0631\u0629 \u0628\u0646 \u0641\u0650\u0631\u0627\u0633: \u0648\u0627\u0644\u0644\u0647 \u0644\u0648 \u0623\u0646\u064a \u0623\u062e\u0630\u062a \u0647\u0630\u0627 \u0627\u0644\u0641\u062a\u0649 \u0644\u0623\u0643\u0644\u062a \u0628\u0647 \u0627\u0644\u0639\u0631\u0628\u060c \u062b\u0645 \u0642\u0627\u0644: \u0623\u0631\u0623\u064a\u062a \u0625\u0646 \u0646\u062d\u0646 \u0628\u0627\u064a\u0639\u0646\u0627\u0643 \u0639\u0644\u0649 \u0623\u0645\u0631\u0643 \u062b\u0645 \u0623\u0638\u0647\u0631\u0643 \u0627\u0644\u0644\u0647 \u0639\u0644\u0649 \u0645\u0646 \u062e\u0627\u0644\u0641\u0643\u060c \u0623\u064a\u0643\u0648\u0646 \u0644\u0646\u0627 \u0627\u0644\u0623\u0645\u0631 \u0645\u0646 \u0628\u0639\u062f\u0643\u061f \u0641\u0642\u0627\u0644 \ufdfa: \xab\u0627\u0644\u0623\u0645\u0631 \u0644\u0644\u0647 \u064a\u0636\u0639\u0647 \u062d\u064a\u062b \u064a\u0634\u0627\u0621\xbb\u060c \u0641\u0642\u0627\u0644 \u0628\u064e\u064a\u062d\u064e\u0631\u0629: \u0623\u0641\u064e\u0646\u064f\u0647\u062f\u0650\u0641\u064f \u0646\u062d\u0648\u0631\u0646\u0627 \u0644\u0644\u0639\u0631\u0628 \u062f\u0648\u0646\u0643\u060c \u0641\u0625\u0630\u0627 \u0623\u0638\u0647\u0631\u0643 \u0627\u0644\u0644\u0647 \u0643\u0627\u0646 \u0627\u0644\u0623\u0645\u0631 \u0644\u063a\u064a\u0631\u0646\u0627\u061f \u0644\u0627 \u062d\u0627\u062c\u0629 \u0644\u0646\u0627 \u0628\u0623\u0645\u0631\u0643\u060c \u0641\u0623\u0628\u064e\u0648\u0627 \u0639\u0644\u064a\u0647."],t.s)
