B.aLg=s(["\u0643\u0627\u0646\u062a \u0627\u0644\u0628\u0646\u0648\u062f \u0627\u0644\u062e\u0645\u0633\u0629 \u0644\u0644\u0628\u064a\u0639\u0629 \u0645\u0646 \u0627\u0644\u0648\u0636\u0648\u062d \u0648\u0627\u0644\u0642\u0648\u0629 \u0628\u062d\u064a\u062b \u0644\u0627 \u062a\u0642\u0628\u0644 \u0627\u0644\u062a\u0645\u064a\u064a\u0639 \u0648\u0627\u0644\u062a\u0631\u0627\u062e\u064a\u060c \u0625\u0646\u0647 \u0627\u0644\u0633\u0645\u0639 \u0648\u0627\u0644\u0637\u0627\u0639\u0629 \u0641\u064a \u0627\u0644\u0646\u0634\u0627\u0637 \u0648\u0627\u0644\u0643\u0633\u0644\u060c \u0648\u0627\u0644\u0646\u0641\u0642\u0629 \u0641\u064a \u0627\u0644\u064a\u0633\u0631 \u0648\u0627\u0644\u0639\u0633\u0631\u060c \u0648\u0627\u0644\u0623\u0645\u0631 \u0628\u0627\u0644\u0645\u0639\u0631\u0648\u0641 \u0648\u0627\u0644\u0646\u0647\u064a \u0639\u0646 \u0627\u0644\u0645\u0646\u0643\u0631\u060c \u0648\u0627\u0644\u0642\u064a\u0627\u0645 \u0641\u064a \u0627\u0644\u0644\u0647 \u0644\u0627 \u062a\u0623\u062e\u0630\u0647\u0645 \u0641\u064a\u0647 \u0644\u0648\u0645\u0629 \u0644\u0627\u0626\u0645\u060c \u0648\u0646\u0635\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \u0648\u062d\u0645\u0627\u064a\u062a\u0647 \u0625\u0630\u0627 \u0642\u064e\u062f\u0650\u0645 \u0627\u0644\u0645\u062f\u064a\u0646\u0629.","\u0648\u0633\u0631\u0639\u0627\u0646 \u0645\u0627 \u0627\u0633\u062a\u062c\u0627\u0628 \u0642\u0627\u0626\u062f \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0627\u0644\u0628\u0631\u0627\u0621 \u0628\u0646 \u0645\u0639\u0631\u0648\u0631 \u062f\u0648\u0646 \u062a\u0631\u062f\u062f\u060c \u0642\u0627\u0626\u0644\u0627\u064b: \u0648\u0627\u0644\u0630\u064a \u0628\u0639\u062b\u0643 \u0628\u0627\u0644\u062d\u0642 \u0644\u0646\u0645\u0646\u0639\u0646\u0643 \u0645\u0645\u0627 \u0646\u0645\u0646\u0639 \u0645\u0646\u0647 \u0623\u064f\u0632\u0631\u064e\u0646\u0627\u060c \u0641\u0628\u0627\u064a\u0639\u0646\u0627 \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u060c \u0641\u0646\u062d\u0646 \u0648\u0627\u0644\u0644\u0647 \u0623\u0628\u0646\u0627\u0621 \u0627\u0644\u062d\u0631\u0628 \u0648\u0623\u0647\u0644 \u0627\u0644\u062d\u0644\u0642\u0629\u060c \u0648\u0631\u062b\u0646\u0627\u0647\u0627 \u0643\u0627\u0628\u0631\u064b\u0627 \u0639\u0646 \u0643\u0627\u0628\u0631\u060c \u0641\u0647\u0630\u0627 \u0632\u0639\u064a\u0645 \u0627\u0644\u0648\u0641\u062f \u064a\u0639\u0631\u0636 \u0625\u0645\u0643\u0627\u0646\u064a\u0627\u062a \u0642\u0648\u0645\u0647 \u0639\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0642\u0648\u0645\u0647 \u0623\u0628\u0646\u0627\u0621 \u0627\u0644\u062d\u0631\u0628 \u0648\u0627\u0644\u0633\u0644\u0627\u062d.","\u0648\u0645\u0645\u0627 \u062a\u062c\u062f\u0631 \u0627\u0644\u0625\u0634\u0627\u0631\u0629 \u0625\u0644\u064a\u0647 \u0641\u064a \u0623\u0645\u0631 \u0627\u0644\u0628\u0631\u0627\u0621 \u0623\u0646\u0647 \u0639\u0646\u062f\u0645\u0627 \u062c\u0627\u0621 \u0645\u0639 \u0642\u0648\u0645\u0647 \u0645\u0646 \u064a\u062b\u0631\u0628 \u0642\u0627\u0644 \u0644\u0647\u0645: \u0625\u0646\u064a \u0642\u062f \u0631\u0623\u064a\u062a \u0631\u0623\u064a\u064b\u0627 \u0641\u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0623\u0631\u0649 \u0623\u062a\u0648\u0627\u0641\u0642\u0648\u0646\u064a \u0639\u0644\u064a\u0647 \u0623\u0645 \u0644\u0627\u061f \u0641\u0642\u0627\u0644\u0648\u0627: \u0648\u0645\u0627 \u0630\u0627\u0643\u061f \u0642\u0627\u0644: \u0642\u062f \u0631\u0623\u064a\u062a \u0623\u0646 \u0644\u0627 \u0623\u062f\u0639 \u0647\u0630\u0647 \u0627\u0644\u0628\u0646\u064a\u0629 -\u064a\u0639\u0646\u064a \u0627\u0644\u0643\u0639\u0628\u0629- \u0645\u0646\u064a \u0628\u0638\u064e\u0647\u0631\u060c \u0648\u0623\u0646 \u0623\u0635\u0644\u064a \u0625\u0644\u064a\u0647\u0627\u060c \u0641\u0642\u0627\u0644\u0648\u0627 \u0644\u0647: \u0648\u0627\u0644\u0644\u0647 \u0645\u0627 \u0628\u0644\u063a\u0646\u0627 \u0623\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u064a\u0635\u0644\u064a \u0625\u0644\u0627 \u0625\u0644\u0649 \u0627\u0644\u0634\u0627\u0645 \u0628\u0628\u064a\u062a \u0627\u0644\u0645\u0642\u062f\u0633\u060c \u0648\u0645\u0627 \u0646\u0631\u064a\u062f \u0623\u0646 \u0646\u062e\u0627\u0644\u0641\u0647\u060c \u0641\u0643\u0627\u0646\u0648\u0627 \u0625\u0630\u0627 \u062d\u0636\u0631\u062a \u0627\u0644\u0635\u0644\u0627\u0629 \u0635\u0644\u0648\u0627 \u0625\u0644\u0649 \u0628\u064a\u062a \u0627\u0644\u0645\u0642\u062f\u0633 \u0648\u0635\u0644\u0649 \u0647\u0648 \u0625\u0644\u0649 \u0627\u0644\u0643\u0639\u0628\u0629\u060c \u0648\u0627\u0633\u062a\u0645\u0631\u0648\u0627 \u0643\u0630\u0644\u0643 \u062d\u062a\u0649 \u0642\u062f\u0645\u0648\u0627 \u0645\u0643\u0629 \u0648\u062a\u0639\u0631\u0641\u0648\u0627 \u0625\u0644\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0647\u0648 \u062c\u0627\u0644\u0633 \u0645\u0639 \u0639\u0645\u0647 \u0627\u0644\u0639\u0628\u0627\u0633 \u0628\u0627\u0644\u0645\u0633\u062c\u062f \u0627\u0644\u062d\u0631\u0627\u0645\u060c \u0641\u0633\u0623\u0644 \u0627\u0644\u0646\u0628\u064a\u064f\u0651 \ufdfa \u0627\u0644\u0639\u0628\u0627\u0633\u064e: \xab\u0647\u0644 \u062a\u0639\u0631\u0641 \u0647\u0630\u064a\u0646 \u0627\u0644\u0631\u062c\u0644\u064a\u0646 \u064a\u0627 \u0623\u0628\u0627 \u0627\u0644\u0641\u0636\u0644\xbb\u060c \u0642\u0627\u0644: \u0646\u0639\u0645\u060c \u0647\u0630\u0627 \u0627\u0644\u0628\u0631\u0627\u0621 \u0628\u0646 \u0645\u0639\u0631\u0648\u0631 \u0633\u064a\u062f \u0642\u0648\u0645\u0647 \u0648\u0647\u0630\u0627 \u0643\u0639\u0628 \u0628\u0646 \u0645\u0627\u0644\u0643\u060c \u0641\u0642\u0627\u0644 \u0627\u0644\u0646\u0628\u064a \ufdfa: \xab\u0627\u0644\u0634\u0627\u0639\u0631\u061f\xbb\u060c \u0642\u0627\u0644: \u0646\u0639\u0645\u060c \u0641\u0642\u0635\u064e\u0651 \u0639\u0644\u064a\u0647 \u0627\u0644\u0628\u0631\u0627\u0621 \u0645\u0627 \u0635\u0646\u0639 \u0641\u064a \u0633\u0641\u0631\u0647 \u0645\u0646 \u0635\u0644\u0627\u062a\u0647 \u0625\u0644\u0649 \u0627\u0644\u0643\u0639\u0628\u0629\u060c \u0642\u0627\u0644: \u0641\u0645\u0627\u0630\u0627 \u062a\u0631\u0649 \u064a\u0627 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647\u061f \u0642\u0627\u0644: \xab\u0642\u062f \u0643\u0646\u062a \u0639\u0644\u0649 \u0642\u0628\u0644\u0629 \u0644\u0648 \u0635\u0628\u0631\u062a \u0639\u0644\u064a\u0647\u0627\xbb\u060c \u0642\u0627\u0644 \u0643\u0639\u0628: \u0641\u0631\u062c\u0639 \u0627\u0644\u0628\u0631\u0627\u0621 \u0625\u0644\u0649 \u0642\u0628\u0644\u0629 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0648\u0635\u0644\u0649 \u0645\u0639\u0646\u0627 \u0625\u0644\u0649 \u0627\u0644\u0634\u0627\u0645\u060c \u0641\u0644\u0645\u0627 \u062d\u0636\u0631\u062a\u0647 \u0627\u0644\u0648\u0641\u0627\u0629 \u0623\u0645\u0631 \u0623\u0647\u0644\u0647 \u0623\u0646 \u064a\u0648\u062c\u0647\u0648\u0647 \u0642\u0650\u0628\u064e\u0644 \u0627\u0644\u0643\u0639\u0628\u0629\u060c \u0648\u0645\u0627\u062a \u0641\u064a \u0635\u0641\u0631 \u0642\u0628\u0644 \u0642\u062f\u0648\u0645\u0647 \ufdfa \u0628\u0634\u0647\u0631\u060c \u0648\u0623\u0648\u0635\u0649 \u0628\u062b\u0644\u062b \u0645\u0627\u0644\u0647 \u0644\u0644\u0646\u0628\u064a \ufdfa \u0641\u0642\u0628\u0644\u0647 \u0648\u0631\u062f\u064e\u0651\u0647 \u0639\u0644\u0649 \u0648\u0644\u062f\u0647\u060c \u0648\u0647\u0648 \u0623\u0648\u0644 \u0645\u0646 \u0623\u0648\u0635\u0649 \u0628\u062b\u0644\u062b \u0645\u0627\u0644\u0647.","\u0648\u064a\u0633\u062a\u0648\u0642\u0641\u0646\u0627 \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062e\u0628\u0631 \u0623\u0645\u0631\u0627\u0646: \u0623\u0648\u0644\u0647\u0645\u0627 \u0627\u0644\u0627\u0646\u0636\u0628\u0627\u0637 \u0648\u0627\u0644\u0627\u0644\u062a\u0632\u0627\u0645 \u0645\u0646 \u0627\u0644\u0645\u0633\u0644\u0645\u064a\u0646 \u0628\u0633\u0644\u0648\u0643 \u0631\u0633\u0648\u0644\u0647\u0645 \u0648\u0623\u0648\u0627\u0645\u0631\u0647\u060c \u0648\u0623\u0646 \u0623\u064a \u0627\u0642\u062a\u0631\u0627\u062d \u0645\u0647\u0645\u0627 \u0643\u0627\u0646 \u0645\u0635\u062f\u0631\u0647 \u064a\u062a\u0639\u0627\u0631\u0636 \u0645\u0639 \u0630\u0644\u0643 \u064a\u064f\u0639\u062a\u0628\u0631 \u0645\u0631\u0641\u0648\u0636\u064b\u0627\u060c \u0648\u0647\u0630\u0647 \u0645\u0646 \u0623\u0648\u0644\u0648\u064a\u0627\u062a \u0627\u0644\u0641\u0642\u0647 \u0641\u064a \u062f\u064a\u0646 \u0627\u0644\u0644\u0647 \u062a\u0623\u062e\u0630 \u062d\u064a\u0632\u0647\u0627 \u0645\u0646 \u062d\u064a\u0627\u062a\u0647\u0645 \u0648\u0647\u0645 \u0628\u0639\u062f \u0645\u0627 \u0632\u0627\u0644\u0648\u0627 \u0641\u064a \u0628\u062f\u0627\u064a\u0629 \u0627\u0644\u0637\u0631\u064a\u0642\u060c \u0648\u062b\u0627\u0646\u064a\u0647\u0645\u0627 \u0623\u0646 \u0627\u0644\u0633\u064a\u0627\u062f\u0629 \u0644\u0645 \u062a\u0639\u062f \u0644\u0623\u062d\u062f \u063a\u064a\u0631 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa\u060c \u0648\u0623\u0646 \u062a\u0648\u0642\u064a\u0631 \u0623\u064a \u0625\u0646\u0633\u0627\u0646 \u0648\u0627\u062d\u062a\u0631\u0627\u0645\u0647 \u0625\u0646\u0645\u0627 \u0647\u0648 \u0627\u0646\u0639\u0643\u0627\u0633 \u0644\u0633\u0644\u0648\u0643\u0647 \u0648\u0627\u0644\u062a\u0632\u0627\u0645\u0647 \u0628\u0623\u0648\u0627\u0645\u0631 \u0627\u0644\u0631\u0633\u0648\u0644 \ufdfa\u060c \u0648\u0647\u0643\u0630\u0627 \u0628\u062f\u0623\u062a \u062a\u0646\u0632\u0627\u062d \u062a\u0642\u0627\u0644\u064a\u062f \u062c\u0627\u0647\u0644\u064a\u0629 \u0644\u062a\u062d\u0644 \u0645\u062d\u0644\u0647\u0627 \u0642\u064a\u0645 \u0625\u064a\u0645\u0627\u0646\u064a\u0629\u060c \u0641\u0647\u064a \u0627\u0644\u0645\u0642\u0627\u064a\u064a\u0633 \u0627\u0644\u062d\u0642\u0629 \u0627\u0644\u062a\u064a \u0628\u0647\u0627 \u064a\u0645\u0643\u0646 \u0627\u0644\u062d\u0643\u0645 \u0639\u0644\u0649 \u0627\u0644\u0646\u0627\u0633 \u062a\u0635\u0646\u064a\u0641\u064b\u0627 \u0648\u062a\u0631\u062a\u064a\u0628\u064b\u0627."],t.s)
