B.aCX=s(["\u0644\u0645 \u062a\u0643\u0646 \u0627\u0644\u0647\u062c\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629 \u0642\u0631\u0627\u0631\u0627\u064b \u0627\u0631\u062a\u062c\u0627\u0644\u064a\u0627\u064b\u060c \u0628\u0644 \u0633\u0628\u0642\u0647\u0627 \u0625\u0639\u062f\u0627\u062f\u064c \u062f\u0642\u064a\u0642\u064c \u0648\u062a\u062e\u0637\u064a\u0637\u064c \u0645\u064f\u062d\u0643\u064e\u0645 \u0645\u0646 \u0627\u0644\u0646\u0628\u064a \ufdfa \u060c \u0648\u0643\u0627\u0646 \u0630\u0644\u0643 \u0643\u0644\u0647 \u0628\u062a\u0642\u062f\u064a\u0631 \u0627\u0644\u0644\u0647 \u062a\u0639\u0627\u0644\u0649 \u0648\u062a\u062f\u0628\u064a\u0631\u0647\u060c \u0648\u0633\u0627\u0631 \u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u062f\u0627\u062f \u0641\u064a \u0627\u062a\u062c\u0627\u0647\u064e\u064a\u0646 \u0645\u062a\u0648\u0627\u0632\u064a\u064e\u064a\u0646: \u0625\u0639\u062f\u0627\u062f\u064c \u0641\u064a \u0634\u062e\u0635\u064a\u0629 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0623\u0646\u0641\u0633\u0647\u0645\u060c \u0648\u0625\u0639\u062f\u0627\u062f\u064c \u0641\u064a \u0627\u0644\u0645\u0643\u0627\u0646 \u0627\u0644\u0645\u064f\u0647\u0627\u062c\u064e\u0631 \u0625\u0644\u064a\u0647.","\u0648\u0644\u0645 \u062a\u0643\u0646 \u0627\u0644\u0647\u062c\u0631\u0629 \u0646\u0632\u0647\u0629\u064b \u0623\u0648 \u0631\u062d\u0644\u0629\u064b \u064a\u064f\u0631\u0648\u062d\u064e \u0641\u064a\u0647\u0627 \u0627\u0644\u0625\u0646\u0633\u0627\u0646 \u0639\u0646 \u0646\u0641\u0633\u0647\u060c \u0628\u0644 \u0643\u0627\u0646\u062a \u0645\u063a\u0627\u062f\u0631\u0629\u064b \u0644\u0644\u0623\u0631\u0636 \u0648\u0627\u0644\u0623\u0647\u0644\u060c \u0648\u0642\u0637\u0639\u0627\u064b \u0644\u0648\u0634\u0627\u0626\u062c \u0627\u0644\u0642\u0631\u0628\u0649 \u0648\u0635\u0644\u0627\u062a \u0627\u0644\u0635\u062f\u0627\u0642\u0629 \u0648\u0627\u0644\u0645\u0648\u062f\u0629\u060c \u0648\u062a\u062e\u0644\u064a\u0627\u064b \u0639\u0646 \u0623\u0633\u0628\u0627\u0628 \u0627\u0644\u0631\u0632\u0642\u060c \u0643\u0644 \u0630\u0644\u0643 \u0645\u0646 \u0623\u062c\u0644 \u0627\u0644\u0639\u0642\u064a\u062f\u0629\u060c \u0648\u0644\u0647\u0630\u0627 \u0627\u062d\u062a\u0627\u062c\u062a \u0625\u0644\u0649 \u0625\u0639\u062f\u0627\u062f\u064d \u0628\u0627\u0644\u063a \u062d\u062a\u0649 \u064a\u0628\u0644\u063a \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u0648\u0646 \u0642\u0646\u0627\u0639\u0629\u064b \u0643\u0627\u0645\u0644\u0629 \u0628\u0647\u0627.","\u0648\u0645\u0646 \u062a\u0644\u0643 \u0648\u0633\u0627\u0626\u0644 \u0647\u0630\u0627 \u0627\u0644\u0625\u0639\u062f\u0627\u062f: \u0627\u0644\u062a\u0631\u0628\u064a\u0629 \u0627\u0644\u0625\u064a\u0645\u0627\u0646\u064a\u0629 \u0627\u0644\u0639\u0645\u064a\u0642\u0629 \u0627\u0644\u062a\u064a \u0634\u0643\u0651\u0644\u062a \u0648\u062c\u062f\u0627\u0646 \u0627\u0644\u0635\u062d\u0627\u0628\u0629\u060c \u0648\u0643\u0630\u0644\u0643 \u0627\u0644\u0627\u0636\u0637\u0647\u0627\u062f\u064f \u0627\u0644\u0630\u064a \u0623\u0635\u0627\u0628\u0647\u0645 \u062d\u062a\u0649 \u0648\u0635\u0644\u0648\u0627 \u0625\u0644\u0649 \u064a\u0642\u064a\u0646\u064d \u062a\u0627\u0645 \u0628\u0627\u0633\u062a\u062d\u0627\u0644\u0629 \u0627\u0644\u0645\u0639\u0627\u064a\u0634\u0629 \u0645\u0639 \u0627\u0644\u0643\u0641\u0631\u060c \u0641\u0636\u0644\u0627\u064b \u0639\u0646 \u062a\u0648\u062c\u064a\u0647 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0645\u0643\u064a \u0623\u0646\u0638\u0627\u0631\u0647\u0645 \u0625\u0644\u0649 \u0623\u0646 \u0623\u0631\u0636 \u0627\u0644\u0644\u0647 \u0648\u0627\u0633\u0639\u0629\u064c \u0644\u0645\u0646 \u0637\u0644\u0628 \u0627\u0644\u0639\u0632\u0629 \u0641\u064a \u062f\u064a\u0646\u0647\u060c \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0642\u064f\u0644 \u064a\u064e\u0627 \u0639\u0650\u0628\u064e\u0627\u062f\u0650 \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0622\u0645\u064e\u0646\u064f\u0648\u0627 \u0627\u062a\u0651\u064e\u0642\u064f\u0648\u0627 \u0631\u064e\u0628\u0651\u064e\u0643\u064f\u0645 \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0623\u064e\u062d\u0633\u064e\u0646\u064f\u0648\u0627 \u0641\u0650\u064a \u0647\u064e\u0670\u0630\u0650\u0647\u0650 \u0627\u0644\u062f\u0651\u064f\u0646\u064a\u064e\u0627 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064c \u0648\u064e\u0623\u064e\u0631\u0636\u064f \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0648\u064e\u0627\u0633\u0650\u0639\u064e\u0629\u064c \u0625\u0650\u0646\u0651\u064e\u0645\u064e\u0627 \u064a\u064f\u0648\u064e\u0641\u0651\u064e\u0649 \u0627\u0644\u0635\u0651\u064e\u0627\u0628\u0650\u0631\u064f\u0648\u0646\u064e \u0623\u064e\u062c\u0631\u064e\u0647\u064f\u0645 \u0628\u0650\u063a\u064e\u064a\u0631\u0650 \u062d\u0650\u0633\u064e\u0627\u0628\u064d\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0632\u0645\u0631.","\u062b\u0645 \u062c\u0627\u0621\u062a \u0633\u0648\u0631\u0629 \u0627\u0644\u0643\u0647\u0641 \u062a\u062d\u062f\u0651\u062b \u0639\u0646 \u0627\u0644\u0641\u062a\u064a\u0629 \u0627\u0644\u0630\u064a\u0646 \u0622\u0645\u0646\u0648\u0627 \u0628\u0631\u0628\u0647\u0645 \u0648\u0645\u0641\u0627\u0631\u0642\u062a\u0647\u0645 \u0628\u0644\u062f\u0647\u0645 \u0625\u0644\u0649 \u0627\u0644\u0643\u0647\u0641\u060c \u0641\u0627\u0633\u062a\u0642\u0631\u062a \u0641\u064a \u0646\u0641\u0648\u0633 \u0627\u0644\u0635\u062d\u0627\u0628\u0629 \u0635\u0648\u0631\u0629\u064c \u0645\u0646 \u0635\u0648\u0631 \u0627\u0644\u0625\u064a\u0645\u0627\u0646 \u062a\u062c\u0644\u0651\u062a \u0641\u064a \u062a\u0631\u0643 \u0627\u0644\u0623\u0647\u0644 \u0648\u0627\u0644\u0648\u0637\u0646 \u062b\u0645\u0646\u0627\u064b \u0644\u0644\u0639\u0642\u064a\u062f\u0629\u060c \u0648\u062a\u062a\u0627\u0628\u0639\u062a \u0628\u0639\u062f \u0630\u0644\u0643 \u0622\u064a\u0627\u062a\u064c \u0635\u0631\u064a\u062d\u0629 \u0641\u064a \u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u062d\u0644 \u062a\u062a\u062d\u062f\u062b \u0639\u0646 \u0627\u0644\u0647\u062c\u0631\u0629 \u0648\u062a\u0628\u0634\u0651\u0631 \u0628\u062c\u0632\u0627\u0621 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646\u060c \u0642\u0627\u0644 \u062a\u0639\u0627\u0644\u0649: \ufd3f\u0648\u064e\u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627 \u0641\u0650\u064a \u0627\u0644\u0644\u0651\u064e\u0647\u0650 \u0645\u0650\u0646 \u0628\u064e\u0639\u062f\u0650 \u0645\u064e\u0627 \u0638\u064f\u0644\u0650\u0645\u064f\u0648\u0627 \u0644\u064e\u0646\u064f\u0628\u064e\u0648\u0651\u0650\u0626\u064e\u0646\u0651\u064e\u0647\u064f\u0645 \u0641\u0650\u064a \u0627\u0644\u062f\u0651\u064f\u0646\u064a\u064e\u0627 \u062d\u064e\u0633\u064e\u0646\u064e\u0629\u064b \u0648\u064e\u0644\u064e\u0623\u064e\u062c\u0631\u064f \u0627\u0644\u0622\u062e\u0650\u0631\u064e\u0629\u0650 \u0623\u064e\u0643\u0628\u064e\u0631\u064f \u0644\u064e\u0648 \u0643\u064e\u0627\u0646\u064f\u0648\u0627 \u064a\u064e\u0639\u0644\u064e\u0645\u064f\u0648\u0646\u064e \u06dd \u0627\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u0648\u064e\u0639\u064e\u0644\u064e\u0649\u0670 \u0631\u064e\u0628\u0651\u0650\u0647\u0650\u0645 \u064a\u064e\u062a\u064e\u0648\u064e\u0643\u0651\u064e\u0644\u064f\u0648\u0646\u064e\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u062d\u0644\u060c \u062b\u0645 \u064a\u0624\u0643\u062f \u0627\u0644\u0645\u0639\u0646\u0649 \u0630\u0627\u062a\u0647 \u0641\u064a \u0623\u0648\u0627\u062e\u0631\u0647\u0627: \ufd3f\u062b\u064f\u0645\u0651\u064e \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0644\u0650\u0644\u0651\u064e\u0630\u0650\u064a\u0646\u064e \u0647\u064e\u0627\u062c\u064e\u0631\u064f\u0648\u0627 \u0645\u0650\u0646 \u0628\u064e\u0639\u062f\u0650 \u0645\u064e\u0627 \u0641\u064f\u062a\u0650\u0646\u064f\u0648\u0627 \u062b\u064f\u0645\u0651\u064e \u062c\u064e\u0627\u0647\u064e\u062f\u064f\u0648\u0627 \u0648\u064e\u0635\u064e\u0628\u064e\u0631\u064f\u0648\u0627 \u0625\u0650\u0646\u0651\u064e \u0631\u064e\u0628\u0651\u064e\u0643\u064e \u0645\u0650\u0646 \u0628\u064e\u0639\u062f\u0650\u0647\u064e\u0627 \u0644\u064e\u063a\u064e\u0641\u064f\u0648\u0631\u064c \u0631\u0651\u064e\u062d\u0650\u064a\u0645\u064c\ufd3e - \u0633\u0648\u0631\u0629 \u0627\u0644\u0646\u062d\u0644\u060c \u0648\u0643\u0627\u0646\u062a \u0627\u0644\u0647\u062c\u0631\u0629 \u0625\u0644\u0649 \u0627\u0644\u062d\u0628\u0634\u0629 \u062a\u062f\u0631\u064a\u0628\u0627\u064b \u0639\u0645\u0644\u064a\u0627\u064b \u0639\u0644\u0649 \u062a\u0631\u0643 \u0627\u0644\u0623\u0647\u0644 \u0648\u0627\u0644\u0648\u0637\u0646."],t.s)
