B.aNE=s(["\u0644\u0645 \u064a\u064f\u0633\u0627\u0631\u0639 \u0627\u0644\u0646\u0628\u064a \ufdfa \u0625\u0644\u0649 \u0627\u0644\u0627\u0646\u062a\u0642\u0627\u0644 \u0625\u0644\u0649 \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0645\u0646 \u0627\u0644\u0623\u064a\u0627\u0645 \u0627\u0644\u0623\u0648\u0644\u0649\u060c \u0628\u0644 \u0623\u062e\u0651\u0631 \u0630\u0644\u0643 \u0623\u0643\u062b\u0631 \u0645\u0646 \u0639\u0627\u0645\u064a\u0646\u060c \u062d\u062a\u0649 \u062a\u0623\u0643\u062f \u0645\u0646 \u0648\u062c\u0648\u062f \u0642\u0627\u0639\u062f\u0629\u064d \u0648\u0627\u0633\u0639\u0629\u064d \u0646\u0633\u0628\u064a\u0627\u064b\u060c \u0648\u0643\u0627\u0646 \u0641\u064a \u0627\u0644\u0648\u0642\u062a \u0646\u0641\u0633\u0647 \u064a\u064f\u062a\u0645\u0651 \u0625\u0639\u062f\u0627\u062f\u0647\u0627 \u0641\u064a \u0623\u062c\u0648\u0627\u0621 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0643\u0631\u064a\u0645\u060c \u0648\u0644\u0627 \u0633\u064a\u0645\u0627 \u0628\u0639\u062f \u0627\u0646\u062a\u0642\u0627\u0644 \u0645\u0635\u0639\u0628 \u0625\u0644\u0649 \u0627\u0644\u0645\u062f\u064a\u0646\u0629.","\u0648\u062a\u0623\u0643\u0651\u062f \u0623\u0646 \u0627\u0633\u062a\u0639\u062f\u0627\u062f \u0627\u0644\u0623\u0646\u0635\u0627\u0631 \u0628\u0644\u063a \u0643\u0645\u0627\u0644\u0647 \u0628\u0637\u0644\u0628\u0647\u0645 \u0647\u062c\u0631\u0629\u064e \u0627\u0644\u0646\u0628\u064a \u0627\u0644\u0643\u0631\u064a\u0645 \u0625\u0644\u064a\u0647\u0645\u060c \u0643\u0645\u0627 \u0643\u0634\u0641\u062a \u0627\u0644\u0645\u0646\u0627\u0642\u0634\u0627\u062a \u0627\u0644\u062a\u064a \u062c\u0631\u062a \u0641\u064a \u0628\u064a\u0639\u0629 \u0627\u0644\u0639\u0642\u0628\u0629 \u0627\u0644\u062b\u0627\u0646\u064a\u0629 \u0639\u0646 \u062d\u0631\u0635\u064d \u0634\u062f\u064a\u062f \u0645\u0646\u0647\u0645 \u0639\u0644\u0649 \u062a\u0623\u0643\u064a\u062f \u0627\u0644\u0628\u064a\u0639\u0629\u060c \u0648\u0627\u0644\u0627\u0633\u062a\u064a\u062b\u0627\u0642 \u0644\u0644\u0646\u0628\u064a \ufdfa \u0628\u0623\u0642\u0648\u0649 \u0627\u0644\u0645\u0648\u0627\u062b\u064a\u0642\u060c \u062d\u062a\u0649 \u0625\u0646\u0647\u0645 \u0623\u0631\u0627\u062f\u0648\u0627 \u0623\u0646 \u064a\u0645\u064a\u0644\u0648\u0627 \u0639\u0644\u0649 \u0623\u0647\u0644 \u0645\u0646\u0649 \u0645\u0645\u0646 \u0622\u0630\u0649 \u0631\u0633\u0648\u0644 \u0627\u0644\u0644\u0647 \ufdfa \u0628\u0623\u0633\u064a\u0627\u0641\u0647\u0645 \u0644\u0648 \u0623\u0630\u0646 \u0644\u0647\u0645 \u0628\u0630\u0644\u0643\u060c \u0641\u0642\u0627\u0644 \u0644\u0647\u0645: \xab\u0644\u0645 \u0623\u064f\u0624\u0645\u064e\u0631 \u0628\u0630\u0644\u0643\xbb\u060c \u0648\u0647\u0643\u0630\u0627 \u0623\u064f\u0639\u0650\u062f\u064e\u0651 \u0623\u0647\u0644 \u064a\u062b\u0631\u0628 \u0644\u064a\u0643\u0648\u0646\u0648\u0627 \u0642\u0627\u062f\u0631\u064a\u0646 \u0639\u0644\u0649 \u0627\u0633\u062a\u0642\u0628\u0627\u0644 \u0627\u0644\u0645\u0647\u0627\u062c\u0631\u064a\u0646 \u0648\u0645\u0627 \u064a\u062a\u0631\u062a\u0628 \u0639\u0644\u0649 \u0630\u0644\u0643 \u0645\u0646 \u062a\u0628\u0639\u0627\u062a."],t.s)
