B.aHI=s(["\u0627\u0646\u0637\u064e\u0644\u064e\u0642\u064e \u0627\u0644\u0646\u064e\u0651\u0628\u064a\u064f\u0651 \ufdfa \u0641\u064a \u0637\u064e\u0631\u064a\u0642\u0650\u0647\u0650 \u0645\u064f\u0647\u0627\u062c\u0650\u0631\u064b\u0627 \u0645\u0650\u0646 \u0645\u064e\u0643\u064e\u0651\u0629\u064e\u060c \u0641\u0644\u064e\u0642\u0650\u064a\u064e \u0627\u0644\u0632\u064f\u0651\u0628\u064e\u064a\u0631\u064e \u0628\u0646\u064e \u0627\u0644\u0639\u064e\u0648\u064e\u0651\u0627\u0645\u0650 \u0641\u064a \u0631\u064e\u0643\u0628\u064d \u0645\u0650\u0646\u064e \u0627\u0644\u0645\u064f\u0633\u0644\u0650\u0645\u064a\u0646\u064e\u060c \u0643\u0627\u0646\u0648\u0627 \u062a\u064f\u062c\u064e\u0651\u0627\u0631\u064b\u0627 \u0642\u0627\u0641\u0650\u0644\u064a\u0646\u064e \u0645\u0650\u0646 \u0623\u064e\u0631\u0636\u0650 \u0627\u0644\u0634\u064e\u0651\u0627\u0645\u0650\u060c \u0641\u0644\u064e\u0645\u064e\u0651\u0627 \u0631\u064e\u0622\u0647\u064f\u0645\u0627 \u0627\u0644\u0632\u064f\u0651\u0628\u064e\u064a\u0631\u064f\u060c \u0623\u064e\u0633\u0631\u064e\u0639\u064e \u064a\u064e\u0643\u0633\u0648\u0647\u064f\u0645\u0627 \u0645\u0650\u0646 \u0646\u064e\u0641\u0627\u0626\u0650\u0633\u0650 \u0645\u0627 \u062d\u064e\u0645\u064e\u0644\u064e\u060c \u0641\u0643\u064e\u0633\u0627 \u0631\u064e\u0633\u0648\u0644\u064e \u0627\u0644\u0644\u0647\u0650 \ufdfa \u0648\u0623\u0628\u0627 \u0628\u064e\u0643\u0631\u064d \u062b\u0650\u064a\u0627\u0628\u064b\u0627 \u0628\u064e\u064a\u0636\u0627\u0621\u064e\u060c \u0648\u0643\u0627\u0646\u064e \u0647\u0630\u0627 \u0627\u0644\u0644\u0650\u0651\u0642\u0627\u0621\u064f \u064a\u064f\u0628\u064e\u0634\u0650\u0651\u0631\u064f \u0628\u0627\u0644\u062e\u064e\u064a\u0631\u0650 \u0642\u064e\u0628\u0644\u064e \u062f\u064f\u062e\u0648\u0644\u0650 \u0627\u0644\u0645\u064e\u062f\u064a\u0646\u064e\u0629\u0650.","\u0648\u0642\u062f \u0633\u064e\u0645\u0650\u0639\u064e \u0627\u0644\u0645\u064f\u0633\u0644\u0650\u0645\u0648\u0646\u064e \u0628\u0627\u0644\u0645\u064e\u062f\u064a\u0646\u064e\u0629\u0650 \u0628\u0645\u064e\u062e\u0631\u064e\u062c\u0650 \u0631\u064e\u0633\u0648\u0644\u0650 \u0627\u0644\u0644\u0647\u0650 \ufdfa \u0645\u0650\u0646 \u0645\u064e\u0643\u064e\u0651\u0629\u064e\u060c \u0641\u0645\u0627 \u0643\u0627\u0646\u064e \u0645\u0650\u0646\u0647\u0645 \u0625\u0644\u064e\u0651\u0627 \u0623\u0646 \u0627\u0646\u062a\u064e\u0638\u064e\u0631\u0648\u0647\u064f \u0628\u0635\u0650\u062f\u0642\u064d \u0648\u0634\u064e\u0648\u0642\u064d\u060c \u064a\u064e\u063a\u062f\u064f\u0648\u0646\u064e \u0643\u064f\u0644\u064e\u0651 \u063a\u064e\u062f\u0627\u0629\u064d \u0625\u0644\u0649 \u0627\u0644\u062d\u064e\u0631\u064e\u0651\u0629\u0650\u060c \u0648\u0647\u064a \u0623\u0631\u0636\u064c \u0645\u064e\u0644\u0633\u0627\u0621\u064f \u0630\u0627\u062a\u064f \u062d\u0650\u062c\u0627\u0631\u064e\u0629\u064d \u0633\u064e\u0648\u062f\u0627\u0621\u064e \u062a\u064e\u0645\u062a\u064e\u062f\u064f\u0651 \u0634\u064e\u0631\u0642\u064e \u0627\u0644\u0645\u064e\u062f\u064a\u0646\u064e\u0629\u0650 \u0639\u0650\u0646\u062f\u064e \u0642\u064f\u0628\u0627\u0621\u064d\u060c \u0641\u064a\u064e\u0646\u062a\u064e\u0638\u0650\u0631\u0648\u0646\u064e \u0641\u064a\u0647\u0627 \u0642\u064f\u062f\u0648\u0645\u064e\u0647\u064f \ufdfa\u060c \u062d\u062a\u064e\u0651\u0649 \u064a\u064e\u0631\u064f\u062f\u064e\u0651\u0647\u0645 \u062d\u064e\u0631\u064f\u0651 \u0627\u0644\u0638\u064e\u0651\u0647\u064a\u0631\u064e\u0629\u0650 \u0625\u0644\u0649 \u062f\u0650\u064a\u0627\u0631\u0650\u0647\u0645\u060c \u0648\u0645\u0627 \u064a\u064e\u0632\u0627\u0644\u064f \u0627\u0644\u0634\u064e\u0651\u0648\u0642\u064f \u064a\u064e\u062f\u0641\u064e\u0639\u064f\u0647\u0645 \u0625\u0644\u0649 \u062a\u0650\u0644\u0643\u064e \u0627\u0644\u062d\u064e\u0631\u064e\u0651\u0629\u0650 \u064a\u064e\u0648\u0645\u064b\u0627 \u0628\u064e\u0639\u062f\u064e \u064a\u064e\u0648\u0645\u064d.","\u062d\u062a\u064e\u0651\u0649 \u0643\u0627\u0646\u064e \u064a\u064e\u0648\u0645\u064c \u0645\u0650\u0646 \u062a\u0650\u0644\u0643\u064e \u0627\u0644\u0623\u064a\u064e\u0651\u0627\u0645\u0650\u060c \u0637\u0627\u0644\u064e \u0641\u064a\u0647\u0650 \u0627\u0646\u062a\u0650\u0638\u0627\u0631\u064f\u0647\u0645\u060c \u0641\u0627\u0646\u0642\u064e\u0644\u064e\u0628\u064f\u0648\u0627 \u0639\u0627\u0626\u0650\u062f\u064a\u0646\u064e \u0625\u0644\u0649 \u0628\u064f\u064a\u0648\u062a\u0650\u0647\u0645\u060c \u0641\u0644\u064e\u0645\u064e\u0651\u0627 \u0623\u064e\u0648\u064e\u0648\u0627 \u0625\u0644\u064a\u0647\u0627\u060c \u0635\u064e\u0639\u0650\u062f\u064e \u0631\u064e\u062c\u064f\u0644\u064c \u0645\u0650\u0646 \u0627\u0644\u064a\u064e\u0647\u0648\u062f\u0650 \u0639\u0644\u0649 \u0623\u064f\u0637\u064f\u0645\u064d \u0645\u0650\u0646 \u0622\u0637\u0627\u0645\u0650\u0647\u0650 -\u062d\u0650\u0635\u0646\u064d \u0645\u0650\u0646 \u062d\u064f\u0635\u0648\u0646\u0650\u0647\u0650- \u0644\u0623\u064e\u0645\u0631\u064d \u0643\u0627\u0646\u064e \u064a\u064e\u0646\u0638\u064f\u0631\u064f \u0625\u0644\u064a\u0647\u0650\u060c \u0641\u0628\u064e\u0635\u064f\u0631\u064e \u0628\u0631\u064e\u0633\u0648\u0644\u0650 \u0627\u0644\u0644\u0647\u0650 \ufdfa \u0648\u0623\u064e\u0635\u062d\u0627\u0628\u0650\u0647\u0650 \u0645\u064f\u0628\u064e\u064a\u064e\u0651\u0636\u064a\u0646\u064e -\u0623\u064e\u064a \u0639\u0644\u064a\u0647\u0650\u0645\u064f \u0627\u0644\u062b\u0650\u0651\u064a\u0627\u0628\u064f \u0627\u0644\u0628\u064e\u064a\u0636\u0627\u0621\u064f \u0627\u0644\u062a\u064a \u0643\u064e\u0633\u0627\u0647\u064f\u0645\u064f \u0627\u0644\u0632\u064f\u0651\u0628\u064e\u064a\u0631\u064f-\u060c \u064a\u064e\u062a\u064e\u0631\u0627\u0621\u064e\u0648\u0646\u064e \u062e\u0650\u0644\u0627\u0644\u064e \u0627\u0644\u0633\u064e\u0651\u0631\u0627\u0628\u0650 -\u0645\u0627 \u064a\u064f\u0631\u0649 \u0641\u064a \u0634\u0650\u062f\u064e\u0651\u0629\u0650 \u0627\u0644\u062d\u064e\u0631\u0650\u0651 \u0641\u064a \u0623\u064f\u0641\u064f\u0642\u0650 \u0627\u0644\u0635\u0651\u064e\u062d\u0631\u0627\u0621\u0650 \u0643\u0623\u064e\u0646\u064e\u0651\u0647\u064f \u0645\u0627\u0621\u064c- \u0641\u0635\u0627\u062d\u064e \u0628\u0623\u064e\u0639\u0644\u0649 \u0635\u064e\u0648\u062a\u0650\u0647\u0650\u060c \u064a\u0627 \u0645\u064e\u0639\u0627\u0634\u0650\u0631\u064e \u0627\u0644\u0639\u064e\u0631\u064e\u0628\u0650\u060c \u0647\u0630\u0627 \u062c\u064e\u062f\u064f\u0651\u0643\u064f\u0645\u064f \u0627\u0644\u0630\u064a \u062a\u064e\u0646\u062a\u064e\u0638\u0650\u0631\u0648\u0646\u064e - \u0623\u064e\u064a \u062d\u064e\u0638\u064f\u0651\u0643\u064f\u0645\u064f \u0648\u0635\u0627\u062d\u0650\u0628\u064f \u062f\u064e\u0648\u0644\u064e\u062a\u0650\u0643\u064f\u0645\u064f \u0627\u0644\u0630\u064a \u062a\u064e\u0646\u062a\u064e\u0638\u0650\u0631\u0648\u0646\u064e \u0642\u064f\u062f\u0648\u0645\u064e\u0647\u064f \u0642\u062f \u0623\u064e\u0642\u0628\u064e\u0644\u064e.","\u0641\u0645\u0627 \u0647\u064a \u0625\u0644\u064e\u0651\u0627 \u0644\u064e\u062d\u0638\u064e\u0629\u064c\u060c \u062d\u062a\u064e\u0651\u0649 \u062b\u0627\u0631\u064e \u0627\u0644\u0645\u064f\u0633\u0644\u0650\u0645\u0648\u0646\u064e \u0625\u0644\u0649 \u0627\u0644\u0633\u0650\u0651\u0644\u0627\u062d\u0650\u060c \u064a\u064e\u062d\u0645\u0650\u0644\u0648\u0646\u064e\u0647\u064f \u0644\u064a\u064e\u062d\u0631\u064f\u0633\u0648\u0627 \u0631\u064e\u0633\u0648\u0644\u064e \u0627\u0644\u0644\u0647\u0650 \ufdfa \u0645\u0650\u0646 \u0645\u064e\u0643\u0631\u0650 \u0627\u0644\u064a\u064e\u0647\u0648\u062f\u0650\u060c \u0641\u0627\u0633\u062a\u064e\u0642\u0628\u064e\u0644\u0648\u0647\u064f \ufdfa \u0641\u064e\u0648\u0642\u064e \u0627\u0644\u062d\u064e\u0631\u064e\u0651\u0629\u0650\u060c \u062b\u064f\u0645\u064e\u0651 \u0645\u0627\u0644\u064e \u0628\u0647\u0650\u0645\u064f \u0630\u0627\u062a\u064e \u0627\u0644\u064a\u064e\u0645\u064a\u0646\u0650\u060c \u062d\u062a\u064e\u0651\u0649 \u0646\u064e\u0632\u064e\u0644\u064e \u0628\u0647\u0650\u0645 \u0641\u064a \u0628\u064e\u0646\u064a \u0639\u064e\u0645\u0631\u0650\u0648 \u0628\u0646\u0650 \u0639\u064e\u0648\u0641\u0650 \u0628\u0646\u0650 \u0645\u0627\u0644\u0650\u0643\u064d \u0627\u0644\u0623\u064e\u0648\u0633\u064a\u0650\u0651\u060c \u0639\u0650\u0646\u062f\u064e \u0627\u0634\u062a\u0650\u062f\u0627\u062f\u0650 \u0627\u0644\u0636\u064f\u0651\u062d\u0649 \u0642\u064e\u0628\u0644\u064e \u0627\u0644\u0632\u064e\u0651\u0648\u0627\u0644\u0650\u060c \u0648\u0643\u0627\u0646\u064e \u0630\u0644\u0650\u0643\u064e \u064a\u064e\u0648\u0645\u064e \u0627\u0644\u0627\u062b\u0646\u064e\u064a\u0646\u0650 \u0645\u0650\u0646 \u0634\u064e\u0647\u0631\u0650 \u0631\u064e\u0628\u064a\u0639\u064d \u0627\u0644\u0623\u064e\u0648\u064e\u0651\u0644\u0650."],t.s)
