B.aNz=s(["\u0627\u0644\u062d\u0645\u062f \u0644\u0644\u0647 \u0627\u0644\u062d\u0645\u062f \u0644\u0644\u0647.","\u0627\u0644\u062d\u0645\u062f \u0644\u0644\u0647 \u064a\u0627\u0631\u0628 \u0643\u0645\u0627 \u064a\u0646\u0628\u063a\u064a \u0644\u062c\u0644\u0627\u0644 \u0648\u062c\u0647\u0643 \u0648\u0644\u0639\u0638\u064a\u0645 \u0633\u0644\u0637\u0627\u0646\u0643.","\u0627\u0644\u0644\u0647\u0645 \u0635\u0650\u0644 \u0648\u0633\u0644\u0645 \u0648\u0628\u064e\u0627\u0631\u0643 \u0639\u0644\u0649 \u0633\u064e\u064a\u062f\u0650\u0646\u0627 \u0645\u064f\u062d\u064e\u0645\u064e\u0651\u062f.","\u0627\u0644\u0644\u0647\u0645\u064e\u0651 \u0623\u0639\u0650\u0646\u064e\u0651\u0627 \u0639\u0644\u0649 \u0630\u0650\u0643\u0631\u0643 \u0648\u0634\u064f\u0643\u0631\u0643 \u0648\u062d\u064f\u0633\u0646 \u0639\u0628\u0627\u062f\u062a\u0643.","\u0627\u0644\u0644\u0647\u0645\u064e\u0651 \u0625\u0646\u0643 \u0639\u0641\u0648 \u0643\u0631\u064a\u0645 \u062a\u064f\u062d\u0628 \u0627\u0644\u0639\u0641\u0648 \u0641\u0623\u0639\u0641\u064f \u0639\u0646\u0651\u0627.","\u0627\u0644\u0644\u0647\u0645\u064e\u0651 \u0625\u0646\u0650\u0651\u064a \u0623\u0633\u0623\u0644\u064f\u0643 \u0645\u0646 \u0627\u0644\u062e\u064a\u0631\u0650 \u0643\u0644\u0650\u0651\u0647 \u0639\u0627\u062c\u0644\u0650\u0647 \u0648\u0622\u062c\u0644\u0650\u0647 \u0645\u0627 \u0639\u0644\u0650\u0645\u062a\u064f \u0645\u0646\u0647 \u0648\u0645\u0627 \u0644\u0645 \u0623\u0639\u0644\u0645\u064f \u060c \u0648\u0623\u0639\u0648\u0630\u064f \u0628\u0643 \u0645\u0646 \u0627\u0644\u0634\u0631\u0650\u0651 \u0643\u0644\u0650\u0651\u0647 \u0639\u0627\u062c\u0644\u0650\u0647 \u0648\u0622\u062c\u0644\u0650\u0647 \u0645\u0627 \u0639\u0644\u0650\u0645\u062a\u064f \u0645\u0646\u0647 \u0648\u0645\u0627 \u0644\u0645 \u0623\u0639\u0644\u0645\u064f.","\u0627\u0644\u0644\u0647\u0645\u064e\u0651 \u0625\u0646\u0650\u0651\u064a \u0623\u0633\u0623\u0644\u064f\u0643 \u0645\u0646 \u062e\u064a\u0631\u0650 \u0645\u0627 \u0633\u0623\u0644\u064e\u0643 \u0628\u0647 \u0639\u0628\u062f\u064f\u0643 \u0648\u0646\u0628\u064a\u0643 \u060c \u0648\u0623\u0639\u0648\u0630\u064f \u0628\u0643 \u0645\u0646 \u0634\u0631\u0650\u0651 \u0645\u0627 \u0639\u0627\u0630 \u0628\u0647 \u0639\u0628\u062f\u064f\u0643 \u0648\u0646\u0628\u064a\u064f\u0651\u0643.","\u0627\u0644\u0644\u0647\u0645\u064e\u0651 \u0625\u0646\u0650\u0651\u064a \u0623\u0633\u0623\u0644\u064f\u0643 \u0627\u0644\u062c\u0646\u0629\u064e \u0648\u0645\u0627 \u0642\u0631\u064e\u0651\u0628 \u0625\u0644\u064a\u0647\u0627 \u0645\u0646 \u0642\u0648\u0644\u064d \u0623\u0648 \u0639\u0645\u0644\u064d \u060c \u0648\u0623\u0639\u0648\u0630\u064f \u0628\u0643 \u0645\u0646 \u0627\u0644\u0646\u0627\u0631\u0650 \u0648\u0645\u0627 \u0642\u0631\u064e\u0651\u0628 \u0625\u0644\u064a\u0647\u0627 \u0645\u0646 \u0642\u0648\u0644\u064d \u0623\u0648 \u0639\u0645\u0644\u064d \u060c \u0648\u0623\u0633\u0623\u0644\u064f\u0643 \u0623\u0646 \u062a\u062c\u0639\u0644\u064e \u0643\u0644\u064e\u0651 \u0642\u0636\u0627\u0621\u064d \u0642\u0636\u064a\u062a\u064e\u0647 \u0644\u064a \u062e\u064a\u0631\u064b\u0627.","\u0644\u0627 \u0625\u0644\u0647\u064e \u0625\u0644\u0627 \u0623\u0646\u062a \u0633\u064f\u0628\u062d\u0627\u0646\u0643 \u0625\u0646\u0651\u064a \u0643\u064f\u0646\u062a \u0645\u0646 \u0627\u0644\u0638\u0627\u0644\u0650\u0645\u064a\u0646.","\u0627\u0644\u0644\u0647\u0645\u064e\u0651 \u064a\u0627 \u0645\u064f\u0642\u0644\u0628 \u0627\u0644\u0642\u0644\u0648\u0628 \u062b\u0628\u062a \u0642\u0644\u0628\u0649 \u0639\u0644\u0649 \u062f\u064a\u0646\u0643.","\u0627\u0644\u0644\u0647\u0645\u064e\u0651 \u0623\u0639\u0648\u0630 \u0628\u0631\u0636\u0627\u0643 \u0645\u0646 \u0633\u062e\u0637\u0643\u060c \u0648\u0628\u0645\u0639\u0627\u0641\u0627\u062a\u0643 \u0645\u0646 \u0639\u0642\u0648\u0628\u062a\u0643\u060c \u0648\u0623\u0639\u0648\u0630 \u0628\u0643 \u0645\u0646\u0643\u060c \u0644\u0627 \u0623\u062d\u0635\u064a \u062b\u0646\u0627\u0621 \u0639\u0644\u064a\u0643 \u0623\u0646\u062a \u0643\u0645\u0627 \u0623\u062b\u0646\u064a\u062a \u0639\u0644\u0649 \u0646\u0641\u0633\u0643.","\u0627\u0644\u0644\u0647\u0645\u064e\u0651 \u0625\u0646\u064a \u0639\u0628\u062f\u0643 \u0648\u0627\u0628\u0646 \u0639\u0628\u062f\u0643 \u0648\u0627\u0628\u0646 \u0623\u0645\u062a\u0643\u060c \u0646\u0627\u0635\u064a\u062a\u064a \u0628\u064a\u062f\u0643\u060c \u0645\u0627\u0636\u064d \u0641\u064a\u064e\u0651 \u062d\u0643\u0645\u0643\u060c \u0639\u062f\u0644 \u0641\u064a\u0651 \u0642\u0636\u0627\u0624\u0643\u060c \u0623\u0633\u0623\u0644\u0643 \u0628\u0643\u0644 \u0627\u0633\u0645 \u0647\u0648 \u0644\u0643\u060c \u0633\u0645\u0651\u064a\u062a \u0628\u0647 \u0646\u0641\u0633\u0643\u060c \u0623\u0648 \u0623\u0646\u0632\u0644\u062a\u0647 \u0641\u064a \u0643\u062a\u0627\u0628\u0643\u060c \u0623\u0648 \u0639\u0644\u0651\u0645\u062a\u0647 \u0623\u062d\u062f\u0627\u064b \u0645\u0646 \u062e\u0644\u0642\u0643\u060c \u0623\u0648 \u0627\u0633\u062a\u0623\u062b\u0631\u062a\u064e \u0628\u0647 \u0641\u064a \u0639\u0644\u0645 \u0627\u0644\u063a\u064a\u0628 \u0639\u0646\u062f\u0643\u060c \u0623\u0646 \u062a\u062c\u0639\u0644 \u0627\u0644\u0642\u0631\u0622\u0646 \u0627\u0644\u0639\u0638\u064a\u0645 \u0631\u0628\u064a\u0639 \u0642\u0644\u0628\u064a\u060c \u0648\u0646\u0648\u0631 \u0635\u062f\u0631\u064a\u060c \u0648\u062c\u0644\u0627\u0621 \u062d\u0632\u0646\u064a \u0648\u0630\u0647\u0627\u0628 \u0647\u0645\u0651\u064a \u0648\u063a\u0645\u0651\u064a.","\u0627\u0644\u0644\u0647\u0645\u064e\u0651 \u0623\u0631\u0632\u0642\u0646\u0627 \u0627\u0644\u0623\u062e\u0644\u0627\u0635 \u0641\u0649 \u0643\u0644 \u0642\u0648\u0644 \u0648\u0641\u0639\u0644 \u0648\u0639\u0645\u0644.","\u0627\u0644\u0644\u0647\u0645\u064e\u0651 \u0625\u0646\u0650\u0651\u064a \u0623\u0633\u0623\u0644\u064f\u0643 \u0628\u0623\u0646\u0650\u0651\u064a \u0623\u0634\u0647\u062f\u064f \u0623\u0646\u0643 \u0623\u0646\u062a \u0627\u0644\u0644\u0647 \u0644\u0627 \u0625\u0644\u064e\u0647\u064e \u0625\u0644\u0627 \u0623\u0646\u062a \u0627\u0644\u0623\u062d\u062f\u064f \u0627\u0644\u0635\u064e\u0651\u0645\u062f\u064f\u060c \u0627\u0644\u0630\u064a \u0644\u0645 \u064a\u0644\u062f \u0648\u0644\u0645 \u064a\u0648\u0644\u062f \u0648\u0644\u0645 \u064a\u0643\u0646 \u0644\u0647 \u0643\u0641\u0648\u0627 \u0623\u062d\u062f\u064c.","\u0627\u0644\u0644\u0647\u0645\u064e\u0651 \u0623\u062d\u0633\u0646 \u0639\u0627\u0642\u0628\u062a\u0646\u0627 \u0641\u0649 \u0627\u0644\u0623\u0645\u0648\u0631 \u0643\u064f\u0644\u0647\u0627\u060c \u0648\u0623\u062c\u0631\u0646\u0627 \u0645\u0646 \u062e\u0632\u0649\u0650 \u0627\u0644\u062f\u0646\u064a\u0627 \u0648\u0639\u0630\u0627\u0628 \u0627\u0644\u0622\u062e\u0631\u0629.","\u0627\u0644\u0644\u0647\u0645\u064e\u0651 \u0644\u0627 \u062a\u062c\u0639\u0644 \u0628\u064a\u0646\u0649 \u0648\u0628\u064a\u0646\u0643 \u0641\u0649 \u0631\u0632\u0642\u0649 \u0623\u062d\u062f \u0633\u0648\u0627\u0643 \u064a\u0627 \u0623\u0643\u0631\u0645 \u0627\u0644\u0623\u0643\u0631\u0645\u064a\u0646.","\u0627\u0644\u0644\u0647\u0645 \u0627\u0646\u0627 \u0646\u0639\u0648\u0630 \u0628\u0643 \u0645\u0646 \u0641\u0648\u0627\u062c\u0639 \u0627\u0644\u0623\u0642\u062f\u0627\u0631 \u0648\u062a\u062d\u0648\u0644 \u0639\u0627\u0641\u064a\u062a\u0643.",u.fj,u.A,"\u0631\u0628 \u0625\u062c\u0639\u0644\u0646\u064a \u0645\u0642\u064a\u0645 \u0627\u0644\u0635\u0644\u0627\u0629 \u0648\u0645\u0646 \u0630\u0631\u064a\u062a\u064a \u0631\u0628\u0646\u0627 \u0648\u062a\u0642\u0628\u0644 \u062f\u0639\u0627\u0621.","\u0631\u0628\u0646\u0627 \u0622\u062a\u0646\u0627 \u0641\u064a \u0627\u0644\u062f\u0646\u064a\u0627 \u062d\u0633\u0646\u0629 \u0648\u0641\u064a \u0627\u0644\u0622\u062e\u0631\u0629 \u062d\u0633\u0646\u0629 \u0648\u0642\u0646\u0627 \u0639\u0630\u0627\u0628 \u0627\u0644\u0646\u0627\u0631.",u.k],t.s)
