B.apk=new A.h("quranHadiths_3","\u062e\u064e\u064a\u0631\u064f\u0643\u0645 \u0645\u0646 \u062a\u0639\u064e\u0644\u0645 \u0627\u0644\u0642\u0631\u0622\u0646 \u0648\u0639\u064e\u0644\u064e\u0651\u0645\u0647\u064f","\u0639\u064e\u0646 \u0639\u062b\u0645\u064e\u0627\u0646\u064e \u0628\u0646\u0650 \u0639\u064e\u0641\u0627\u0646\u064e \u0631\u064e\u0636\u064a\u064e \u0627\u0644\u0644\u0647\u064f \u0639\u0646\u0647 \u0639\u0646 \u0627\u0644\u0646\u0628\u064a\u0651\u0650 \ufdfa \u0642\u0627\u0644\u064e: \u062e\u064e\u064a\u0631\u064f\u0643\u064f\u0645 \u0645\u064e\u0646 \u062a\u064e\u0639\u064e\u0644\u0651\u064e\u0645\u064e \u0627\u0644\u0642\u064f\u0631\u0622\u0646\u064e \u0648\u0639\u064e\u0644\u0651\u064e\u0645\u064e\u0647\u064f. \u0642\u0627\u0644\u064e: \u0648\u0623\u064e\u0642\u0631\u064e\u0623\u064e \u0623\u0628\u0648 \u0639\u0628\u062f\u0650 \u0627\u0644\u0631\u0651\u064e\u062d\u0645\u064e\u0646\u0650 \u0641\u064a \u0625\u0645\u0631\u064e\u0629\u0650 \u0639\u064f\u062b\u0645\u0627\u0646\u064e\u060c \u062d\u062a\u0651\u064e\u0649 \u0643\u0627\u0646\u064e \u0627\u0644\u062d\u064e\u062c\u0651\u064e\u0627\u062c\u064f \u0642\u0627\u0644\u064e: \u0648\u0630\u0627\u0643\u064e \u0627\u0644\u0630\u064a \u0623\u0642\u0639\u064e\u062f\u064e\u0646\u0650\u064a \u0645\u064e\u0642\u0639\u064e\u062f\u0650\u064a \u0647\u0630\u0627 - \u0631\u0648\u0627\u0647 \u0627\u0644\u0628\u062e\u0627\u0631\u064a",B.aDU)
B.aOU=s(["\u0627\u0644\u062d\u064e\u0633\u064e\u062f\u064f \u0623\u0646\u0648\u0627\u0639\u064c \u0645\u062e\u062a\u0644\u0650\u0641\u0629: \u0641\u0645\u0650\u0646\u0647: \u062d\u064e\u0633\u064e\u062f\u064c \u0645\u064e\u0630\u0645\u0648\u0645\u064c \u0645\u062d\u0631\u0651\u064e\u0645\u064c \u0634\u0631\u0639\u064b\u0627\u060c \u0648\u0647\u0648 \u0623\u0646 \u064a\u064e\u062a\u0645\u0646\u0651\u064e\u0649 \u0627\u0644\u0645\u0631\u0621\u064f \u0632\u064e\u0648\u0627\u0644\u064e \u0627\u0644\u0646\u0651\u0650\u0639\u0645\u0629\u0650 \u0639\u0646 \u0623\u062e\u064a\u0647\u0650\u060c \u0648\u0645\u0646\u0647 \u062d\u064e\u0633\u064e\u062f\u064c \u0645\u064e\u062d\u0645\u0648\u062f\u064c \u0645\u064f\u0633\u062a\u062d\u064e\u0628\u0651\u064c \u0634\u0631\u0639\u064b\u0627\u060c \u0648\u0647\u0648 \u0623\u0646 \u064a\u0631\u064e\u0649 \u0646\u0650\u0639\u0645\u0629\u064b \u062f\u0650\u064a\u0646\u064a\u0651\u064e\u0629\u064b \u0639\u0646\u062f\u064e \u063a\u064a\u0631\u0650\u0647\u060c \u0641\u064a\u064e\u062a\u0645\u0646\u0651\u064e\u0627\u0647\u0627 \u0644\u0646\u0641\u0633\u0650\u0647 \u0645\u0650\u0646 \u063a\u064a\u0631\u0650 \u062a\u064e\u0645\u0646\u0651\u0650\u064a \u0632\u064e\u0648\u0627\u0644\u0650\u0647\u0627 \u0639\u0646 \u0635\u0627\u062d\u0628\u0650\u0647\u0627\u060c \u0648\u064a\u064f\u0633\u0645\u0651\u064e\u0649 \u0627\u0644\u063a\u0650\u0628\u0637\u0629\u064e\u060c \u0648\u0647\u0648 \u0645\u0627 \u0639\u064e\u0646\u064e\u0627\u0647 \u0627\u0644\u0646\u0651\u064e\u0628\u064a\u0651\u064f \ufdfa \u0641\u064a \u0647\u0630\u0627 \u0627\u0644\u062d\u064e\u062f\u064a\u062b\u0650 \u0628\u0642\u0648\u0644\u0650\u0647: \xab\u0644\u0627 \u062d\u064e\u0633\u064e\u062f\u064e \u0625\u0644\u0651\u064e\u0627 \u0641\u064a \u0627\u062b\u0646\u062a\u064e\u064a\u0646\xbb\u060c \u0623\u064a: \u0625\u0646\u0651\u064e \u0627\u0644\u062d\u0633\u062f\u064e \u0644\u0627 \u064a\u0643\u0648\u0646\u064f \u0645\u064e\u062d\u0645\u0648\u062f\u064b\u0627 \u0625\u0644\u0651\u064e\u0627 \u0641\u064a \u0623\u0645\u0631\u064e\u064a\u0646:",u.m,u.cH,"\u0648\u0641\u064a \u0627\u0644\u062d\u064e\u062f\u064a\u062b\u0650: \u062a\u0648\u062c\u064a\u0647\u064c \u0648\u0646\u0647\u064a\u064c \u0639\u0646 \u0627\u0644\u062d\u0633\u064e\u062f\u0650 \u0627\u0644\u0645\u0630\u0645\u0648\u0645\u0650\u060c \u0648\u0641\u064a\u0647: \u0623\u0646\u0651\u064e \u0627\u0644\u063a\u0646\u064a\u0651\u064e \u0625\u0630\u0627 \u0642\u0627\u0645 \u0628\u0634\u064e\u0631\u0637\u0650 \u0627\u0644\u0645\u0627\u0644\u0650\u060c \u0648\u0641\u0639\u064e\u0644 \u0641\u064a\u0647 \u0645\u0627 \u064a\u064f\u0631\u0636\u064a \u0627\u0644\u0644\u0647\u064e\u060c \u0643\u0627\u0646 \u0623\u0641\u0636\u0644\u064e \u0645\u0650\u0646 \u0627\u0644\u0641\u0642\u064a\u0631\u0650\u060c \u0648\u0641\u064a\u0647: \u0627\u0644\u0645\u0646\u0627\u0641\u0633\u0629\u064f \u0641\u064a \u0627\u0644\u062e\u064a\u0631\u0650\u060c \u0648\u0627\u0644\u062d\u0636\u0651\u064f \u0639\u0644\u064a\u0647."],t.s)
